NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Jeremiah'

CHAPTERS = {
    1: {
        1: 'Jeremian, Hilkian pojan, sanat. Hän oli Anatotin pappeja Benjaminin maasta.',
        2: 'Hänelle tuli Herran sana Juudan kuninkaan Joosian, Aamonin pojan, päivinä, tämän kolmantenatoista hallitusvuotena.',
        3: 'Se tuli vielä Juudan kuninkaan Joojakimin, Joosian pojan, päivinä ja aina Juudan kuninkaan Sidkian, Joosian pojan, yhdennentoista vuoden loppuun asti. Silloin viidentenä kuukautena Jerusalemin asukkaat vietiin karkotukseen.',
        4: 'Minulle tuli tämä Herran sana, ja se kuului:',
        5: '"Jo ennen kuin valmistin sinut kohdussa, tunsin sinut omakseni, ja ennen kuin lähdit kohdusta, pyhitin sinut, asetin sinut kansojen profeetaksi."',
        6: 'Mutta sanoin: "Voi Herra, Herra! Katso, en osaa puhua, sillä minä olen nuori."',
        7: 'Herra sanoi minulle: "Älä sano: \'Minä olen nuori\', vaan mene, minne ikinä sinut lähetän, ja puhu kaikki, mitä käsken sinun puhua.',
        8: 'Älä pelkää heitä, sillä minä olen kanssasi ja pelastan sinut, sanoo Herra."',
        9: 'Herra ojensi kätensä ja kosketti suutani, ja Herra sanoi minulle: "Katso, panen sanani suuhusi.',
        10: 'Katso, asetan sinut tänä päivänä kansoja ja valtakuntia vastaan repimään maasta ja hajottamaan, hävittämään ja kukistamaan, rakentamaan ja istuttamaan."',
        11: 'Minulle tuli tämä Herran sana, ja se kuului: "Mitä sinä näet, Jeremia?" Vastasin: "Minä näen mantelipuun oksan."',
        12: 'Herra sanoi minulle: "Olet nähnyt oikein, sillä minä valvon sanaani toteuttaakseni sen."',
        13: 'Minulle tuli toistamiseen Herran sana, näin sanoen: "Mitä sinä näet?" Vastasin: "Minä näen kiehuvan padan. Se näkyy pohjoisen puolelta."',
        14: 'Herra sanoi minulle: "Pohjoisesta onnettomuus kohtaa kaikkia tämän maan asukkaita.',
        15: 'Sillä katso, kutsun kaikki pohjoisten valtakuntien kansanheimot, sanoo Herra, ja ne tulevat ja asettavat kukin valtaistuimensa Jerusalemin porttien oville ja kaikkia sen muureja vastaan, ympäriinsä, ja kaikkia Juudan kaupunkeja vastaan.',
        16: 'Julistan heille tuomioni kaikesta heidän pahuudestaan, koska he ovat hylänneet minut, polttaneet uhreja muille jumalille ja kumartaneet kättensä tekoja.',
        17: 'Mutta sinä, vyötä lanteesi, nouse ja puhu heille kaikki, mitä minä käsken sinun puhua. Älä heitä kauhistu, etten kauhistuttaisi sinua heidän edessään.',
        18: 'Sillä katso, minä teen sinusta tänä päivänä varustetun kaupungin, rautapatsaan ja vaskimuurin koko maata vastaan, Juudan kuninkaita, sen ruhtinaita, sen pappeja ja maan kansaa vastaan.',
        19: 'Niin he sotivat sinua vastaan, mutta eivät voita sinua, sillä minä olen kanssasi, sanoo Herra, ja pelastan sinut."',
    },
    2: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Mene ja julista Jerusalemin kuullen ja sano: Näin sanoo Herra: Muistan nuoruutesi ystävällisyyden, morsiusaikasi rakkauden, kun sinä seurasit minua erämaassa, maassa, jossa ei kylvetä.',
        3: 'Herran pyhäkkö oli Israel, hänen ensisatonsa. Kaikki, jotka sitä söivät, joutuivat syynalaisiksi, ja onnettomuus kohtasi heitä, sanoo Herra.',
        4: 'Kuulkaa Herran sana, Jaakobin heimo ja kaikki Israelin huoneen sukukunnat.',
        5: 'Näin sanoo Herra: Mitä vääryyttä teidän isänne minusta löysivät, koska he loittonivat minusta kauas ja lähtivät seuraamaan turhia jumalia ja tulivat turhanpäiväisiksi?',
        6: "He eivät kysyneet: 'Missä on Herra, joka toi meidät pois Egyptin maasta, joka johdatti meitä erämaassa, arojen ja kuilujen maassa, kuivuuden ja kuoleman varjon maassa, maassa, jossa ei kukaan kulje eikä yksikään ihminen asu?'",
        7: 'Sitten toin teidät hedelmätarhojen maahan syömään sen hedelmää ja hyvyyttä, mutta sinne tultuanne saastutitte maani ja teitte perintöosani kauhistukseksi.',
        8: "Papit eivät kysyneet: 'Missä on Herra?' Lainkäyttäjät eivät minua tunteneet, paimenet luopuivat minusta, profeetat ennustivat Baalin nimessä ja seurasivat niitä, joista ei ole apua.",
        9: 'Sen tähden käyn vielä oikeutta teidän kanssanne, sanoo Herra, ja lastenne lasten kanssa käyn oikeutta.',
        10: 'Menkää kittiläisten saarille katsomaan ja lähettäkää [lähettinne] Keedariin panemaan tarkasti merkille ja katsomaan, onko sellaista tapahtunut.',
        11: 'Onko mikään pakanakansa vaihtanut jumalia, vaikka ne eivät jumalia ole? Mutta minun kansani on vaihtanut Kunniansa siihen, josta ei ole apua.',
        12: 'Hämmästykää tästä, te taivaat, kauhistukaa, aivan järkyttykää, sanoo Herra.',
        13: 'Sillä minun kansani on tehnyt kaksinkertaisen synnin: minut, elävän veden lähteen, he ovat hylänneet, ja ovat hakanneet itselleen vesisäiliöitä, särkyviä säiliöitä, jotka eivät pidä vettä.',
        14: 'Onko Israel ostettu orja tai kotona syntynyt? Minkä tähden hän on joutunut saaliiksi?',
        15: 'Häntä vastaan karjuivat nuoret leijonat, antoivat äänensä kuulua. Ne tekivät hänen maansa autioksi, hänen kaupunkinsa hävitettiin, niin ettei siinä ole asukkaita.',
        16: 'Myös noofilaiset ja tahpanheelaiset pitivät päälakeasi laitumenaan.',
        17: 'Eikö tämän tee sinulle se, että hylkäät Herran, Jumalasi, silloin kun hän tahtoo kuljettaa sinua tietä pitkin?',
        18: 'Mutta nyt, mitä menemistä Egyptiin sinulla on juomaan Siihorin vettä ja mitä menemistä Assuriin sinulla on juomaan Eufrat-virran vettä?',
        19: 'Pahuutesi tuottaa sinulle kurituksen, ja luopumuksesi saattaa sinut rangaistukseen. Niin tiedä ja näe, kuinka onnetonta ja katkeraa on, että hylkäät Herran, Jumalasi, etkä minua pelkää, sanoo Herra, Herra Sebaot.',
        20: "Sillä jo kaukaisista ajoista olet särkenyt ikeesi, katkaissut siteesi ja sanonut: 'En tahdo palvella.' Sillä kaikilla korkeilla kukkuloilla ja kaikkien vihreiden puiden alla makailit porttona.",
        21: 'Olin istuttanut sinut jaloksi viiniköynnökseksi, totuuden siemeneksi. Kuinka olet muuttunut minulle vieraan viinipuun villiköynnökseksi?',
        22: 'Vaikka pesisit itsesi saippualla ja käyttäisit paljon lipeää, saastaiseksi jää sittenkin syntisi edessäni, sanoo Herra, Herra.',
        23: "Kuinka sanot: 'En ole saastuttanut itseäni enkä kulkenut baalien perässä'! Katso menoasi laaksossa ja tiedä, mitä olet tehnyt, sinä nopea, nuori naaraskameli, joka juokset sinne tänne;",
        24: 'sinä villiaasi, erämaahan tottunut, joka ahmit himossasi ilmaa! Kuka voi sitä pidätellä? Joka sitä etsii, sen ei tarvitse väsyttää itseään. Sen löytää, kun tulee sen kuukausi.',
        25: "Varo, ettet tallaa jalkojasi paljaiksi ja kurkkuasi janoiseksi. Mutta sanot: 'Ei pelkoa! Sillä minä rakastan vieraita ja seuraan niitä.'",
        26: 'Niin kuin teosta tavattu varas on häpeissään, niin joutuu Israelin huone häpeään, se ja sen kuninkaat, ruhtinaat, papit ja profeetat,',
        27: "ne, jotka sanovat puulle: 'Sinä olet isäni' ja kivelle: 'Sinä olet minut synnyttänyt.' Sillä he ovat kääntäneet minulle selkänsä eivätkä kasvojaan. Mutta onnettomuutensa aikana he sanovat: 'Nouse ja pelasta meidät.'",
        28: 'Mutta missä ovat jumalasi, jotka olet itsellesi tehnyt? Nouskoot ne, jos voivat pelastaa sinut onnettomuutesi aikana. Sillä yhtä monta, kuin sinulla on kaupunkeja, sinulla on jumalia, Juuda.',
        29: 'Miksi riitelette minua vastaan? Olettehan te kaikki tehneet syntiä minua vastaan, sanoo Herra.',
        30: 'Turhaan olen lyönyt lapsianne. He eivät ole ottaneet kuritusta varteen. Miekkanne on syönyt profeettojanne kuin hävittävä leijona.',
        31: "Te sukukunta! Katsokaa Herran sanaa: olenko ollut Israelille erämaa, pimeyden maa? Miksi kansani sanoo: 'Me juoksemme valtoimina emmekä enää tule luoksesi.'",
        32: 'Unohtaako neitsyt korunsa, morsian koruvyönsä? Mutta minun kansani on unohtanut minut lukemattomina päivinä.',
        33: 'Kuinka ovelasti kuljet etsiessäsi rakkautta! Niinpä oletkin perehtynyt pahuuden teihin.',
        34: 'Vaatteesi liepeetkin ovat köyhien, viattomien veressä. Et tavannut heitä murtautumasta sisälle, mutta siitä huolimatta!',
        35: "Kuitenkin sanot: 'Olen syytön; hänen vihansa on kai kääntynyt minusta pois.' Katso, käyn oikeutta kanssasi, koska sanot: 'En ole tehnyt syntiä.'",
        36: 'Miksi niin täysin käännyt vaihtamaan tiesi! Egyptistäkin olet saava häpeän, niin kuin sait häpeän Assurista.',
        37: 'Senkin luota olet lähtevä kädet pääsi päällä, sillä Herra on hylännyt ne, joihin luotat, eikä heistä tule sinulle menestystä."',
    },
    3: {
        1: 'On sanottu: Katso, jos mies lähettää pois vaimonsa ja tämä lähtee hänen luotaan ja tulee toisen miehen vaimoksi, palaako mies enää hänen luokseen? Eikö maa tule saastutetuksi? Mutta sinä olet harjoittanut haureutta monen ystävän kanssa – palaa kuitenkin luokseni! – sanoo Herra.',
        2: 'Nosta silmäsi kukkuloihin ja katso: missä ei olisi sinua maattu? Teitten vieressä sinä istuit heitä odotellen kuin arabialainen erämaassa, ja saastutit maan haureudellasi ja pahuudellasi.',
        3: 'Sadekuurot tyrehtyivät, kevätsade jäi tulematta, mutta sinulla oli porttonaisen otsa, et tahtonut hävetä.',
        4: 'Kuitenkin huudat nyt minulle: "Isäni! Sinä olet nuoruuteni ystävä!',
        5: 'Pitääkö hän vihaa iankaikkisesti, kantaako hän sitä ainiaan?" Katso, näin sinä puhut, mutta teet pahaa, ja siihen sinä pystyt.',
        6: 'Herra sanoi minulle kuningas Joosian päivinä: "Oletko nähnyt, mitä tuo luopiovaimo, Israel, on tehnyt? Hän kuljeskeli kaikilla korkeilla vuorilla ja kaikkien vihreiden puiden alla ja harjoitti siellä haureutta.',
        7: "Sanoin, sitten kun hän oli kaiken tämän tehnyt: 'Palaa luokseni.' Mutta hän ei palannut, ja hänen uskoton sisarensa Juuda näki sen.",
        8: 'Näin, että vaikka olin lähettänyt pois luopiovaimo Israelin juuri sen tähden, että hän oli tehnyt aviorikoksen ja olin antanut hänelle erokirjan, uskoton Juuda, hänen sisarensa, ei kuitenkaan pelännyt, vaan meni ja harjoitti hänkin haureutta.',
        9: 'Haureutensa huudolla hän saastutti maan ja teki aviorikoksen kiven ja puun kanssa.',
        10: 'Kaikesta tästäkään huolimatta hänen uskoton sisarensa Juuda ei palannut luokseni kaikesta sydämestään, vaan petollisesti, sanoo Herra."',
        11: 'Herra sanoi minulle: "Luopiovaimo Israel on osoittautunut vanhurskaammaksi kuin uskoton Juuda.',
        12: 'Mene ja julista nämä sanat pohjoiseen päin ja sano: Palaa, sinä luopiovaimo Israel, sanoo Herra. En synkistä teille kasvojani, sillä minä olen armollinen, sanoo Herra, enkä pidä vihaa iankaikkisesti.',
        13: 'Ainoastaan tunne rikoksesi, että olet rikkonut Herraa, Jumalaasi vastaan, ja juossut sinne tänne vieraiden jumalien luo, kaikkien vihreiden puiden alle, ettekä ole kuulleet ääntäni, sanoo Herra.',
        14: 'Palatkaa takaisin, te luopiolapset, sanoo Herra, sillä minä kihlaan teidät ja otan teidät omikseni, yhden ainoankin kaupungista ja kaksi sukukunnasta, ja tuon teidät Siioniin,',
        15: 'ja annan teille paimenet oman sydämeni mukaan, ja he kaitsevat teitä tiedolla ja taidolla.',
        16: 'Kun te lisäännytte ja tulette hedelmällisiksi maassa niinä päivinä, sanoo Herra, enää ei puhuta Herran liitonarkista, se ei enää nouse mieleen, eikä sitä enää muisteta. Sen luo ei enää tulla eikä sitä enää tehdä.',
        17: 'Siihen aikaan sanotaan Jerusalemia Herran valtaistuimeksi, ja kaikki kansat kokoontuvat sinne, Jerusalemiin, Herran nimen tähden eivätkä enää vaella pahan sydämensä paatumuksessa.',
        18: 'Niinä päivinä Juudan heimo on kulkeva Israelin heimon luo, ja he tulevat yhdessä pohjoisesta maasta siihen maahan, jonka annoin isillenne perinnöksi.',
        19: 'Minä sanoin: Kuinka asetankaan sinut lasten joukkoon ja annan sinulle suloisen maan, ihanan perintöosan, pakanoiden ihanimman joukon! Sanoin: Olet sanova minua Isäksi etkä ole koskaan kääntyvä minusta pois.',
        20: 'Mutta niin kuin vaimo on uskoton puolisolleen, niin te, Israelin heimo, olette olleet uskottomat minulle, sanoo Herra.',
        21: 'Kuule! Kallioilta kuuluu itku, israelilaisten valitus, sillä he ovat vaeltaneet väärää tietä ja ovat unohtaneet Herran, Jumalansa.',
        22: 'Palatkaa takaisin, te luopuneet lapset, niin parannan teidän luopumuksenne." – "Katso, me tulemme luoksesi, sillä sinä olet Herra, Jumalamme."',
        23: 'Totisesti, petosta on, mitä kukkuloilta kuuluu, pauhina vuorilla. Totisesti, Herrassa, Jumalassamme, on Israelin pelastus.',
        24: 'Häpeäjumala on syönyt isiemme vaivannäön nuoruudestamme asti, heidän lampaansa ja nautansa, poikansa ja tyttärensä.',
        25: 'Maatkaamme häpeässämme, ja häväistyksemme peittäköön meidät, sillä Herraa, Jumalaamme, vastaan me olemme syntiä tehneet, me ja isämme, aina nuoruudestamme tähän päivään asti, emmekä ole kuulleet Herran, Jumalamme, ääntä."',
    },
    4: {
        1: '"Jos sinä, Israel, käännyt, sanoo Herra, käänny minun luokseni, ja jos sinä poistat iljetyksesi kasvojeni edestä, niin et harhaile.',
        2: "Jos vannot: 'Niin totta kuin Herra elää', totuudessa, oikeutta noudattaen ja vanhurskaasti, niin kansat siunaavat itsensä hänen nimeensä, ja hän on heidän kunniansa.",
        3: 'Sillä näin sanoo Herra Juudan miehille ja Jerusalemille: Raivatkaa itsellenne uudispelto, älkääkä kylväkö orjantappuroihin.',
        4: 'Ympärileikatkaa itsenne Herralle ja poistakaa sydämenne esinahka, te Juudan miehet ja Jerusalemin asukkaat, ettei vihani syttyisi tekojenne pahuuden tähden kuin tuli ja palaisi, eikä olisi sammuttajaa.',
        5: "Julistakaa Juudassa ja Jerusalemissa, saarnatkaa ja sanokaa: Puhaltakaa torveen kautta maan. Huutakaa täysin voimin ja sanokaa: 'Kokoontukaa, ja menkäämme varustettuihin kaupunkeihin.'",
        6: 'Nostakaa lippu Siionia kohti, paetkaa pysähtymättä, sillä minä annan tulla pohjoisesta onnettomuuden ja suuren hävityksen.',
        7: 'Leijona on noussut tiheiköstään, kansojen hävittäjä on lähtenyt liikkeelle ja lähtenyt paikaltaan tekemään maasi autioksi. Kaupunkisi hävitetään niin, ettei niissä ole asukkaita.',
        8: 'Sen tähden kääriytykää säkkeihin, valittakaa ja itkekää, sillä Herran vihan hehku ei ole kääntynyt meistä pois."',
        9: 'Sinä päivänä tapahtuu, tämä on Herran sana: kuninkaan ja ruhtinaiden rohkeus katoaa, papit kauhistuvat ja profeetat hämmästyvät.',
        10: 'Mutta minä sanoin: "Voi, Herra, Herra! Totisesti, sinä olet pettänyt tätä kansaa ja Jerusalemia, kun sanoit: \'Teillä on oleva rauha!\' Kuitenkin miekka koskee sieluun asti."',
        11: 'Siihen aikaan sanotaan tälle kansalle ja Jerusalemille: Kuuma tuuli tulee erämaan kallioilta tytärtä, kansaani, kohti – ei viljan viskaamiseksi eikä puhdistamiseksi.',
        12: 'Tuuli täydessä voimassaan tulee minulta. Nyt minä myös julistan heille tuomiot.',
        13: 'Katso, hän nousee kuin pilvet, ja hänen vaununsa ovat kuin pyörremyrsky, hänen hevosensa ovat kotkia nopeammat. Voi meitä, sillä olemme tuhon omia!',
        14: 'Pese sydämesi puhtaaksi pahuudesta, sinä Jerusalem, että pelastuisit. Kuinka kauan sisimmässäsi asuvat väärät ajatuksesi?',
        15: 'Sillä sanantuojan ääni kuuluu Daanista ja onnettomuuden julistus Efraimin vuorilta!',
        16: 'Muistuttakaa kansoja. Katso, saarnatkaa Jerusalemia vastaan: "Piirittäjät tulevat kaukaisesta maasta ja kohottavat äänensä Juudan kaupunkeja vastaan."',
        17: 'Kuin pellon vartijat he piirittävät sitä ympäriinsä, koska se kapinoi minua vastaan, sanoo Herra.',
        18: 'Vaelluksesi ja tekosi ovat tuottaneet sinulle tämän: tämän saat pahuudestasi, sillä se on katkeraa ja koskee sydämeesi asti.',
        19: 'Voi rintaani, voi rintaani! Vääntelehdin tuskasta. Voi sydämeni kammioita! Sydämeni väräjää minussa. En voi vaieta, sillä kuulen torven äänen, sotahuudon.',
        20: 'Hävitystä hävityksen päällä, sillä koko maa on tuhottu. Äkisti ovat telttani tuhotut ja telttakankaani revityt silmänräpäyksessä.',
        21: 'Kuinka kauan minun täytyy nähdä sotalippua ja kuulla torven ääntä?',
        22: 'Sillä kansani on typerä. He eivät tunne minua. He ovat tyhmiä lapsia eivätkä ymmärtäväisiä. He ovat viisaita tekemään pahaa, mutta hyvää he eivät osaa tehdä.',
        23: 'Katselin maata, ja katso, se oli autio ja tyhjä, ja katsoin taivaalle, eikä siinä ollut valoa.',
        24: 'Katselin vuoria, ja katso, ne järisivät, ja kaikki kukkulat huojuivat.',
        25: 'Katselin, ja katso, ei ollut yhtään ihmistä, ja kaikki taivaan linnut olivat paenneet pois.',
        26: 'Katselin, ja katso, hedelmätarha oli erämaana, ja kaikki sen kaupungit olivat kukistuneet Herran edessä ja hänen vihansa hehkun edessä.',
        27: 'Sillä näin sanoo Herra: Koko maa tulee autioksi, vaikka en tee siitä täysin loppua.',
        28: 'Sen tähden maa suree, ja taivaat ylhäällä pukeutuvat mustiin, sillä olen puhunut, olen päättänyt, en kadu enkä siitä peräydy.',
        29: 'Ratsu- ja jousimiesten huutoa pakenee koko kaupunki. He menevät metsän tiheikköihin ja nousevat kallioille. Jokainen kaupunki on hylätty, eikä niissä asu kukaan.',
        30: 'Mutta sinä, tuhon oma, mitä teet, kun pukeudut purppuraan, kun kaunistat itseäsi kultakoruilla ja kun suurennat silmäsi ihomaalilla? Turhaan itseäsi kaunistat. Rakastajat ovat hylänneet sinut. He etsivät henkeäsi.',
        31: 'Sillä kuulen huudon, kuin synnyttäjän tuskanhuudon, vaivan, kuin ensisynnyttäjän vaivan, tytär Siionin huudon. Hän vaikeroi ja levittää kätensä: "Voi minua, sillä sieluni menehtyy murhaajien tähden!"',
    },
    5: {
        1: 'Kiertäkää Jerusalemin katuja, katsokaa ja tiedustelkaa, ja etsikää sen toreilta. Jos löydätte yhdenkään, jos on ainoatakaan, joka tekee oikein, joka etsii totuutta, niin annan sille anteeksi.',
        2: 'Mutta vaikka he sanovat: "Niin totta kuin Herra elää", he kuitenkin vannovat väärin.',
        3: 'Herra, eivätkö silmäsi katso uskollisuutta? Olet lyönyt heitä, mutta he eivät tunteneet kipua. Olet aivan hävittänyt heidät, mutta he eivät tahtoneet ottaa kuritusta varteen. He ovat kovettaneet kasvonsa kalliota kovemmiksi eivätkä ole tahtoneet kääntyä.',
        4: 'Minä sanoin: Sellaisia ovat vain alhaiset. He ovat typeriä, sillä he eivät tunne Herran tietä eivätkä Jumalansa oikeutta.',
        5: 'Menen ylhäisten luo ja puhuttelen heitä, sillä he kyllä tuntevat Herran tien ja Jumalansa oikeuden. Mutta he olivat kaikki särkeneet ikeen ja katkaisseet siteet.',
        6: 'Sen tähden heidät surmaa metsän leijona, aavikon susi raatelee heidät, ja pantteri väijyy heidän kaupunkejaan. Kuka ikinä niistä lähtee, se raadellaan, sillä monet ovat heidän rikoksensa ja suuri on heidän luopumustensa luku.',
        7: 'Kuinka antaisin sinulle anteeksi? Lapsesi ovat hylänneet minut ja vannoneet niiden kautta, jotka eivät ole jumalia. Ravitsin heitä, mutta he tekivät aviorikoksen ja menivät joukolla porton huoneeseen.',
        8: 'He ovat hyvinruokittuja, kiimaisia oriita. He hirnuvat kukin lähimmäisensä vaimoa.',
        9: 'Enkö rankaisisi tällaisista, sanoo Herra, eikö sieluni kostaisi tällaiselle kansalle?',
        10: 'Nouskaa sen muureille ja hävittäkää, älkää kuitenkaan siitä aivan loppua tehkö. Ottakaa pois sen köynnökset, sillä ne eivät ole Herran.',
        11: 'Sillä he ovat olleet minulle aivan uskottomat, sekä Israelin heimo että Juudan heimo, sanoo Herra.',
        12: 'He ovat olleet petollisia Herraa kohtaan ja sanoneet: "Ei se ole hän! Meitä ei kohtaa onnettomuus, emmekä tule näkemään miekkaa emmekä nälkää.',
        13: 'Profeetat ovat tuulta. Herra, joka puhuu, ei ole heissä. Tämä kohtaa heitä itseään."',
        14: 'Sen tähden sanoo Herra, Jumala Sebaot, näin: Koska te tällaisia olette puhuneet, niin katso, teen sanani suussasi tuleksi ja tämän kansan polttopuiksi, ja se kuluttaa heidät.',
        15: 'Katso, tuon teitä vastaan, te Israelin heimo, kansan kaukaa, sanoo Herra. Se on horjumaton kansa, se on ikivanha kansa, kansa, jonka kieltä sinä et osaa ja jonka puhetta et käsitä.',
        16: 'Heidän viinensä on kuin avoin hauta, ja he ovat kaikki sankareita.',
        17: 'He syövät satosi ja leipäsi, syövät poikasi ja tyttäresi, syövät lampaasi ja nautasi, syövät viinipuusi ja viikunapuusi. He hävittävät miekalla varustetut kaupunkisi, joihin sinä luotat.',
        18: 'Mutta niinäkään päivinä, sanoo Herra, en tee teistä loppua.',
        19: 'Kun he kysyvät: "Miksi Herra, Jumalamme, on tehnyt meille kaiken tämän?" vastaa heille: "Niin kuin te olette hylänneet minut ja palvelleet vieraita jumalia maassanne, niin teidän täytyy palvella muukalaisia maassa, joka ei ole teidän."',
        20: 'Julistakaa tämä Jaakobin huoneessa ja kuuluttakaa se Juudassa sanoen:',
        21: 'Kuulkaa tämä, te tyhmä ja ymmärtämätön kansa, te, joilla on silmät, mutta ette näe, joilla on korvat, mutta ette kuule.',
        22: 'Ettekö pelkää minua, sanoo Herra, ettekö vapise edessäni, joka olen pannut hiekan meren rajaksi, ikuiseksi määräksi, jonka yli se ei pääse. Vaikka se kuohuu, se ei mahda mitään, ja vaikka sen aallot pauhaavat, ne eivät pääse sen yli?',
        23: 'Mutta tällä kansalla on uppiniskainen ja tottelematon sydän. He ovat poikenneet ja menneet pois.',
        24: 'He eivät sano sydämessään: "Pelätkäämme Herraa, Jumalaamme, joka antaa sateen, syyssateen ja kevätsateen ajallaan, ja säilyttää meille elonkorjuun määräviikot."',
        25: 'Pahat tekonne käänsivät nämä pois, ja syntinne estivät teitä saamasta niistä hyvää.',
        26: 'Sillä kansassani on jumalattomia. He väijyvät, niin kuin linnunpyytäjät kyykistyvät, ja asettavat ansoja ja pyydystävät ihmisiä.',
        27: 'Niin kuin häkki on täynnä lintuja, heidän huoneensa ovat täynnä petosta. Siitä he ovat tulleet suuriksi ja rikkaiksi,',
        28: 'ovat tulleet lihaviksi ja kiiltäviksi. Myös heidän ilkeät puheensa käyvät yli kaiken määrän. He eivät aja orpojen asiaa, että nämä voittaisivat, eivätkä hanki köyhille oikeutta.',
        29: 'Enkö rankaisisi näistä tällaisista, sanoo Herra, eikö sieluni kostaisi tällaiselle kansalle?',
        30: 'Kauheita ja hirvittäviä asioita tapahtuu maassa:',
        31: 'profeetat ennustavat valhetta, ja papit hallitsevat yksissä neuvoin heidän kanssaan, ja sitä kansani rakastaa. Mutta mitä teette, kun tästä tulee loppu?',
    },
    6: {
        1: 'Paetkaa, benjaminilaiset, Jerusalemista, puhaltakaa torveen Tekoassa ja nostakaa merkki Beet-Keremin kohdalle, sillä pohjoisesta nousee onnettomuus ja suuri hävitys.',
        2: 'Hävitän suloisen ja hemmotellun tytär Siionin.',
        3: 'Hänen luokseen tulee paimenia laumoineen, he pystyttävät telttansa häntä vastaan joka puolelle ja kaitsevat laumaansa kukin alallaan.',
        4: 'Pyhittäkää häntä vastaan sota. "Nouskaa ja menkäämme puolipäivän aikaan! Voi meitä, sillä päivä painuu, sillä illan varjot pitenevät!',
        5: 'Nouskaa ja menkäämme yöllä ja hävittäkäämme hänen linnansa."',
        6: 'Sillä näin sanoo Herra Sebaot: Kaatakaa puita ja luokaa valli Jerusalemia vastaan. Se on kaupunki, jolle on kostettava. Siinä on pelkkää väkivaltaa.',
        7: 'Niin kuin kaivo pitää vetensä tuoreena, niin sekin pitää pahuutensa tuoreena. Väkivaltaa ja hävitystä kuuluu sieltä. Edessäni on aina kipu ja haavat.',
        8: 'Ota ojentuaksesi, Jerusalem, ettei sieluni vieraannu sinusta ja etten tee sinua autioksi, asumattomaksi maaksi.',
        9: 'Näin sanoo Herra Sebaot: Israelin jäännöksestä pidetään jälkikorjuu kuin viinipuusta. Ojenna kätesi köynnöksiä kohti kuin viininkorjaaja.',
        10: 'Kenelle puhuisin, ketä varoittaisin, että he kuulisivat? Katso, heidän korvansa ovat ympärileikkaamattomat, he eivät voi kuunnella. Katso, Herran sana on tullut heille pilkaksi, se ei kelpaa heille.',
        11: 'Olen täynnä Herran vihaa, en jaksa sitä pidättää. Vuodata se lapsiin kadulla, myös nuorukaisjoukkoon. Sillä mies vangitaan vaimonsa kanssa ja vanhus päiviensä täydessä määrässä.',
        12: 'Heidän talonsa joutuvat vieraille, myös pellot ja vaimot, sillä ojennan käteni maan asukkaita vastaan, sanoo Herra.',
        13: 'Sillä kaikki pienistä suuriin pyytävät väärää voittoa, ja kaikki, niin profeetat kuin papitkin, harjoittavat petosta.',
        14: 'He parantavat kansani vamman kevytmielisesti sanoen: "Rauha, rauha!" vaikka rauhaa ei ole.',
        15: 'He joutuvat häpeään, sillä he ovat tehneet kauhistuksia, mutta heillä ei ole häpeän tuntoa eivätkä he osaa hävetä. Sen tähden he kaatuvat kaatuvien joukkoon ja sortuvat koston päivänä, sanoo Herra.',
        16: 'Näin on Herra sanonut: "Astukaa teille ja katsokaa ja kysykää muinaisia polkuja, kysykää, mikä on hyvä tie, ja vaeltakaa sitä, niin löydätte levon sieluillenne." Mutta he vastasivat: "Emme vaella."',
        17: 'Olen asettanut teille vartijat: "Kuunnelkaa torven ääntä." Mutta he vastasivat: "Emme kuuntele."',
        18: 'Sen tähden kuulkaa, te kansat, ja tiedä, seurakunta, mitä heille tapahtuu.',
        19: 'Kuule, maa! Katso, minä tuotan onnettomuuden tälle kansalle, heidän hankkeittensa hedelmän, sillä he eivät ole kuunnelleet sanojani, vaan ovat hylänneet lakini.',
        20: 'Mitä on minulle suitsutus, joka tulee Sabasta, ja paras kalmoruoko kaukaisesta maasta? Polttouhrinne eivät ole minulle otollisia, eivätkä teurasuhrinne minulle kelpaa.',
        21: 'Sen tähden, näin sanoo Herra: Katso, panen tälle kansalle kompastuskiviä, joihin he kompastuvat, isät ja pojat yhdessä, ja naapuri hukkuu naapurinsa kanssa.',
        22: 'Näin sanoo Herra: Katso, kansa tulee pohjoisesta maasta, suuri pakanakansa nousee maan ääriltä.',
        23: 'He käyttävät jousta ja keihästä, ovat julmat ja armahtamattomat. Heidän äänensä on kuin pauhaava meri, ja he ratsastavat hevosilla, varustettuina kuin soturi taisteluun sinua vastaan, tytär Siion.',
        24: 'Kun kuulemme siitä sanoman, kätemme herpoavat, ahdistus valtaa meidät ja tuska kuin synnyttäjän.',
        25: 'Älkää menkö vainiolle, älkää vaeltako tiellä, sillä vihollisen miekka – kauhistus on kaikkialla!',
        26: 'Tytär, kansani! Kääriydy säkkiin, vieriskele tuhkassa, pidä valittajaiset, niin kuin ainoaa poikaa itketään, katkerat valittajaiset, sillä äkkiarvaamatta käy kimppuumme hävittäjä.',
        27: 'Olen asettanut sinut kansani koettelijaksi, suojavarustukseksi, että oppisit tuntemaan ja koettelisit heidän vaelluksensa.',
        28: 'Kaikki he ovat niskoittelevia kapinoitsijoita ja liikkuvat panettelijoina. He ovat vaskea ja rautaa ja ovat kaikki kelvottomia.',
        29: 'Palkeet puhkuvat, tulesta lähtee vain lyijyä. Turhaan on heitä sulateltu ja sulateltu: pahat eivät ole erottuneet.',
        30: 'Hylkyhopeaksi heitä sanotaan, sillä Herra on heidät hylännyt.',
    },
    7: {
        1: 'Sana, joka tuli Jeremialle Herralta:',
        2: '"Seiso Herran huoneen portilla ja saarnaa sieltä tämä sana ja sano: Kuulkaa Herran sana, koko Juuda, te jotka tulette näistä porteista kumartaen rukoilemaan Herraa.',
        3: 'Näin sanoo Herra Sebaot, Israelin Jumala: Parantakaa vaelluksenne ja tehkää hyviä tekoja, niin tulette asumaan tässä paikassa.',
        4: "Älkää luottako valheen sanoihin, kun sanotaan: 'Tämä on Herran temppeli, Herran temppeli, Herran temppeli!'",
        5: 'Vaan jos te todella parannatte vaelluksenne ja tekonne, jos te todella teette oikeuden lähimmäisillenne,',
        6: 'ette sorra muukalaista, orpoa ja leskeä, ette vuodata viatonta verta tässä paikassa ettekä seuraa muita jumalia itsellenne onnettomuudeksi,',
        7: 'annan teidän asua tässä paikassa, maassa, jonka olen antanut isillenne kauan sitten ja pitkäksi aikaa.',
        8: 'Katso, te luotatte valheen sanoihin, joista ei ole hyötyä.',
        9: 'Te varastatte, tapatte, rikotte avion, vannotte väärin, poltatte uhreja Baalille ja seuraatte vieraita jumalia, joita ette tunne.',
        10: "Te tulette ja astutte eteeni tähän huoneeseen, joka on otettu nimiini, ja sanotte: 'pelastumme' – tehdäksenne yhä kaikkia näitä kauhistuksia!",
        11: 'Ryövärien luolaksiko te katsotte tämän huoneen, joka on otettu nimiini? Katso, sellaiseksi minäkin olen sen havainnut, sanoo Herra.',
        12: 'Menkääpä asuinpaikkaani, joka oli Siilossa, jossa ensin annoin nimeni asua, ja katsokaa, mitä olen sille tehnyt kansani Israelin pahuuden tähden!',
        13: 'Koska olette nyt kaikkia näitä tekoja tehneet, sanoo Herra, ettekä ole kuulleet, vaikka varhaisesta alkaen olen teille puhunut, koska ette vastanneet, vaikka teille huusin,',
        14: 'niin teen tälle huoneelle, joka on otettu nimiini, johon te luotatte, ja tälle paikalle, jonka olen antanut teille ja teidän isillenne, samoin kuin olen tehnyt Siilolle,',
        15: 'ja heitän teidät pois kasvojeni edestä, niin kuin olen heittänyt pois kaikki veljenne, kaikki Efraimin jälkeläiset.',
        16: 'Mutta sinä älä rukoile tämän kansan puolesta, älä kohota heidän puolestaan huutoa ja rukousta äläkä niillä ahdista minua, sillä en kuule sinua.',
        17: 'Etkö näe, mitä he tekevät Juudan kaupungeissa ja Jerusalemin kaduilla?',
        18: 'Lapset kokoavat puita, isät sytyttävät tulen, ja vaimot sotkevat taikinaa valmistaaksensa uhrikakkuja taivaan kuningattarelle, ja he vuodattavat juomauhreja muille jumalille tuottaakseen minulle mielipahaa.',
        19: 'Minulleko he tuottavat mielipahaa, sanoo Herra, eivätkö pikemmin itselleen, omaksi häpeäkseen?',
        20: 'Sen tähden, näin sanoo Herra, Herra: Katso, vihani ja kiivauteni on vuotava tämän paikan ylle, ihmisten, eläinten, kedon puiden ja maan hedelmän ylle, ja se palaa sammumatta."',
        21: 'Näin sanoo Herra Sebaot, Israelin Jumala: "Lisätkää polttouhrinne teurasuhreihinne ja syökää lihaa.',
        22: 'Sillä en puhunut enkä antanut käskyä isillenne poltto- ja teurasuhrista silloin, kun vein heidät pois Egyptin maasta,',
        23: 'vaan näin käskin heitä ja sanoin: Kuulkaa ääntäni, niin minä olen Jumalanne ja te olette kansani; ja vaeltakaa aina sitä tietä, jota käsken teidän vaeltaa, jotta teidän kävisi hyvin.',
        24: 'Mutta he eivät kuulleet eivätkä kallistaneet korvaansa, vaan vaelsivat oman neuvonsa mukaan, pahan sydämensä paatumuksessa, ja käänsivät minulle selkänsä eivätkä kasvojaan.',
        25: 'Siitä päivästä, jona isänne lähtivät Egyptin maasta, aina tähän päivään asti olen lähettänyt teille kaikki palvelijani, profeetat – lähettänyt varhaisesta alkaen, päivä päivältä.',
        26: 'Mutta he eivät kuulleet minua eivätkä kallistaneet minulle korvaansa, vaan he olivat niskureita ja tekivät enemmän pahaa kuin heidän isänsä.',
        27: 'Mutta kun sinä puhut heille kaiken tämän, niin he eivät kuule sinua, ja kun sinä julistat heille, he eivät sinulle vastaa.',
        28: 'Sen tähden sano heille: Tämä on kansa, joka ei kuullut Herran, Jumalansa, ääntä eikä ottanut opetusta vastaan. Kadonnut on totuus ja hävinnyt heidän suustaan.',
        29: 'Leikkaa hiuksesi ja heitä ne pois ja viritä kallioilla itkuvirsi, sillä Herra on hylännyt ja syössyt pois vihansa alaisen sukupolven.',
        30: 'Sillä Juudan miehet ovat tehneet sen, mikä on silmissäni paha, sanoo Herra. He ovat asettaneet iljetyksensä temppeliin, joka on otettu nimiini, ja saastuttaneet sen.',
        31: 'He ovat rakentaneet Toofetin uhrikukkulat Ben-Hinnomin laaksoon polttaakseen tulessa poikiaan ja tyttäriään, mitä en ole käskenyt ja mikä ei ole mieleeni noussut.',
        32: "Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota 'Toofet' ja 'Ben-Hinnomin laakso', vaan 'Murhalaakso', ja Toofetiin haudataan, kun muualla ei ole tilaa.",
        33: 'Tämän kansan ruumiit joutuvat taivaan lintujen ja maan eläinten ruuaksi, eikä kukaan pelota niitä pois.',
        34: 'Lopetan Juudan kaupungeista ja Jerusalemin kaduilta riemu- ja ilohuudot, huudon yljälle ja huudon morsiamelle, sillä maa on tuleva raunioiksi."',
    },
    8: {
        1: '"Siihen aikaan, sanoo Herra, viedään Juudan kuningasten luut, sen ruhtinaiden luut, pappien luut, profeettojen luut ja Jerusalemin asukasten luut pois heidän haudoistaan',
        2: 'ja hajotetaan auringon, kuun ja kaiken taivaan joukon eteen, joita he rakastivat ja palvelivat, joita he seurasivat, etsivät ja kumartaen rukoilivat. Niitä ei koota eikä haudata, vaan ne tulevat maan lannaksi.',
        3: 'Kuolema on oleva halutumpi kuin elämä koko sille jäännökselle, joka jää jäljelle tästä pahasta sukukunnasta, kaikissa paikoissa, mihin karkotan nämä jäljelle jääneet, sanoo Herra Sebaot.',
        4: 'Sano heille: Näin sanoo Herra: Eivätkö ne, jotka lankeavat, nouse jälleen? Eikö se, joka kääntyy pois, palaa takaisin?',
        5: 'Miksi tämä kansa, Jerusalem, kääntyy pois pysyvässä luopumuksessa? Miksi he pitävät kiinni petoksesta ja kieltäytyvät palaamasta?',
        6: 'Olen tarkkaillut ja kuunnellut: he puhuvat sitä, mikä ei ole oikein; kukaan ei kadu pahuuttaan sanoen: Mitä olen tehnyt! Kaikki he kääntyvät juoksemaan suuntaansa, niin kuin ori kiitää taisteluun.',
        7: 'Haikarakin taivaalla tietää aikansa. Metsäkyyhkynen, pääskynen ja kurki pitävät vaarin tuloajastaan, mutta kansani ei tunne Herran tuomiota.',
        8: "Kuinka saatatte sanoa: 'Olemme viisaita, ja Herran laki on kanssamme'? Totisesti! Katso, valheen työtä on tehnyt kirjanoppineiden valhekynä.",
        9: 'Viisaat saavat häpeän, kauhistuvat ja heidät vangitaan. Katso, he ovat hylänneet Herran sanan – mitä viisautta heillä on?',
        10: 'Sen tähden annan heidän vaimonsa vieraille ja heidän peltonsa valloittajille. Sillä kaikki pienimmästä suurimpaan pyytävät väärää voittoa, kaikki, sekä profeetat että papit harjoittavat petosta.',
        11: "He parantavat pinnallisesti tyttären, kansani, vamman, sanoen: 'Rauha, rauha!' vaikka ei ole rauhaa.",
        12: 'He joutuvat häpeään, sillä he ovat tehneet kauhistuksia. Heillä ei ole myöskään häpeän tuntoa eivätkä he osaa nöyrtyä. Sen tähden he kaatuvat kaatuvien joukkoon, sortuvat, kun heidän rangaistuksensa tulee, sanoo Herra.',
        13: 'Totisesti tempaan heidät pois, sanoo Herra. Rypäleitä ei ole viinipuussa eikä viikunoita viikunapuussa, ja lehtikin lakastuu. Se, mitä olen heille antanut, menee heiltä pois."',
        14: '"Miksi me istumme? Kokoontukaa! Menkäämme varustettuihin kaupunkeihin, ja olkaamme siellä hiljaa! Sillä Herra, Jumalamme, hiljentää meidät ja juottaa meille myrkkyvettä, sillä olemme tehneet syntiä Herraa vastaan."',
        15: '"Odotetaan rauhaa, mutta hyvää ei tule, ja paranemisen aikaa, mutta katso, tulee kauhu!',
        16: 'Daanista kuuluu hänen hevostensa korskunta, hänen oriittensa hirnunnasta vapisee koko maa. He tulevat ja syövät maan ja kaiken, mitä siinä on, kaupungin ja siinä asuvat.',
        17: 'Sillä katso, lähetän keskellenne käärmeitä ja myrkkyliskoja, joita ei voi lumota, ja ne purevat teitä, sanoo Herra."',
        18: 'Murheeseeni ei ole virvoitusta. Sydämeni on sairas.',
        19: 'Katso, tyttären, kansani, avunhuuto kuuluu kaukaisesta maasta: "Eikö Herra ole Siionissa, eikö siellä ole sen kuningas?" Miksi he ovat vihoittaneet minut jumalankuvillaan, muukalaisten turhilla jumalilla?',
        20: 'Ohi on elonkorjuuaika, loppunut on kesä, mutta me emme ole saaneet apua.',
        21: 'Tyttären, kansani, murtumisen tähden olen murtunut, kuljen mustissa, murhe on minut vallannut.',
        22: 'Eikö Gileadissa ole balsamia, eikö siellä ole parantajaa? Vai miksi tyttären, kansani, haavat eivät kasva umpeen?',
        23: 'Jos joku antaisi päähäni vettä ja tekisi silmäni kyynelten lähteeksi, itkisin päivät ja yöt tyttären, kansani, kaatuneita!',
    },
    9: {
        1: 'Oi, jospa joku antaisi minulle erämaassa matkamiehen yömajan, jättäisin kansani ja vaeltaisin pois heidän luotaan! Sillä he ovat kaikki avionrikkojia ja uskottomien joukko.',
        2: 'He jännittävät kielensä kuten jousen puhumaan valhetta, eivätkä käytä maassa valtaansa totuuden hyväksi, sillä he menevät pahuudesta pahuuteen, mutta minua he eivät tunne, sanoo Herra.',
        3: 'Varokaa kukin lähimmäistänne, älkää luottako yhteenkään veljeen, sillä jokainen veli pettämällä pettää ja jokainen lähimmäinen liikkuu panettelijana.',
        4: 'He pettävät toinen toistaan eivätkä puhu totta. He ovat totuttaneet kielensä puhumaan valhetta ja tehneet vääryyttä väsyksiin asti.',
        5: 'Asut vilpin keskellä. Vilpillisyydessään he eivät tahdo tuntea minua, sanoo Herra.',
        6: 'Sen tähden, näin sanoo Herra Sebaot: Katso, tutkin heidät ja koettelen heitä, sillä mitä muuta voisin tehdä tyttären, kansani, tähden?',
        7: 'Tappava nuoli on heidän kielensä, vilppiä se puhuu. Suullaan he puhuvat rauhaa lähimmäisensä kanssa, mutta sisimmässään he punovat juoniaan.',
        8: 'Enkö näistä tällaisista rankaisisi heitä, sanoo Herra, eikö sieluni kostaisi tällaiselle kansalle?',
        9: 'Nostan vuorilla itkun ja valituksen. Erämaan laitumien tähden viritän itkuvirren. Sillä ne ovat poltetut, ei kukaan siellä kulje, eivätkä ne kuule karjan ääntä. Paenneet ovat taivaan linnut ja eläimet. Ne ovat menneet pois.',
        10: 'Teen Jerusalemin kivikasaksi, sakaalien asunnoksi, ja Juudan kaupungit teen autioiksi, joissa ei ole asukkaita.',
        11: 'Kuka on viisas mies, joka tämän ymmärtää ja jolle Herran suu on puhunut, että hän sen ilmoittaisi? Minkä tähden maa on hävitetty ja poltettu kuin erämaa, jossa ei kukaan kulje?',
        12: 'Herra sanoi: "Sen tähden, että he ovat hylänneet lakini, jonka annoin heille, eivätkä ole kuulleet ääntäni eivätkä vaeltaneet sen mukaan,',
        13: 'vaan ovat vaeltaneet sydämensä paatumuksessa ja seuranneet baaleja, niin kuin heidän isänsä olivat heille opettaneet,',
        14: 'sen tähden Herra Sebaot, Israelin Jumala, sanoo näin: Katso, syötän heille, tälle kansalle, koiruohoa ja juotan heille myrkkyvettä.',
        15: 'Hajotan heidät kansojen sekaan, joita eivät he eivätkä heidän isänsä ole tunteneet, ja lähetän heidän peräänsä miekan, kunnes teen heistä lopun.',
        16: 'Näin sanoo Herra Sebaot: Ottakaa vaari, kutsukaa itkijänaisia tulemaan tänne. Lähettäkää hakemaan taitavia naisia, jotta he tulisivat,',
        17: 'kiiruhtaisivat ja virittäisivät meistä valitusvirren, niin että silmämme vuotaisivat kyyneliä ja silmäripsistämme tippuisi vesi.',
        18: 'Sillä valitushuuto kuuluu Siionista: Kuinka olemmekaan hävitetyt! Olemme joutuneet suureen häpeään, sillä meidän täytyy jättää maa, sillä kukistuneet ovat asuntomme.',
        19: 'Kuulkaa siis, te naiset, Herran sana, ottakoon korvanne vastaan hänen suunsa puheen. Opettakaa tyttärillenne valitusvirsi ja toisillenne itkuvirsi.',
        20: 'Sillä kuolema on noussut sisään ikkunoistamme ja tullut palatseihimme tuhotakseen kadulta lapset ja toreilta nuorukaiset.',
        21: 'Puhu: Näin sanoo Herra: Ihmisten ruumiita makaa maassa kuin lantaa pelloilla, kuin lyhteitä leikkaajan jäljessä, eikä ole niille korjaajaa.',
        22: 'Näin sanoo Herra: Älköön viisas kerskuko viisaudestaan, älköön voimakas kerskuko voimastaan älköönkä rikas kerskuko rikkaudestaan,',
        23: 'vaan joka kerskaa, kerskatkoon siitä, että hän on ymmärtäväinen ja tuntee minut ja että minä, Herra, teen laupeuden, oikeuden ja vanhurskauden maan päällä. Sillä sellaisiin miellyn, sanoo Herra.',
        24: 'Katso, päivät tulevat, sanoo Herra, jolloin rankaisen kaikkia, jotka ovat ympärileikattuja, mutta kuitenkin ympärileikkaamattomia:',
        25: 'Egyptiä, Juudaa, Edomia, ammonilaisia, Mooabia ja kaikkia, joiden hiukset on ohimoilta ajettu, jotka asuvat erämaassa, sillä kaikki pakanakansat ovat ympärileikkaamattomia ja koko Israelin heimo on sydämeltään ympärileikkaamaton."',
    },
    10: {
        1: 'Kuulkaa sana, jonka Herra on puhunut teitä vastaan, te Israelin heimo.',
        2: 'Näin sanoo Herra: "Älkää opetelko kulkemaan pakanoiden tietä älkääkä kauhistuko taivaan merkkejä, sillä pakanat niitä kauhistuvat.',
        3: 'Sillä kansat palvovat turhia jumalia. Nehän ovat puuta, joka hakataan metsästä, puusepän kätten tekemiä, kirveellä veistettyjä.',
        4: 'Ne koristetaan hopealla ja kullalla sekä kiinnitetään nauloilla ja vasaroilla, niin etteivät ne horju.',
        5: 'Ne ovat kuin linnunpelätin kurkkumaalla. Ne eivät puhu, kantamalla täytyy niitä kantaa, sillä ne eivät kävele. Älkää pelätkö niitä, sillä ne eivät tee pahaa, mutta eivät ne myöskään tee hyvää.',
        6: 'Ei ole ketään vertaistasi, Herra. Sinä olet suuri, ja suuri on nimesi voimassaan.',
        7: 'Kuka ei sinua pelkäisi, sinä kansojen kuningas? Sillä siihen sinä olet arvollinen. Kaikissa kansojen viisaissa ja kaikissa heidän valtakunnissaan ei ole näet ketään sinun vertaistasi.',
        8: 'He ovat kaikki typeriä ja tyhmiä, kasvatettu palvomaan turhia jumalia, jotka ovat puuta,',
        9: 'ohueksi taottua hopeaa, joka tuodaan Tarsiista, ja Uufaan kultaa, mestarin ja kultasepän kätten tekoa. Punasinistä ja punaista purppuraa on niiden puku. Taitavien tekoa ne ovat kaikki.',
        10: 'Mutta Herra on tosi Jumala. Hän on elävä Jumala ja iankaikkinen kuningas. Hänen vihastaan järisee maa, eivätkä kansat kestä hänen suuttumustaan.',
        11: 'Sanokaa heille näin: Jumalat, jotka eivät ole tehneet taivasta eivätkä maata, katoavat maan päältä ja taivaan alta.',
        12: 'Hän on tehnyt maan voimallaan, vahvistanut maanpiirin viisaudellaan ja levittänyt taivaat taidollaan.',
        13: 'Kun hän antaa äänensä kuulua, vetten pauhu käy taivaalla, ja hän nostaa pilvet maan ääristä, tekee salamat ja sateen ja tuo tuulen sen varastoista.',
        14: 'Typerä on jokainen ihminen, tietoa vailla, häpeän saa jokainen seppä veistetystä kuvasta, petosta on hänen valamansa kuva, eikä niissä ole henkeä.',
        15: 'Turhuutta ne ovat, naurettavia tekeleitä. Kun niiden rangaistus tulee, ne hukkuvat.',
        16: 'Näiden kaltainen ei ole Jaakobin osa, sillä hän on kaiken Luoja, ja Israel on hänen perintösukunsa: Herra Sebaot on hänen nimensä.',
        17: 'Kokoa omaisuutesi maasta pois, sinä, joka istut piiritettynä.',
        18: 'Sillä näin sanoo Herra: Katso, tällä kertaa linkoan pois maan asukkaat ja ahdistan heitä, niin että saavat tarpeekseen."',
        19: 'Voi minua vammani tähden! Kipeä on haavani; mutta minä sanon: Tämä on minun vaivani, minun on se kannettava.',
        20: 'Telttani on hävitetty, ja kaikki telttaköyteni ovat katkotut. Lapseni ovat lähteneet luotani, eikä niitä enää ole. Ei ole enää, kuka telttani pystyttäisi ja nostaisi seinieni kankaan.',
        21: 'Sillä paimenet olivat järjettömiä eivätkä etsineet Herraa. Sen tähden he eivät menestyneet, vaan koko heidän laumansa hajotettiin.',
        22: 'Ääni kuuluu! Katso, se tulee, suuri pauhina pohjoisesta maasta, tekemään Juudan kaupungit autioiksi, sakaalien asunnoiksi.',
        23: 'Tiedän, Herra, ettei ihmisen tie ole hänen vallassaan, eikä miehen vallassa, kuinka hän vaeltaa ja askeleensa ohjaa.',
        24: 'Kurita minua, Herra, mutta oikeuden mukaan, äläkä vihassasi, ettet tekisi minua mitättömäksi.',
        25: 'Vuodata vihasi pakanoiden päälle, jotka eivät sinua tunne, ja sukukuntien yli, jotka eivät huuda avuksi nimeäsi. Sillä he ovat syöneet Jaakobin, ovat syöneet hänet ja tehneet hänestä lopun, ja tehneet autioksi hänen asuinsijansa.',
    },
    11: {
        1: 'Sana, joka tuli Herralta Jeremialle ja kuului näin:',
        2: '"Kuulkaa tämän liiton sanat ja puhukaa ne Juudan miehille ja Jerusalemin asukkaille.',
        3: 'Sano heille: Näin sanoo Herra, Israelin Jumala: Kirottu olkoon se mies, joka ei kuule tämän liiton sanoja,',
        4: 'jonka annoin käskynä isillenne silloin, kun vein heidät pois Egyptin maasta, rautapätsistä, sanoen: Kuulkaa ääntäni ja tehkää kaikki niin, kuin käsken teidän tehdä, niin olette kansani ja minä olen Jumalanne',
        5: 'ja pidän valan, jonka olen vannonut isillenne luvaten antaa heille maan, joka vuotaa maitoa ja hunajaa, niin kuin se teillä tänäkin päivänä on." Vastasin ja sanoin: "Aamen, Herra!"',
        6: 'Herra sanoi minulle: "Saarnaa kaikki nämä sanat Juudan kaupungeissa ja Jerusalemin kaduilla ja sano: Kuulkaa tämän liiton sanat ja noudattakaa niitä.',
        7: "Sillä totisesti varoitin isiänne silloin, kun johdatin heidät pois Egyptin maasta, ja olen varoittanut varhaisesta alkaen tähän päivään saakka sanoen: 'Kuulkaa ääntäni.'",
        8: 'Mutta he eivät kuulleet eivätkä korvaansa kallistaneet, vaan vaelsivat kukin pahan sydämensä paatumuksessa. Tuotin heidän päälleen kaikki tämän liiton sanat, joita olin käskenyt heidän noudattaa, mutta joita he eivät noudattaneet."',
        9: 'Herra sanoi minulle: "Juudan miesten ja Jerusalemin asukkaiden keskuudessa on salaliitto.',
        10: 'He ovat kääntyneet takaisin ensimmäisten esi-isiensä pahoihin tekoihin, niiden, jotka kieltäytyivät kuulemasta sanojani, ja he ovat seuranneet muita jumalia ja palvelleet niitä. Israelin heimo ja Juudan heimo ovat rikkoneet liittoni, jonka tein heidän isiensä kanssa.',
        11: 'Sen tähden, näin sanoo Herra: Katso, tuotan heille onnettomuuden, josta heillä ei ole pääsyä; ja kun he minua huutavat, en kuule heitä.',
        12: 'Juudan kaupungit ja Jerusalemin asukkaat menevät ja huutavat avuksi niitä jumalia, joille he ovat polttaneet uhreja, mutta ne eivät pelasta heitä heidän onnettomuutensa aikana.',
        13: 'Sillä yhtä paljon kuin sinulla on kaupunkeja, on sinulla, Juuda, jumalia, ja yhtä paljon kuin Jerusalemissa on katuja, olette pystyttäneet alttareita häpeäjumalalle, alttareita polttaaksenne uhreja Baalille.',
        14: 'Mutta älä sinä rukoile tämän kansan puolesta, älä kohota heidän puolestaan huutoa ja rukousta, sillä en kuule, kun he minua avuksi huutavat onnettomuutensa tähden.',
        15: 'Mitä tekee rakkaani temppelissäni? Onko hänellä paljon juonia? Ottaako uhriliha sinusta pois pahuutesi? Silloin riemuitsisit!',
        16: "'Vihreä öljypuu, ihana, kaunishedelmäinen': sillä nimellä Herra kutsui sinua. Suuren jyrinän pauhatessa hän sytytti sen tuleen, ja sen oksat turmeltuivat.",
        17: 'Mutta Herra Sebaot, joka sinut istutti, on päättänyt osaksesi onnettomuuden Israelin heimon ja Juudan heimon pahuuden tähden, jota he ovat harjoittaneet ja jolla ovat vihoittaneet minut polttamalla uhreja Baalille."',
        18: 'Herra ilmoitti minulle, ja sain tietää. Silloin näytit minulle heidän hankkeensa.',
        19: 'Silloin olin kuin kesy karitsa, joka viedään teurastettavaksi, enkä ollut tiennyt heidän pitäneen neuvoa minua vastaan: "Tuhotkaamme puu hedelmineen, hävittäkäämme hänet elävien maasta, niin ettei hänen nimeään enää muisteta."',
        20: 'Mutta Herra Sebaot on vanhurskas tuomari, joka tutkii munuaiset ja sydämen. Salli minun nähdä sinun kostavan heille, sillä haltuusi olen uskonut asiani.',
        21: 'Sen tähden, näin sanoo Herra Anatotin miehistä, jotka väijyvät henkeäsi sanoen: "Älä profetoi Herran nimeen, ettet kuolisi kättemme kautta."',
        22: 'Sen tähden, näin sanoo Herra Sebaot: "Katso, kostan heille. Heidän nuoret miehensä kuolevat miekkaan, ja heidän poikansa ja tyttärensä kuolevat nälkään.',
        23: 'Heistä ei jää jäännöstä, sillä tuotan onnettomuuden Anatotin miehille heidän kostonsa vuotena."',
    },
    12: {
        1: 'Sinä, Herra, olet vanhurskas, käyn oikeutta sinua vastaan. Kuitenkin kysyn sinulta, mikä on oikeus. Miksi jumalattomien tie menestyy? Miksi kaikki uskottomat saavat elää rauhassa?',
        2: 'Sinä istutat heidät, he myös juurtuvat; he kasvavat, kantavat myös hedelmää. Heidän suussaan olet lähellä, mutta kaukana heidän sisimmästään.',
        3: 'Mutta sinä, Herra, tunnet minut, näet minut ja tutkit sydämeni, millainen se on edessäsi. Tempaa heidät pois kuin lampaat teuraiksi ja vihi heidät tapon päivää varten.',
        4: 'Kuinka kauan täytyy maan surra ja kaiken kedon ruohon kuivua? Eläimet ja linnut hukkuvat siinä asuvien pahuuden tähden, sillä nämä sanovat: "Hän ei tule näkemään loppuamme."',
        5: '"Sillä jos juokset jalkamiesten kanssa ja ne väsyttävät sinut, kuinka kävisit kilpaan hevosten kanssa? Mutta jos sinä vaarattomalla maalla oletkin turvassa, kuinka sinun käy Jordanin rantatiheikössä?',
        6: 'Sillä omat veljesikin ja isäsi huone ovat petollisia sinua kohtaan. Hekin huutavat täysin voimin jälkeesi. Älä usko heitä, vaikka he puhuttelevat sinua ystävällisesti.',
        7: 'Olen hylännyt huoneeni ja jättänyt perintöosani. Olen antanut sieluni rakkaimman hänen vihollistensa käsiin.',
        8: 'Hän, perintöosani, oli minulle kuin leijona metsässä. Hän karjui minua vastaan, sen tähden minä vihastuin häneen.',
        9: 'Onko perintöosani kirjava petolintu, jonka ympärillä on petolintuja? Menkää, kootkaa kaikki kedon eläimet ja tuokaa ne ruualle.',
        10: 'Monet paimenet ovat turmelleet viinitarhani, tallanneet peltoni, tehneet ihanan peltoni autioksi erämaaksi.',
        11: 'Se on tehty autioksi, ja se suree edessäni autiona. Koko maa on hävitetty, sillä ei ollut ketään, joka olisi pannut sitä sydämelleen.',
        12: 'Kaikkien erämaan kukkuloiden yli tulivat hävittäjät, sillä Herran miekka syö maan toisesta äärestä toiseen, eikä millään lihalla ole rauhaa.',
        13: 'He ovat kylväneet vehnää ja niittäneet ohdakkeita. He ovat nähneet vaivaa näännyksiin asti saamatta hyötyä. Niinpä saakaa häpeä sadostanne Herran vihan hehkun tähden."',
        14: 'Näin sanoo Herra kaikista pahoista naapureistani, jotka koskevat siihen perintöosaan, minkä olen antanut kansalleni Israelille: "Katso, minä tempaan heidät pois heidän maastaan, ja Juudan heimon tempaan pois heidän keskeltään.',
        15: 'Mutta tapahtuu, että sen jälkeen kun olen temmannut heidät pois, jälleen armahdan heitä ja palautan heidät, kunkin perintöosaansa ja jokaisen maahansa.',
        16: "Jos he oppivat kansani tiet, niin että vannovat nimeeni: 'Niin totta kuin Herra elää', niin kuin he opettivat kansaani vannomaan Baalin kautta, niin heidät rakennetaan kansani keskuuteen.",
        17: 'Mutta jos he eivät kuule, niin minä totisesti tempaan pois ja hukutan sellaisen kansan, sanoo Herra."',
    },
    13: {
        1: 'Herra sanoi minulle näin: "Mene ja osta itsellesi pellavavyö ja pane se vyötäisillesi, mutta älä laske sitä veteen."',
        2: 'Ostin vyön Herran sanan mukaan ja panin sen vyötäisilleni.',
        3: 'Herran sana tuli minulle toisen kerran, tämä sana:',
        4: '"Ota vyö, jonka ostit ja joka on vyötäisilläsi, ja nouse, mene Eufratille ja kätke se siellä kallion koloon."',
        5: 'Menin ja kätkin sen Eufratille, niin kuin Herra oli käskenyt minun tehdä.',
        6: 'Pitkän ajan kuluttua Herra sanoi minulle: "Nouse, mene Eufratille ja ota vyö, jonka käskin sinun kätkeä sinne."',
        7: 'Menin Eufratille, kaivoin ja otin vyön siitä paikasta, johon olin sen kätkenyt. Katso, vyö oli turmeltunut eikä kelvannut mihinkään.',
        8: 'Minulle tuli tämä Herran sana, ja se kuului:',
        9: '"Näin sanoo Herra: Samalla tavoin tuotan turmion Juudan ylpeydelle ja Jerusalemin suurelle ylpeydelle.',
        10: 'Tämä paha kansa, joka ei tahdo kuulla sanojani, joka vaeltaa sydämensä paatumuksessa, seuraa muita jumalia, palvelee ja kumartaa niitä, tulee tämän vyön kaltaiseksi, joka ei kelpaa mihinkään.',
        11: 'Sillä niin kuin vyö liittyy miehen vyötäisiin, niin liitin koko Israelin heimon ja koko Juudan heimon itseeni, sanoo Herra, että se olisi kansani, minulle maineeksi, ylistykseksi ja kirkkaudeksi; mutta he eivät totelleet.',
        12: "Sen tähden sano heille tämä sana: Näin sanoo Herra, Israelin Jumala: Jokainen leili täytetään viinillä. Mutta jos he sanovat sinulle: 'Emmekö tiedä, että jokainen leili täytetään viinillä?'",
        13: 'sano heille: Näin sanoo Herra: Katso, täytän kaikki tämän maan asukkaat, kuninkaat, jotka istuvat Daavidin valtaistuimella, papit ja profeetat ja kaikki Jerusalemin asukkaat päihtymyksellä.',
        14: 'Murskaan heidät toisiaan vasten, isät ja lapset yhdessä, sanoo Herra. En sääli, en säästä enkä armahda, niin että jättäisin heidät hävittämättä."',
        15: 'Kuulkaa, ottakaa korviinne, älkää ylpeilkö, sillä Herra on puhunut.',
        16: 'Antakaa Herralle, Jumalallenne, kunnia, ennen kuin tulee pimeä ja jalkanne loukkaantuvat vuoriin hämärässä. Silloin odotatte valoa, mutta hän muuttaa sen kuoleman varjoksi, tekee sen synkeydeksi.',
        17: 'Mutta ellette kuule tätä, niin sieluni salassa itkee sellaista ylpeyttä, itkee katkerasti, ja silmäni vuotavat kyyneliä, kun Herran lauma viedään vankeuteen.',
        18: '"Sano kuninkaalle ja kuningattarelle: Istukaa alhaiselle sijalle, sillä päästänne on pudonnut kunnian kruununne.',
        19: 'Negevin kaupungit ovat suljetut, eikä ole avaajaa. Koko Juuda on viety karkotukseen, karkotukseen koko kansa.',
        20: 'Nostakaa silmänne ja katsokaa, ne tulevat pohjoisesta. Missä on lauma, joka oli annettu haltuusi, nuo lampaasi, kunniasi?',
        21: 'Mitä sanot, kun hän kostaa sinulle? Olet opettanut heidät päälliköiksi. Eivätkö tuskat kourista sinua kuin synnyttävää vaimoa?',
        22: "Mutta jos sanot sydämessäsi: 'Miksi minulle on näin käynyt?' – suuren syntisi tähden liepeesi kohotettiin ja tehtiin väkivaltaa kantapäillesi.",
        23: 'Voiko kuusilainen muuttaa ihonsa ja pantteri pilkkunsa? Voitteko te tehdä hyvää, te pahantekoon tottuneet?',
        24: 'Hajotan heidät kuin oljenkorret erämaan tuuleen.',
        25: 'Tämä on arpasi, mitattu osasi minulta, sanoo Herra, koska olet unohtanut minut ja luottanut valheeseen.',
        26: 'Niinpä minäkin nostan sinulta liepeet kasvoillesi, ja häpeäsi näkyy.',
        27: 'Olen nähnyt aviorikoksesi, hirnumisesi, haureutesi ja iljetyksesi kedon kukkuloilla. Voi sinua, Jerusalem! Et puhdistu, et vielä pitkään aikaan."',
    },
    14: {
        1: 'Herran sana, joka tuli Jeremialle kuivuuden tähden.',
        2: '"Juuda murehtii, sen portit murtuvat ja maatuvat mustiksi, ja Jerusalemista nousee valitushuuto.',
        3: 'Heidän ylimyksensä lähettävät alaisiaan noutamaan vettä. Nämä tulevat kaivoille, eivät löydä vettä, palaavat astiat tyhjinä, ovat pettyneitä ja häpeissään ja peittävät päänsä.',
        4: 'Viljelysmaan tähden, joka halkeilee, kun ei ole satanut maassa, viljelijät ovat pettyneinä ja peittävät päänsä.',
        5: 'Peurakin poikii kedolla ja hylkää vasansa, kun ei ole mitään vihantaa.',
        6: 'Villiaasit seisovat kukkuloilla, haukkovat ilmaa kuin sakaalit. Niiden silmät ovat voipuneet, kun ei ole ruohoa."',
        7: 'Vaikka pahat tekomme todistavat meitä vastaan, tee työsi, Herra, nimesi tähden, sillä luopumuksemme ovat monet ja sinua vastaan olemme tehneet syntiä.',
        8: 'Sinä Israelin toivo, sen vapahtaja ahdingon aikana, minkä tähden olet kuin muukalainen maassa, kuin ohikulkija, joka poikkeaa vain yöpyäkseen?',
        9: 'Minkä tähden olet kuin kauhistunut mies, kuin sankari, joka ei voi pelastaa? Kuitenkin sinä olet keskellämme, Herra, ja olemme otetut sinun nimiisi. Älä jätä meitä.',
        10: 'Näin sanoo Herra tästä kansasta: Noin he mielellään harhailevat eivätkä pidätä jalkojaan. Herra ei mielly heihin. Hän muistaa nyt heidän pahat tekonsa ja kostaa heidän syntinsä.',
        11: 'Herra sanoi minulle: "Älä rukoile tämän kansan puolesta, sen hyväksi.',
        12: 'Vaikka he paastoavat, en kuule heidän huutoaan, ja vaikka he uhraavat polttouhreja ja ruokauhreja, en heihin mielly, vaan miekalla, nälällä ja rutolla minä heidät lopetan."',
        13: 'Sanoin: "Voi, Herra, Herra! Katso, profeetat sanovat heille: \'Ette tule näkemään miekkaa ettekä kärsimään nälkää, vaan annan teille vakaan rauhan tässä paikassa.\'"',
        14: 'Mutta Herra sanoi minulle: "Valhetta ennustavat profeetat nimessäni. En ole lähettänyt heitä, en käskenyt heitä enkä puhunut heille. Valhenäkyjä, turhia ennustuksia ja oman sydämensä petosta he ennustavat teille.',
        15: 'Sen tähden, näin sanoo Herra profeetoista, jotka ennustavat nimessäni, vaikka minä en ole heitä lähettänyt, ja jotka sanovat, että miekka ja nälkä eivät tule tähän maahan: miekkaan ja nälkään hukkuvat nämä profeetat.',
        16: 'Myös kansa, jolle he ennustavat, suistuu Jerusalemin kaduilla nälkään ja miekkaan, eikä kukaan heitä hautaa – ei heitä, ei heidän vaimojaan, poikiaan eikä tyttäriään. Vuodatan heidän pahuutensa heidän päälleen."',
        17: 'Sano heille tämä sana: Silmistäni vuotavat kyyneleet yötä päivää eivätkä lakkaa. Sillä neitsyt, tytär, kansani, on kovin runneltu suurta kipua tuovalla iskulla.',
        18: 'Jos kedolle lähden, katso – miekan lävistämiä! Jos tulen kaupunkiin, katso, nälkään nääntyviä! Sillä sekä profeetat että papit kiertävät maata eivätkä tiedä mitään.',
        19: 'Oletko totisesti hylännyt Juudan, kammoaako sielusi Siionia? Minkä tähden olet lyönyt meitä, niin ettemme voi parantua? Odotetaan rauhaa, mutta hyvää ei tule, paranemisen aikaa, mutta katso, tulee kauhu!',
        20: 'Herra, me tunnemme jumalattomuutemme ja isiemme pahat teot, sillä sinua vastaan olemme tehneet syntiä.',
        21: 'Älä hylkää, nimesi tähden! Älä anna kunniasi valtaistuinta häväistäväksi. Muista liittosi kanssamme äläkä sitä riko.',
        22: 'Onko pakanoiden turhista jumalista sateen antajiksi, tai taivasko antaa sadekuurot? Etkö sinä ole Herra, Jumalamme? Sinua odotamme, sillä sinä olet tehnyt tämän kaiken.',
    },
    15: {
        1: 'Herra sanoi minulle: "Vaikka Mooses ja Samuel seisoisivat edessäni, sieluni ei taipuisi tämän kansan puoleen. Aja heidät pois kasvojeni edestä, he menkööt!',
        2: "Jos he kysyvät sinulta: 'Minne meidän on mentävä?' niin vastaa heille: Näin sanoo Herra: Joka ruton oma, se ruttoon, joka miekan, se miekkaan, joka nälän, se nälkään, joka vankeuden, se vankeuteen!",
        3: 'Rankaisen heitä neljällä tuomiolla, sanoo Herra: miekan surmaamaan, koirat raahaamaan, taivaan linnut ja maan eläimet syömään ja hävittämään.',
        4: 'Panen heidät kauhistukseksi kaikille valtakunnille maan päällä Manassen, Hiskian pojan, Juudan kuninkaan, tähden, kaiken tähden, mitä hän teki Jerusalemissa.',
        5: 'Kuka säälii sinua, Jerusalem, kuka surkuttelee sinua, kuka poikkeaa kysymään, mitä rauhaasi sopii?',
        6: 'Olet hylännyt minut, sanoo Herra, olet kääntynyt pois. Olen ojentanut käteni sinua vastaan, ja hävitän sinut. Olen väsynyt armahtamaan.',
        7: 'Viskaan viskimellä heidät maan porteilla, teen heidät lapsettomiksi ja hukutan kansani, kun he eivät ole kääntyneet teiltään.',
        8: 'Heidän leskiään on oleva minulla enemmän kuin meren hiekkaa. Tuon heidän nuorukaistensa äitien kimppuun hävittäjän keskellä päivää, langetan äkkiä heidän kaupunkinsa päälle kauhun.',
        9: 'Seitsemän pojan synnyttäjä menehtyy ja huokaisee henkensä pois. Hänen aurinkonsa laski, kun vielä oli päivä. Hän joutui häpeään ja sai hävetä. Mitä heistä jää, sen annan miekalle heidän vihollistensa edessä, sanoo Herra."',
        10: 'Voi minua, äitini, kun minut synnytit riidan ja toran mieheksi koko maalle! En ole lainaksi antanut enkä lainaksi ottanut. Kuitenkin kaikki minua kiroavat.',
        11: 'Herra sanoi: "Totisesti, jäännöksenne käy hyvin. Totisesti, saatan viholliset käyttäytymään hyvin sinua kohtaan onnettomuuden ja ahdistuksen aikana.',
        12: 'Murtuuko rauta, pohjoisen rauta, ja vaski? –',
        13: 'Omaisuutesi ja aarteesi annan ryöstettäviksi, ilman hintaa kaikkien syntiesi tähden, kaikkia rajojasi myöten.',
        14: 'Panen sinut vihollistesi kanssa kulkemaan maata, jota et tunne. Sillä vihani tuli on syttynyt. Se leimuaa teitä vastaan."',
        15: 'Sinä, Herra, sen tiedät. Muista minua ja pidä minusta huoli ja kosta puolestani vainoojilleni. Älä tempaa minua pois pitkämielisyytesi tähden. Huomaa, että kannan häväistystä tähtesi.',
        16: 'Sanasi löytyivät, ja söin ne, ja sanasi olivat minulle riemu ja sydämeni ilo. Sillä minut on otettu nimiisi, Herra, Jumala Sebaot.',
        17: 'En ole istunut iloitsemassa ilonpitäjien seurassa. Kätesi tähden olen istunut yksin, sillä olet täyttänyt minut vihallasi.',
        18: 'Miksi kipuni on loputon ja haavani on paha eikä tahdo parantua? Olet minulle kuin petollinen lähde, kuin vesi, joka ei pysy.',
        19: 'Sen tähden, näin sanoo Herra: "Jos käännyt, käännän sinut, ja tulet seisomaan edessäni. Ja jos tuot esiin jaloa, et arvotonta, olet oleva suunani. He kääntyvät luoksesi, mutta sinä et käänny heidän luokseen.',
        20: 'Teen sinut vahvaksi vaskimuuriksi tätä kansaa vastaan, ja he sotivat sinua vastaan, mutta eivät voita sinua. Sillä minä olen kanssasi ja vapautan ja pelastan sinut, sanoo Herra.',
        21: 'Pelastan sinut pahojen käsistä ja päästän sinut väkivaltaisten kourista."',
    },
    16: {
        1: 'Minulle tuli tämä Herran sana, ja se kuului:',
        2: '"Älä ota itsellesi vaimoa, älköönkä sinulle tulko poikia ja tyttäriä tässä paikassa.',
        3: 'Sillä näin sanoo Herra niistä pojista ja tyttäristä, jotka syntyvät tässä paikassa, ja heidän äideistään, jotka heidät synnyttävät, ja heidän isistään, jotka heidät siittävät tässä maassa:',
        4: 'He kuolevat tuskallisiin tauteihin, heille ei pidetä valittajaisia eikä heitä haudata. He tulevat pellon lannaksi. He hukkuvat miekkaan ja nälkään, ja heidän ruumiinsa tulevat taivaan lintujen ja maan eläinten ruuaksi.',
        5: 'Sillä näin sanoo Herra: Älä mene surutaloon, älä käy valittajaisiin äläkä heitä sure, sillä otan tältä kansalta pois rauhani, armoni ja laupeuteni, sanoo Herra.',
        6: 'He kuolevat, sekä suuret että pienet, tässä maassa. Heitä ei haudata eikä heille pidetä valittajaisia. Kukaan ei viileskele ihoaan eikä aja päätään paljaaksi heidän takiaan.',
        7: 'Heille ei murreta leipää lohdutukseksi heidän surussaan kuolleen tähden, eikä heille anneta juotavaksi lohdutusmaljaa heidän isänsä ja äitinsä tähden.',
        8: 'Älä mene pitotaloon istumaan heidän kanssaan, älä syömään äläkä juomaan.',
        9: 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Katso, lopetan tästä paikasta silmienne edessä ja teidän päivinänne riemu- ja ilohuudon, huudon yljälle ja huudon morsiamelle.',
        10: "Kun ilmoitat tälle kansalle kaikki nämä sanat ja he sanovat sinulle: 'Minkä tähden Herra on julistanut meille kaiken tämän suuren onnettomuuden, ja mikä on rikoksemme, mikä syntimme, jonka olemme tehneet Herraa, Jumalaamme, vastaan?'",
        11: 'niin sano heille: Sen tähden että isänne hylkäsivät minut, sanoo Herra, ja seurasivat muita jumalia, palvelivat niitä ja kumarsivat niitä, mutta hylkäsivät minut eivätkä noudattaneet lakiani.',
        12: 'Te taas olette tehneet pahemmin kuin isänne, ja katso, te vaellatte kukin pahan sydämenne paatumuksessa kuulematta minua.',
        13: 'Heitän teidät pois tästä maasta maahan, jota te ette tunne eivätkä teidän isänne tunteneet, ja siellä te palvelette muita jumalia päivät ja yöt, sillä en anna teille armoa.',
        14: "Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota: 'Niin totta kuin Herra elää, joka johdatti israelilaiset Egyptin maasta',",
        15: "vaan: 'Niin totta kuin Herra elää, joka johdatti israelilaiset pohjoisesta maasta ja kaikista muista maista, joihin hän oli heidät karkottanut.' Sillä palautan heidät heidän omaan maahansa, jonka annoin heidän isilleen.",
        16: 'Katso, lähetän monta kalastajaa, sanoo Herra, ja he kalastavat heitä, ja sen jälkeen lähetän monta metsästäjää, ja he metsästävät heitä kaikilta vuorilta ja kaikilta kukkuloilta ja kallioiden rotkoista.',
        17: 'Sillä silmäni tarkkaavat kaikkia heidän teitään. Ne eivät ole minulta salassa, eikä heidän rikoksensa ole kätketty silmiltäni.',
        18: 'Silloin kostan ensin kaksinkertaisesti heidän rikoksensa ja syntinsä, koska he ovat saastuttaneet maani iljetystensä raadoilla ja täyttäneet perintöosani kauhistuksillaan."',
        19: 'Herra, voimani, varustukseni ja pakopaikkani hädän päivänä! Sinun luoksesi tulevat pakanat maan ääristä ja sanovat: "Petosta vain ovat perineet isämme, turhuutta, josta ei ole hyötyä.',
        20: 'Voiko ihminen tehdä itselleen jumalia? Eivät ne ole jumalia!"',
        21: '"Sen tähden, katso, saatan heidät tuntemaan – tuntemaan nyt tällä kertaa – käteni ja voimani, ja he tulevat tietämään, että nimeni on Herra."',
    },
    17: {
        1: '"Juudan synti on kirjoitettu rautapiirtimellä, timanttikärjellä, kaiverrettu heidän sydämensä tauluun ja alttarienne sarviin.',
        2: 'Heidän lapsensa muistavat alttarinsa ja aseransa vihreiden puiden vieressä korkeilla kukkuloilla.',
        3: 'Oman vuoreni, joka on kedolla, omaisuutesi, kaikki aarteesi ja uhrikukkulasi annan ryöstettäviksi synnin tähden kaikkia rajojasi myöten.',
        4: 'Sinun on luovuttava perintöosastasi, jonka olen antanut sinulle. Saatan sinut vihollistesi orjuuteen maassa, jota et tunne. Sillä olette sytyttäneet vihani tulen, ja se on palava ikuisesti.',
        5: 'Näin sanoo Herra: Kirottu on se mies, joka turvaa ihmisiin ja tekee lihan käsivarrekseen ja jonka sydän luopuu Herrasta.',
        6: 'Hän jää alastomaksi arolle eikä näe hyvän tulemista. Hän asuu poudan polttamissa paikoissa erämaassa, asumattomassa suolamaassa.',
        7: 'Siunattu on se mies, joka turvaa Herraan, jonka turvana on Herra.',
        8: 'Hän on kuin veden partaalle istutettu puu, joka lähettää juurensa puroa kohti. Helteen tuloa se ei pelästy, vaan sen lehvä on vihanta. Poutavuotenakaan sillä ei ole huolta, eikä se lakkaa tekemästä hedelmää.',
        9: 'Petollinen on sydän yli kaiken, eikä sitä voi parantaa. Kuka sen tuntee?',
        10: 'Minä, Herra, tutkin sydämen, koettelen munuaiset, ja annan jokaiselle hänen vaelluksensa mukaan, hänen tekojensa hedelmän mukaan.',
        11: 'Peltokana, joka hautoo, mitä ei ole muninut, on se, joka hankkii rikkautta vääryydellä. Päiviensä puolivälissä hänen täytyy se jättää, ja hänen loppunsa on houkan loppu."',
        12: 'Kunnian valtaistuin, korkea alusta asti, on pyhäkkömme paikka!',
        13: 'Israelin toivo, sinä Herra! Kaikki, jotka sinut hylkäävät, joutuvat häpeään. "Jotka minusta luopuvat, ne kirjoitetaan maahan. Sillä he ovat hylänneet elävän veden lähteen, Herran."',
        14: 'Paranna minut, Herra, niin paranen, pelasta minut, niin olen pelastettu. Sillä sinä olet ylistykseni.',
        15: 'Katso, he sanovat minulle: "Missä on Herran sana? Toteutukoon se!"',
        16: 'Mutta minä en ole vetäytynyt pois olemasta paimenena, en sinua seuraamasta enkä toivonut tuhon päivää, sinä tiedät sen. Se, mitä huuliltani on lähtenyt, on kasvojesi edessä.',
        17: 'Älä tule minulle kauhuksi, sinä, turvani onnettomuuden päivänä.',
        18: 'Joutukoot häpeään ne, jotka minua vainoavat, mutta älä anna minun häpeään tulla. Pelästykööt he, mutta älä anna minun pelästyä. Tuota heille onnettomuuden päivä ja tuhoa heidät kaksinkertaisella tuholla.',
        19: 'Näin sanoi Herra minulle: "Mene ja seiso Kansanportissa, josta Juudan kuninkaat tulevat ja josta he menevät, ja kaikissa Jerusalemin porteissa.',
        20: 'Sano heille: Kuulkaa Herran sana, te Juudan kuninkaat ja koko Juuda ja kaikki Jerusalemin asukkaat, jotka tulette näistä porteista.',
        21: 'Näin sanoo Herra: Ottakaa sielustanne vaari, älkää sapatinpäivänä kantako mitään taakkaa älkääkä tuoko niitä Jerusalemin porteista.',
        22: 'Älkää kantako sapatinpäivänä taloistanne mitään älkääkä tehkö mitään työtä, vaan pyhittäkää sapatinpäivä, kuten olen isillenne käskyn siitä antanut.',
        23: 'Mutta he eivät kuulleet, eivät korvaansa kallistaneet, vaan olivat niskureita, niin etteivät kuulleet eivätkä ottaneet ojennusta varteen.',
        24: 'Jos kuulette minua, sanoo Herra, niin ettette tuo sapatinpäivänä mitään kantamusta tämän kaupungin porteista, vaan pyhitätte sapatinpäivän, niin ettette silloin tee mitään työtä,',
        25: 'niin tämän kaupungin porteista tulee sisälle vaunuilla ja hevosilla ajaen kuninkaita ja ruhtinaita, jotka istuvat Daavidin valtaistuimella, he ja heidän ruhtinaansa, Juudan miehet ja Jerusalemin asukkaat tulevat, ja tämä kaupunki on oleva asuttu iankaikkisesti.',
        26: 'Juudan kaupungeista ja Jerusalemin ympäriltä, Benjaminin maasta ja Alankomaasta, Vuoristosta ja Negevistä tulee niitä, jotka tuovat polttouhreja, teurasuhreja, ruokauhreja ja suitsutusuhreja, tuovat kiitosuhreja Herran huoneeseen.',
        27: 'Mutta jos ette kuule minua ettekä pyhitä sapatinpäivää, vaan kannatte kantamuksia ja kuljette Jerusalemin porteista sapatinpäivänä, niin sytytän tuleen sen portit, ja tuli kuluttaa Jerusalemin palatsit, eikä sammu."',
    },
    18: {
        1: 'Sana, joka tuli Jeremialle Herralta ja kuului:',
        2: '"Nouse ja mene alas savenvalajan huoneeseen. Siellä annan sinun kuulla sanani."',
        3: 'Menin alas savenvalajan huoneeseen, ja katso, hän teki työtä dreijan ääressä.',
        4: 'Jos astia, jota hän valmisti, meni pilalle, niin kuin savi voi mennä savenvalajan käsissä, hän teki siitä toisen astian, miten vain savenvalaja näki parhaaksi tehdä.',
        5: 'Minulle tuli tämä Herran sana:',
        6: '"Enkö voi tehdä teille, te Israelin heimo, niin kuin tekee tuo savenvalaja, sanoo Herra. Katso, niin kuin savi on savenvalajan kädessä, niin te olette kädessäni, te Israelin heimo.',
        7: 'Yhden kerran sanon tempaavani pois, hajottavani ja hävittäväni kansan ja valtakunnan.',
        8: 'Mutta jos kansa kääntyy pois pahuudestaan, josta sille puhuin, niin kadun sitä pahaa, jota ajattelin tehdä sille.',
        9: 'Toisen kerran taas lupaan rakentaa ja istuttaa kansan ja valtakunnan;',
        10: 'mutta jos se tekee sitä, mikä on pahaa silmissäni, eikä kuule ääntäni, niin kadun sitä hyvää, jota olin luvannut tehdä sille.',
        11: 'Sano siis nyt Juudan miehille ja Jerusalemin asukkaille: Näin sanoo Herra: Katso, minä hankin teille onnettomuutta ja pidän neuvoa teitä vastaan. Kääntykää siis pois kukin pahalta tieltänne ja parantakaa vaelluksenne ja tekonne.',
        12: 'Mutta he sanovat: \'Se on turhaa! Sillä vaellamme omien neuvojemme mukaan ja teemme kukin oman pahan sydämensä paatumuksen mukaan.\'"',
        13: 'Sen tähden, näin sanoo Herra: "Kysykää kansojen keskuudessa, kuka on tällaista kuullut? Hyvin kauhistuttavia tekoja on tehnyt neitsyt Israel.',
        14: 'Lähteekö aukealta kalliolta Libanonin lumi? Ehtyvätkö kaukaa virtaavat, kylmät, kuohuvat vedet?',
        15: 'Mutta kansani on minut unohtanut. He polttavat uhreja turhille jumalille. Nämä ovat saaneet heidät kompastumaan teillään, ikivanhoilla poluilla, niin että he ovat joutuneet kulkemaan syrjäpolkuja, raivaamatonta tietä.',
        16: 'Niin he tekevät maansa kauhistukseksi, ikuiseksi ivan vihellykseksi. Jokainen, joka kulkee ohi, kauhistuu ja pudistaa päätään.',
        17: 'Kuin itätuuli hajotan heidät vihollisen edessä; näytän heille selkäni enkä kasvojani heidän hätänsä päivänä."',
        18: 'Mutta he sanoivat: "Tulkaa, pitäkäämme neuvoa Jeremiaa vastaan. Sillä ei laki lopu papilta, ei neuvo viisaalta eikä sana profeetalta. Tulkaa, lyökäämme hänet kielellä, älkäämme kuunnelko lainkaan hänen puheitaan."',
        19: 'Kuuntele sinä, Herra, minua ja kuule, mitä vastustajani puhuvat.',
        20: 'Onko hyvä pahalla kostettava, sillä he ovat kaivaneet kuopan sielulleni? Muista, kuinka olen seisonut edessäsi ja puhunut hyvää heidän puolestaan kääntääkseni heistä pois vihasi.',
        21: 'Sen tähden jätä heidän lapsensa nääntymään nälkään ja anna heidät alttiiksi miekalle, ja tulkoot heidän vaimonsa lapsettomiksi ja leskiksi, heidän miehensä surmatkoon kuolema, ja heidän nuorukaisensa kaatakoon sodassa miekka.',
        22: 'Kuulukoon huuto heidän huoneistaan, kun tuot äkkiä heidän kimppuunsa rosvojoukon. Sillä he ovat kaivaneet kuopan vangitakseen minut ja virittäneet piiloansoja jaloilleni.',
        23: 'Mutta sinä, Herra, tiedät kaikki heidän murha-aikeensa minua vastaan. Älä anna anteeksi heidän rikostaan äläkä pyyhi pois heidän syntiään kasvojesi edestä. Kaatukoot he kasvojesi edessä. Tee tämä heille vihasi aikana.',
    },
    19: {
        1: 'Herra sanoi näin: "Mene ja osta savenvalajalta ruukku ja ota mukaasi kansan ja pappien vanhimpia.',
        2: 'Lähde sitten Ben-Hinnomin laaksoon, joka on Sirpaleportin edustalla, ja julista siellä sanat, jotka puhun sinulle.',
        3: 'Sano: Kuulkaa Herran sana, te Juudan kuninkaat ja Jerusalemin asukkaat: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, tuotan sellaisen onnettomuuden tälle paikalle, että jokaisen korvat soivat, joka sen kuulee,',
        4: 'sen tähden että he ovat hylänneet minut ja muuttaneet vieraaksi tämän paikan, ovat polttaneet siinä uhreja muille jumalille, joita he eivät tunteneet, eivät he eivätkä heidän isänsä eivätkä Juudan kuninkaat, ja täyttäneet tämän paikan viattomien verellä,',
        5: 'ovat rakentaneet uhrikukkuloita Baalille ja polttaneet tulessa lapsiaan polttouhreiksi Baalille, mitä en ole käskenyt enkä puhunut ja mikä ei ole mieleeni noussut.',
        6: "Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin tätä paikkaa ei enää sanota Toofetiksi eikä Ben-Hinnomin laaksoksi, vaan 'Murhalaaksoksi.'",
        7: 'Silloin teen tyhjäksi Juudan ja Jerusalemin neuvon tässä paikassa, annan heidän kaatua miekkaan vihollistensa edessä, annan heidät niiden käsiin, jotka etsivät heidän henkeään ja annan heidän ruumiinsa ruuaksi taivaan linnuille ja maan eläimille.',
        8: 'Teen tämän kaupungin kauhistukseksi ja pilkattavaksi. Jokainen, joka kulkee ohi, kauhistuu ja viheltää kaikille sen haavoille.',
        9: 'Panen heidät syömään poikiensa ja tyttäriensä lihaa, ja he syövät toistensa lihaa siinä hädässä ja ahdistuksessa, jolla heitä ahdistavat heidän vihollisensa, ne, jotka etsivät heidän henkeään.',
        10: 'Särje ruukku niiden miesten nähden, jotka ovat tulleet kanssasi.',
        11: 'Sano heille: Näin sanoo Herra Sebaot: Näin särjen tämän kansan ja tämän kaupungin, kuin särjetään savenvalajan astia, niin ettei sitä enää saa ehjäksi. Silloin haudataan Toofetiin, kun muualla ei ole tilaa haudata.',
        12: 'Niin teen tälle paikalle, sanoo Herra, samoin sen asukkaille: teen tämän kaupungin Toofetin kaltaiseksi.',
        13: 'Jerusalemin talot ja Juudan kuningasten talot tulevat Toofetin paikan kaltaisiksi, kaikki nuo saastaiset talot, joiden katoilla he ovat polttaneet uhreja kaikelle taivaan joukolle ja vuodattaneet juomauhreja muille jumalille."',
        14: 'Jeremia tuli Toofetista, johon Herra oli lähettänyt hänet profetoimaan, ja asettui Herran huoneen esipihalle ja sanoi kaikelle kansalle:',
        15: '"Näin sanoo Herra Sebaot, Israelin Jumala: Katso, tuotan tämän kaupungin päälle ja kaikkien sen kaupunkien päälle kaiken sen onnettomuuden, jonka olen sille puhunut, koska he ovat olleet niskureita eivätkä ole kuulleet sanojani."',
    },
    20: {
        1: 'Mutta pappi Pashur, Immerin poika, joka oli Herran temppelin ylivalvoja, kuuli Jeremian profetoivan nämä sanat.',
        2: 'Niin Pashur löi profeetta Jeremiaa ja pani hänet jalkapuuhun, joka oli Herran huoneeseen kuuluvassa Benjaminin yläportissa.',
        3: 'Kun Pashur seuraavana päivänä päästi Jeremian jalkapuusta, Jeremia sanoi hänelle: " Herra ei kutsu sinua nimellä Pashur, vaan Maagor-Missabib.',
        4: 'Sillä näin sanoo Herra: Katso, teen sinut kauhistukseksi sekä itsellesi että kaikille ystävillesi; he kaatuvat vihollistensa miekkaan silmiesi nähden, ja koko Juudan annan Baabelin kuninkaan käsiin, ja hän vie heidät Baabeliin karkotukseen ja surmaa heitä miekalla.',
        5: 'Annan kaikki tämän kaupungin rikkaudet, kaiken, mitä se on saanut aikaan, kaikki sen kalleudet ja kaikki Juudan kuningasten aarteet annan heidän vihollistensa käsiin. Nämä ryöstävät ne, ottavat ne ja vievät ne Baabeliin.',
        6: 'Sinä, Pashur, ja kaikki, jotka talossasi asuvat, vaellatte vankeuteen, ja tulet Baabeliin. Sinne sinä kuolet ja sinne sinut haudataan, sinut ja kaikki ystäväsi, joille olet ennustanut valhetta."',
        7: 'Olet taivutellut minua, Herra, ja olen taipunut. Olet tarttunut minuun ja voittanut. Olen ollut nauruna kaiken päivää, ja kaikki pilkkaavat minua.',
        8: 'Sillä niin usein kuin puhun, minun täytyy itkeä, huutaa väkivaltaa ja sortoa. Sillä Herran sana on tullut minulle häväistykseksi ja pilkaksi kaiken päivää.',
        9: 'Mutta kun sanoin: "En tahdo muistella häntä enkä enää puhua hänen nimessään", sydämessäni oli kuin polttava tuli, suljettuna luihini. Väsyksiin asti yritin sitä kestää, mutta en voinut.',
        10: 'Sillä monen kuulen parjaavan. Kauhistus joka puolella! "Ilmiantakaa! Ilmiantakaamme hänet!" Kaikki ystäväni vaanivat, milloin kompastuisin: "Ehkäpä hän antaa viekoitella itsensä, niin että voitamme hänet ja saamme hänelle kostaa."',
        11: 'Mutta Herra on kanssani kuin väkevä sankari. Sen tähden vainoojani kompastuvat eivätkä voi mitään. He saavat suuren häpeän, sillä he ovat olleet ymmärtämättömiä, iankaikkisen pilkan, joka ei unohdu.',
        12: 'Herra Sebaot, sinä, joka tutkit vanhurskaan, näet munuaiset ja sydämen, salli minun nähdä, että kostat heille, sillä sinun huomaasi olen jättänyt asiani.',
        13: 'Veisatkaa Herralle, ylistäkää Herraa, sillä hän pelastaa köyhän sielun pahantekijöiden käsistä.',
        14: 'Kirottu olkoon se päivä, jona synnyin. Älköön se päivä, jona äitini minut synnytti, olko siunattu.',
        15: 'Kirottu olkoon se mies, joka toi isälleni ilosanoman, sanoen: "Sinulle on syntynyt poikalapsi", ja toi hänelle suuren ilon.',
        16: 'Käyköön sen miehen kuin niiden kaupunkien, jotka Herra kukisti armahtamatta. Hän kuulkoon huudon aamulla ja sotahuudon keskipäivän aikaan,',
        17: 'koska ei surmannut minua äidinkohtuun, niin että äitini olisi ollut hautani ja hänen kohtunsa jäänyt iäti kantavaksi.',
        18: 'Miksi olen äitini kohdusta tullut näkemään tuskaa ja vaivaa, niin että päiväni päättyvät häpeässä?',
    },
    21: {
        1: 'Sana, joka tuli Jeremialle Herralta, kun kuningas Sidkia lähetti hänen luokseen Pashurin, Malkian pojan, ja pappi Sefanjan, Maasejan pojan, sanomaan:',
        2: '"Kysy neuvoa Herralta puolestamme, sillä Nebukadressar, Baabelin kuningas, sotii meitä vastaan. Ehkäpä Herra tekee meille ihmeen, kaikkien ihmeittensä vertaisen, niin että tämä lähtee pois kimpustamme."',
        3: 'Jeremia vastasi heille: "Sanokaa Sidkialle näin:',
        4: 'Näin sanoo Herra, Israelin Jumala: Katso, käännän takaisin sota-aseet, jotka ovat käsissänne ja joilla te muurin ulkopuolella taistelette piirittäjiänne, Baabelin kuningasta ja kaldealaisia, vastaan, ja kokoan ne tämän kaupungin keskelle.',
        5: 'Minä itse sodin teitä vastaan ojennetulla kädellä ja väkevällä käsivarrella vihassa, kiivastuksessa ja suuressa suuttumuksessa.',
        6: 'Tuhoan tämän kaupungin asukkaat, ihmiset ja eläimet. He kuolevat suureen ruttoon.',
        7: 'Sen jälkeen, sanoo Herra, annan Sidkian, Juudan kuninkaan, ja hänen palvelijansa ja kansan ja ne, jotka ovat tähän kaupunkiin jääneet jäljelle rutolta, miekalta ja nälältä, Nebukadressarin, Baabelin kuninkaan, käsiin ja heidän vihollistensa käsiin, niiden, jotka etsivät heidän henkeään, ja hän surmaa heidät miekan terällä. Hän ei säästä heitä, ei sääli eikä armahda.',
        8: 'Sano tälle kansalle: Näin sanoo Herra: Katso, panen eteenne elämän tien ja kuoleman tien.',
        9: 'Joka jää tähän kaupunkiin, se kuolee miekkaan, nälkään ja ruttoon, mutta se, joka lähtee ulos ja menee kaldealaisten puolelle, jotka teitä piirittävät, jää eloon ja pitää henkensä saaliinaan.',
        10: 'Sillä olen kääntänyt kasvoni tätä kaupunkia vastaan sille onnettomuudeksi enkä onneksi, sanoo Herra. Baabelin kuninkaan käsiin se annetaan, ja hän polttaa sen tulella.',
        11: 'Sano Juudan kuninkaan huoneelle: Kuulkaa Herran sana:',
        12: 'Daavidin huone! Näin sanoo Herra: Tuomitkaa joka aamu oikeat tuomiot ja pelastakaa ryöstetty sortajan kädestä, ettei tekojenne pahuuden tähden vihani syttyisi kuin tuli ja palaisi, eikä olisi sammuttajaa.',
        13: "Katso, käyn kimppuusi, sinä laakson asujatar, sinä tasangon kalliolinna, sanoo Herra, teidän kimppuunne, jotka sanotte: 'Kuka voi astua alas meitä vastaan, kuka tulla asuntoihimme?'",
        14: 'Rankaisen teitä tekojenne hedelmän mukaan, sanoo Herra, ja sytytän tuleen kaupungin metsän, ja tuli kuluttaa kaiken, mitä on sen ympärillä."',
    },
    22: {
        1: 'Näin sanoo Herra: "Mene alas Juudan kuninkaan taloon ja puhu siellä tämä sana,',
        2: 'ja sano: Kuule Herran sana, sinä Juudan kuningas, joka istut Daavidin valtaistuimella, sinä ja palvelijasi ja kansasi, jotka käytte sisälle näistä porteista.',
        3: 'Näin sanoo Herra: Tehkää oikeus ja vanhurskaus ja pelastakaa ryöstetty sortajan kädestä. Muukalaiselle, orvolle ja leskelle älkää tehkö vääryyttä ja väkivaltaa älkääkä vuodattako viatonta verta tässä paikassa.',
        4: 'Sillä jos teette tämän sanan mukaan, niin tulee tämän linnan porteista sisälle ajaen vaunuilla ja hevosilla kuninkaita, jotka istuvat Daavidin valtaistuimella, tulee kuningas sekä hänen palvelijansa ja kansansa.',
        5: 'Mutta jos ette kuule näitä sanoja, niin vannon itseni kautta, sanoo Herra, että tämä talo on tuleva raunioiksi.',
        6: 'Sillä näin sanoo Herra Juudan kuninkaan talosta: Sinä olet minulle Gilead, olet Libanonin huippu; mutta totisesti, teen sinut erämaaksi, asumattomiksi kaupungeiksi.',
        7: 'Vihin hävittäjät sinua vastaan, kunkin aseineen, ja he hakkaavat maahan valiosetrisi ja heittävät ne tuleen.',
        8: "Monet kansat kulkevat tämän kaupungin ohi ja kysyvät toisiltaan: 'Miksi Herra on tehnyt näin tälle suurelle kaupungille?'",
        9: "Siihen vastataan: 'Siksi, että he hylkäsivät Herran, Jumalansa, liiton ja kumarsivat muita jumalia ja palvelivat niitä.'",
        10: 'Älkää kuollutta itkekö älkääkä häntä surko, vaan itkekää tuota pois kulkevaa, sillä hän ei enää palaa eikä näe synnyinmaataan.',
        11: 'Sillä näin sanoo Herra Sallumista, Joosian pojasta, Juudan kuninkaasta, joka tuli kuninkaaksi isänsä Joosian jälkeen ja joka on vaeltanut pois tästä paikasta: Hän ei enää tänne palaa;',
        12: 'vaan sinne, minne hänet on viety vangiksi, hän kuolee eikä näe enää tätä maata.',
        13: 'Voi sitä, joka ei rakenna vanhurskaudella taloaan eikä ullakkohuoneitaan oikeudella; joka ilmaiseksi teettää työtä lähimmäisellään eikä maksa hänelle hänen työstään;',
        14: "joka sanoo: 'Rakennan itselleni tilavan talon ja avarat ullakkohuoneet', joka hakkauttaa siihen ikkunat, laudoittaa sen setripuulla ja maalauttaa punavärillä.",
        15: 'Siksikö sinä olet kuningas, että sinulla on intoa setripuuhun? Eikö isäsikin syönyt ja juonut ja kuitenkin ollut oikeuden ja vanhurskauden tekijä? Silloin hänen kävi hyvin.',
        16: 'Hän hankki oikeuden kurjalle ja köyhälle. Silloin kaikki kävi hyvin. Eikö tämä juuri ole minun tuntemistani, sanoo Herra?',
        17: 'Mutta sinun silmäsi ja sydämesi eivät pyydä muuta kuin omaa voittoasi, muuta kuin vuodattaa viatonta verta ja harjoittaa väkivaltaa ja sortoa.',
        18: "Sen tähden, näin sanoo Herra Joojakimista, Joosian pojasta, Juudan kuninkaasta: Hänelle ei pidetä valittajaisia eikä huudeta: 'Voi veljeni! Voi sisareni!' Ei hänelle pidetä valittajaisia eikä huudeta: 'Voi herraamme! Voi hänen majesteettiaan!'",
        19: 'Hänet haudataan kuin aasi haudataan. Hänet raahataan pois ja viskataan Jerusalemin porttien ulkopuolelle.',
        20: 'Nouse Libanonille ja huuda, korota äänesi Baasanissa. Huuda Abarimin vuorilta, sillä kaikki sinun rakastajasi ovat murskatut.',
        21: "Puhuin sinulle onnesi päivinä. Sanoit: 'En halua kuulla.' Tämä on ollut tapasi nuoruudestasi asti: et ole kuullut ääntäni.",
        22: 'Tuuli on kaitseva kaikkia kaitsijoitasi, ja rakastajasi menevät vankeuteen. Silloin saat häpeän ja pilkan kaiken pahuutesi tähden.',
        23: 'Sinä, joka asut Libanonissa, pidät pesääsi setripuissa, kuinka oletkaan voihkiva, kun sinulle tuskat tulevat kuin synnyttäjälle kouristus!',
        24: 'Niin totta kuin minä elän, sanoo Herra: olkoon Konja, Joojakimin poika, Juudan kuningas, vaikka sinettisormus oikeassa kädessäni, sillä siitäkin repäisen sinut irti.',
        25: 'Annan sinut niiden käsiin, jotka etsivät henkeäsi, niiden käsiin, joita sinä kauhistut: Nebukadressarin, Baabelin kuninkaan, ja kaldealaisten käsiin.',
        26: 'Sitten heitän sinut ja äitisi, joka on sinut synnyttänyt, vieraalle maalle, missä ette ole syntyneet, ja sinne kuolette.',
        27: 'Mutta siihen maahan, jonne heidän sielunsa haluaa palata, he eivät palaa.',
        28: 'Onko sitten tämä mies, Konja, tarpeeton, rikottu astia? Minkä tähden hänet ja hänen jälkeläisensä on heitetty pois, viskattu pois maahan, jota eivät tunne?',
        29: 'Maa, maa, maa! Kuule Herran sana!',
        30: 'Näin sanoo Herra: Kirjoittakaa tämä mies lapsettomaksi, mieheksi, jolla ei ole onnea elinpäivinään. Sillä kenellekään hänen jälkeläisistään ei tule sitä onnea, että hän istuisi Daavidin valtaistuimella ja hallitsisi vielä Juudaa."',
    },
    23: {
        1: '"Voi paimenia, jotka tuhoavat ja hajottavat laitumeni lampaat, sanoo Herra.',
        2: 'Sen tähden näin sanoo Herra, Israelin Jumala, paimenista, jotka kaitsevat kansaani: Olette hajottaneet lampaani ja karkottaneet ne pois ettekä ole pitäneet niistä huolta. Katso, huolehdin teidän pahojen tekojenne rankaisemisesta, sanoo Herra.',
        3: 'Minä kokoan lampaitteni jäännöksen kaikista maista, joihin olen ne karkottanut, ja tuon ne takaisin laitumelleen, ja ne ovat hedelmälliset ja lisääntyvät.',
        4: 'Herätän heille paimenia, ja ne kaitsevat heitä. He eivät enää pelkää eivätkä säiky, eikä heistä puutu yhtään, sanoo Herra.',
        5: 'Katso, päivät tulevat, sanoo Herra, jolloin herätän Daavidille vanhurskaan Vesan. Hän on hallitseva kuninkaana ja menestyvä, ja hän on tekevä oikeuden ja vanhurskauden maassa.',
        6: "Hänen päivinään pelastetaan Juuda ja Israel asuu turvassa. Tämä on hänen nimensä, jolla häntä kutsutaan: ' Herra vanhurskautemme.'",
        7: "Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota: 'Niin totta kuin Herra elää, joka johdatti israelilaiset Egyptin maasta',",
        8: 'vaan: \'Niin totta kuin Herra elää, joka johdatti ja toi Israelin heimon jälkeläiset pohjoisesta maasta ja kaikista muista maista, joihin olin heidät karkottanut.\' He asuvat omassa maassaan."',
        9: 'Profeettoja vastaan. Sydämeni on murtunut rinnassani, ja kaikki luuni ovat voipuneita. Olen kuin juopunut mies, kuin sankari, jonka viini on voittanut, Herran edessä ja hänen pyhien sanojensa edessä.',
        10: '"Sillä maa on täynnä avionrikkojia, maa murehtii kirouksen tähden ja erämaan laitumet kuivuvat. Heidän pyrkimyksensä on paha ja heidän voimansa on väärä.',
        11: 'Sillä he ovat jumalattomia, niin profeetta kuin pappikin. Omasta huoneestanikin olen löytänyt heidän pahuuttaan, sanoo Herra.',
        12: 'Sen tähden heidän tiensä on oleva heille kuin liukas polku pimeässä. He suistuvat sillä ja kaatuvat. Sillä tuotan heille onnettomuuden heidän rangaistusvuotenaan, sanoo Herra.',
        13: 'Samarian profeetoissa näin pahennuksen: he ennustivat Baalin nimessä ja eksyttivät kansani Israelin.',
        14: 'Jerusalemin profeetoissa olen taas nähnyt kauhistuksia: aviorikosta ja valheessa vaeltamista. He ovat vahvistaneet pahantekijöiden käsiä, niin ettei kukaan käänny pois pahuudestaan. He ovat edessäni kaikki kuin Sodoma, ja kaupungin asukkaat kuin Gomorra.',
        15: 'Sen tähden, näin sanoo Herra Sebaot profeetoista: Katso, syötän heille koiruohoa ja juotan heille myrkkyvettä. Sillä Jerusalemin profeetoista on jumalattomuus lähtenyt koko maahan.',
        16: 'Näin sanoo Herra Sebaot: Älkää kuulko profeettojen sanoja, noiden, jotka teille ennustavat täyttäen teidät tyhjillä toiveilla. Oman sydämensä näkyjä he puhuvat, mutta eivät sitä, mikä tulee Herran suusta.',
        17: "He hokevat halveksijoilleni: ' Herra on sen sanonut: Teillä on oleva rauha!' Kaikille, jotka vaeltavat sydämensä paatumuksessa, he sanovat: 'Teitä ei kohtaa onnettomuus.'",
        18: 'Mutta kuka on seisonut Herran neuvottelussa ja nähnyt ja kuullut hänen sanansa? Kuka on kiinnittänyt huomionsa hänen sanaansa ja sitä kuunnellut?"',
        19: 'Katso, Herran myrsky, viha, puhkeaa, myrsky pyörii kohti jumalattomien päätä.',
        20: 'Eikä Herran viha käänny pois, ennen kuin hän on toteuttanut ja täyttänyt sydämensä ajatukset. Päivien lopulla te tulette sen ymmärtämään.',
        21: '"En ole lähettänyt noita profeettoja, mutta silti he juoksevat. En ole puhunut heille, mutta kuitenkin he profetoivat.',
        22: 'Jos he olisivat seisoneet neuvottelussani, niin he julistaisivat sanani kansalleni ja kääntäisivät heidät pois heidän pahalta tieltään ja pahoista teoistaan.',
        23: 'Olenko minä Jumala vain lyhyeltä matkalta, sanoo Herra. Enkö ole Jumala myös kaukaa?',
        24: 'Saattaako joku niin piiloon piiloutua, etten minä häntä näe? sanoo Herra. Enkö minä täytä taivasta ja maata? sanoo Herra.',
        25: "Olen kuullut, mitä nuo profeetat sanovat, jotka ennustavat nimessäni valhetta sanoen: 'Olen nähnyt unta, olen nähnyt unta.'",
        26: 'Kuinka kauan? Mitä noilla profeetoilla, jotka ennustavat valhetta, on mielessä? He ennustavat oman sydämensä petosta.',
        27: 'Aikovatko he unillaan, joita he kertovat toisilleen, saattaa kansani unohtamaan nimeni, niin kuin heidän isänsä unohtivat nimeni Baalin tähden?',
        28: 'Se profeetta, jolla on uni, kertokoon unensa. Mutta se, jolla on sanani, puhukoon sanani uskollisesti. Mitä tekevät oljet jyvien seassa? sanoo Herra.',
        29: 'Eikö sanani ole kuin tuli, sanoo Herra, ja kuin vasara, joka kallion murtaa?',
        30: 'Katso, sen tähden käyn niiden profeettojen kimppuun, sanoo Herra, jotka varastavat sanani toinen toiseltaan.',
        31: "Katso, käyn niiden profeettojen kimppuun, sanoo Herra, jotka ottavat sanansa omalta kieleltään, mutta sanovat: 'Hänen sanansa.'",
        32: 'Katso, käyn niiden kimppuun, jotka ennustavat valheunia, sanoo Herra, ja kertovat niitä ja eksyttävät kansaani valheillaan ja kerskumisellaan, vaikka minä en ole heitä lähettänyt enkä käskenyt ja vaikka heistä ei ole mitään hyötyä tälle kansalle, sanoo Herra.',
        33: "Kun tämä kansa tai profeetta tai pappi kysyy sinulta sanoen: 'Mikä on Herran kuorma?' niin sano heille: 'Mikä kuorma? – Teidät heitän pois', sanoo Herra.",
        34: "Sitä profeettaa, pappia ja kansaa, joka sanoo: ' Herran kuorma' – sitä miestä ja hänen huonettaan rankaisen.",
        35: "Näin sanokaa keskenänne, toinen toisellenne: 'Mitä on Herra vastannut?' ja 'Mitä on Herra puhunut?'",
        36: "Mutta ' Herran kuormaa' älkää enää mainitko, sillä kuormaksi on tuleva jokaiselle hänen oma sanansa. Te vääntelette elävän Jumalan, Herran Sebaotin, Jumalanne, sanoja.",
        37: "Näin sano profeetalle: 'Mitä on Herra sinulle vastannut? Mitä on Herra puhunut?'",
        38: "Mutta jos te sanotte: ' Herran kuorma', silloin Herra sanoo näin: Koska te sanotte tämän sanan: ' Herran kuorma', vaikka olen lähettänyt luoksenne sanomaan: Älkää sanoko: ' Herran kuorma',",
        39: 'sen tähden katso: minä unohdan kokonaan teidät ja heitän pois kasvojeni edestä teidät ja tämän kaupungin, jonka annoin teille ja isillenne,',
        40: 'ja panen päällenne iankaikkisen häpeän ja iankaikkisen pilkan, joka ei unohdu."',
    },
    24: {
        1: 'Herra näytti minulle, ja katso, kaksi viikunakoria oli asetettu Herran temppelin edustalle, sen jälkeen kun Nebukadressar, Baabelin kuningas, oli siirtänyt pois Jekonjan, Joojakimin pojan, Juudan kuninkaan, ja Juudan johtomiehet sekä sepät ja lukkosepät Jerusalemista ja vienyt heidät Baabeliin.',
        2: 'Toisessa korissa oli erittäin hyviä viikunoita, ensi sadon viikunoiden kaltaisia, ja toisessa korissa oli erittäin huonoja viikunoita, niin huonoja, ettei niitä syödä.',
        3: 'Herra sanoi minulle: "Mitä sinä näet, Jeremia?" Sanoin: "Viikunoita. Hyvät viikunat ovat erityisen hyviä, mutta huonot ovat kovin huonoja, niin huonoja, ettei niitä syödä."',
        4: 'Minulle tuli tämä Herran sana, ja se kuului:',
        5: '"Näin sanoo Herra, Israelin Jumala: Niin kuin näitä hyviä viikunoita, niin pidän hyvinä Juudan karkotettuja, jotka lähetin tästä paikasta kaldealaisten maahan.',
        6: 'Käännän katseeni heihin heidän hyväkseen, ja tuon heidät takaisin tähän maahan. Rakennan heidät enkä hajota, istutan heidät enkä revi pois.',
        7: 'Annan heille sydämen heidän tunteakseen minut, että minä olen Herra; ja he ovat kansani, ja minä olen heidän Jumalansa; sillä he kääntyvät luokseni kaikesta sydämestään.',
        8: 'Mutta kuten tehdään huonoille viikunoille, joita ei syödä niiden huonouden tähden, niin samoin, sanoo Herra, teen Sidkialle, Juudan kuninkaalle, ja hänen ruhtinailleen ja Jerusalemin jäännökselle, niille, jotka ovat jääneet jäljelle tähän maahan, ja niille, jotka asuvat Egyptin maassa:',
        9: 'Teen heidät kauhistukseksi ja onnettomuudeksi kaikille valtakunnille maan päällä, häväistykseksi ja sananparreksi, pistopuheeksi ja kirosanaksi kaikissa paikoissa, mihin heidät karkotan.',
        10: 'Lähetän heihin miekan, nälän ja ruton, kunnes he ovat hävinneet siitä maasta, jonka annoin heille ja heidän isilleen."',
    },
    25: {
        1: 'Sana, joka tuli Jeremialle ja koko Juudan kansalle, Joojakimin, Joosian pojan, Juudan kuninkaan, neljäntenä vuotena, se on Nebukadressarin, Baabelin kuninkaan, ensimmäisenä vuotena –',
        2: 'sana, jonka profeetta Jeremia lausui koko Juudan kansaa ja kaikkia Jerusalemin asukkaita vastaan sanoen:',
        3: 'Joosian, Aamonin pojan, Juudan kuninkaan, kolmannestatoista vuodesta alkaen tähän päivään asti – kaksikymmentä kolme vuotta – on Herran sana tullut minulle, ja olen puhunut teille aamuvarhaisesta alkaen, mutta te ette ole kuulleet.',
        4: 'Herra on lähettänyt luoksenne kaikki palvelijansa, profeetat, aamuvarhaisesta alkaen, mutta te ette ole kuulleet ettekä kallistaneet korvaanne kuullaksenne,',
        5: 'kun he sanoivat: "Kääntykää itse kukin pahalta tieltänne ja pahoista teoistanne, niin tulette asumaan maassa, jonka Herra on antanut teille ja isillenne, iankaikkisesta iankaikkiseen.',
        6: 'Älkää seuratko muita jumalia, älkää palvelko ja kumartako niitä älkääkä vihoittako minua kättenne teoilla, etten tuottaisi teille onnettomuutta." –',
        7: '"Mutta ette kuulleet minua, sanoo Herra, ja niin vihoititte minut kättenne töillä omaksi onnettomuudeksenne.',
        8: 'Sen tähden näin sanoo Herra Sebaot: Koska ette ole kuulleet sanojani,',
        9: 'katso, lähetän sanan, nostan kaikki pohjoiset kansanheimot, sanoo Herra, sanan Nebukadressarille, Baabelin kuninkaalle, palvelijalleni, ja tuon heidät tätä maata ja sen asukkaita vastaan ja kaikkia näitä ympärillä olevia kansoja vastaan. Nämä vihin tuhon omiksi ja teen heidät kauhistukseksi, ivatuiksi ja ikuisiksi raunioiksi.',
        10: 'Hävitän heidän keskuudestaan riemu- ja ilohuudon, huudon yljälle ja huudon morsiamelle, käsikivien äänen ja lampun valon.',
        11: 'Koko tämä maa tulee raunioiksi ja autioksi. Nämä kansat palvelevat Baabelin kuningasta seitsemänkymmentä vuotta.',
        12: 'Mutta kun seitsemänkymmentä vuotta on täyttynyt, niin kostan Baabelin kuninkaalle ja sille kansalle – sanoo Herra – heidän pahat tekonsa, kostan kaldealaisten maalle ja hävitän sen ikuisesti.',
        13: 'Tuotan sen maan päälle kaikki sanani, jotka olen puhunut sitä vastaan, kaiken, mitä tähän kirjaan on kirjoitettu, mitä Jeremia on profetoinut kaikkia niitä kansoja vastaan.',
        14: 'Sillä hekin palvelevat monia kansoja ja suuria kuninkaita, ja maksan heille heidän tekojensa ja kättensä tekojen mukaan."',
        15: 'Sillä näin sanoi Herra, Israelin Jumala, minulle: "Ota tämä vihan viinin malja kädestäni ja juota sillä kaikki kansat, joiden luo sinut lähetän.',
        16: 'He juovat ja horjuvat ja tulevat mielettömiksi miekan edessä, jonka lähetän heidän keskelleen."',
        17: 'Otin maljan Herran kädestä ja juotin kaikkia kansoja, joiden luo Herra minut lähetti:',
        18: 'Jerusalemia ja Juudan kaupunkeja, sen kuninkaita ja ruhtinaita tehdäkseni heidät raunioiksi, kauhistukseksi, ivatuksi ja kiroukseksi, kuin on tänä päivänä;',
        19: 'faraota, Egyptin kuningasta, ja hänen palvelijoitaan ja ruhtinaitaan ja koko hänen kansaansa;',
        20: 'kaikkea sekakansaa ja kaikkia Uusin maan kuninkaita ja kaikkia filistealaisten maan kuninkaita ja Askelonia, Gassaa, Ekronia ja Asdodin jäännöstä;',
        21: 'Edomia, Mooabia ja ammonilaisia;',
        22: 'kaikkia Tyyron kuninkaita ja kaikkia Siidonin kuninkaita ja rantamaan kuninkaita, jotka ovat meren tuolla puolen;',
        23: 'Dedania, Teemaa ja Buusia ja kaikkia, joiden ohimoilta hiukset on ajettu;',
        24: 'kaikkia Arabian kuninkaita ja kaikkia sekakansan kuninkaita, jotka asuvat erämaassa;',
        25: 'kaikkia Simrin kuninkaita, kaikkia Eelamin kuninkaita ja kaikkia Meedian kuninkaita;',
        26: 'kaikkia pohjoisen kuninkaita, läheisiä ja kaukaisia, toista toisensa jälkeen, ja kaikkia maan valtakuntia, mitä maan päällä on. Heidän jälkeensä on Seesakin kuningas juova.',
        27: '"Sano heille: Näin sanoo Herra Sebaot, Israelin Jumala: Juokaa ja juopukaa, oksentakaa ja kaatukaa, älkääkä enää nousko, – miekan edessä, jonka minä lähetän keskellenne.',
        28: 'Mutta jos he eivät tahdo ottaa maljaa kädestäsi ja juoda, niin sano heille: Näin sanoo Herra Sebaot: Teidän täytyy juoda.',
        29: 'Sillä, katso, siitä kaupungista alkaen, joka on otettu nimiini, minä aloitan onnettomuuden tuottamisen, ja tekö jäisitte rankaisematta! Te ette jää rankaisematta, sillä minä kutsun miekan kaikkia maan asukkaita vastaan, sanoo Herra Sebaot.',
        30: 'Mutta profetoi sinä heille kaikki nämä sanat ja sano heille: Herra huutaa korkeudesta, antaa äänensä kaikua pyhästä asunnostaan. Hän totisesti huutaa yli laitumensa. Hän nostaa huudon kuin viinikuurnan polkijat kaikkia maan asukkaita vastaan.',
        31: 'Pauhina käy maan ääriin asti, sillä Herralla on riita-asia kansoja vastaan, hän käy oikeutta kaiken lihan kanssa, ja antaa jumalattomat miekalle alttiiksi, sanoo Herra.',
        32: 'Näin sanoo Herra Sebaot: Katso, onnettomuus kulkee kansasta kansaan, ja suuri myrsky nousee maan ääristä.',
        33: 'Herran surmaamia on oleva sinä päivänä maan äärestä maan ääreen. Heille ei pidetä valittajaisia, heitä ei koota eikä haudata; he jäävät lannaksi maan pinnalle.',
        34: 'Itkekää, paimenet, ja huutakaa, vieriskelkää tuhkassa, te lauman johtajat; sillä teidän teuraaksi joutumisen päivänne ovat tulleet täyteen. Hajoatte pirstaleiksi, kaadutte kuin arvokas astia.',
        35: 'Mennyt on paimenilta pakopaikka ja pelastus lauman johtajilta.',
        36: 'Kuule paimenten huutoa, lauman johtajien valitusta! Sillä Herra hävittää heidän laumansa.',
        37: 'Heidän rauhalliset laitumensa ovat tuhoutuneet Herran vihan hehkusta.',
        38: 'Hän on lähtenyt kuin nuori leijona pensaikostaan. Heidän maansa on tullut autioksi hävittäjän vihan hehkusta, Herran vihan hehkusta."',
    },
    26: {
        1: 'Joojakimin, Joosian pojan, Juudan kuninkaan, hallituksen alussa tuli Herralta tämä sana:',
        2: '"Näin sanoo Herra: Asetu Herran temppelin esipihaan ja puhu kaikkia Juudan kaupunkeja vastaan, jotka tulevat kumartaen rukoilemaan Herran temppeliin, kaikki ne sanat, jotka olen käskenyt sinun sanoa heille. Älä jätä pois sanaakaan.',
        3: 'Ehkäpä he kuulevat ja kääntyvät itse kukin pois pahalta tieltään, ja kadun sitä onnettomuutta, jonka olin aikonut tuottaa heille heidän pahojen tekojensa tähden.',
        4: 'Sano heille: Näin sanoo Herra: Jos ette kuule minua ja vaella laissani, jonka olen teille antanut,',
        5: 'ettekä kuule palvelijoitteni, profeettojen, sanoja, niiden, jotka minä olen lähettänyt teille, varhaisesta aamusta alkaen, vaikka ette ole kuulleet heitä,',
        6: 'niin teen tälle huoneelle kuin Siilolle, ja teen tämän kaupungin kirosanaksi kaikille maan kansoille."',
        7: 'Papit ja profeetat ja koko kansa kuulivat Jeremian puhuvan nämä sanat Herran huoneessa.',
        8: 'Kun Jeremia oli puhunut loppuun kaiken, minkä Herra oli käskenyt hänen puhua kaikelle kansalle, papit ja profeetat ja koko kansa ottivat hänet kiinni sanoen: "Sinun on kuolemalla kuoltava!',
        9: 'Miksi olet profetoinut Herran nimessä sanoen: Tälle huoneelle käy kuin Siilolle, ja tämä kaupunki on tuleva autioksi eikä siinä ole asukkaita?" Kaikki kansa kokoontui Jeremiaa vastaan Herran huoneeseen.',
        10: 'Kun Juudan ruhtinaat tämän kuulivat, he nousivat kuninkaan palatsista Herran temppeliin ja istuivat Herran uuden portin ovelle.',
        11: 'Papit ja profeetat sanoivat ruhtinaille ja kaikelle kansalle näin: "Kuolemantuomio tälle miehelle! Sillä hän on profetoinut tätä kaupunkia vastaan, kuten olette omin korvin kuulleet."',
        12: 'Mutta Jeremia sanoi kaikille ruhtinaille ja kaikelle kansalle näin: " Herra lähetti minut profetoimaan tätä huonetta ja tätä kaupunkia vastaan kaikki ne sanat, jotka olette kuulleet.',
        13: 'Parantakaa siis nyt vaelluksenne ja tekonne ja kuulkaa Herran, Jumalanne, ääntä, niin Herra katuu sitä onnettomuutta, jonka hän on teille puhunut.',
        14: 'Mutta katso, minä olen teidän käsissänne. Tehkää minulle, minkä katsotte hyväksi ja oikeaksi.',
        15: 'Mutta se totisesti tietäkää, että te, jos minut surmaatte, saatatte viattoman veren päällenne ja tämän kaupungin ja sen asukkaiden päälle, sillä totisesti Herra lähetti minut luoksenne puhumaan kaikki nämä sanat korvienne kuullen."',
        16: 'Silloin ruhtinaat ja kaikki kansa sanoivat papeille ja profeetoille: "Ei kuoleman tuomiota tälle miehelle! Sillä hän on puhunut meille Herran, Jumalamme, nimessä."',
        17: 'Muutamat maan vanhimmista nousivat ja sanoivat kaikelle kansan joukolle näin:',
        18: '"Miika, mooresetilainen, ennusti Hiskian, Juudan kuninkaan, päivinä ja sanoi kaikelle Juudan kansalle näin: Näin sanoo Herra Sebaot: \'Siion kynnetään pelloksi, ja Jerusalem tulee kivikasaksi ja temppelivuori metsäkukkulaksi.\'',
        19: 'Surmasivatko hänet tosiaan silloin Hiskia, Juudan kuningas, ja koko Juuda? Eikö hän pelännyt Herraa ja lepyttänyt häntä, niin että Herra katui sitä onnettomuutta, jonka hän oli heille puhunut? Mutta mekö tuottaisimme suuren onnettomuuden sieluillemme?"',
        20: 'Mutta oli toinenkin mies, joka profetoi Herran nimessä: Uuria, Semajan poika, Kirjat-Jearimista. Hän profetoi tätä kaupunkia ja tätä maata vastaan aivan kuin Jeremia.',
        21: 'Kun kuningas Joojakim ja kaikki hänen sankarinsa ja kaikki ruhtinaat kuulivat hänen sanansa, niin kuningas etsi häntä tappaakseen. Sen kuultuaan Uuria pelästyi, pakeni ja meni Egyptiin.',
        22: 'Mutta kuningas Joojakim lähetti miehiä Egyptiin: Elnatanin, Akborin pojan, ja muita hänen kanssaan Egyptiin.',
        23: 'He toivat Uurian Egyptistä ja veivät hänet kuningas Joojakimin eteen. Tämä surmautti hänet miekalla ja heitätti hänen ruumiinsa tavallisen kansan hautaan.',
        24: 'Mutta Ahikamin, Saafanin pojan, käsi oli Jeremian suojana, niin ettei häntä jätetty kansan käsiin surmattavaksi.',
    },
    27: {
        1: 'Joojakimin, Joosian pojan, Juudan kuninkaan, hallituksen alussa tuli Herralta tämä sana Jeremialle:',
        2: 'Näin Herra sanoi minulle: "Tee itsellesi ikeet siteineen ja pane ne niskasi päälle.',
        3: 'Lähetä ne Edomin kuninkaalle, Mooabin kuninkaalle, ammonilaisten kuninkaalle, Tyyron kuninkaalle ja Siidonin kuninkaalle niiden lähettiläiden mukana, jotka ovat tulleet Jerusalemiin Sidkian, Juudan kuninkaan, luo.',
        4: 'Käske heidän sanoa herroilleen: Näin sanoo Herra Sebaot, Israelin Jumala: Näin sanokaa herroillenne:',
        5: 'Minä olen tehnyt maan sekä ihmiset ja eläimet, jotka maan päällä ovat, suurella voimallani ja ojennetulla käsivarrellani, ja annan sen sille, kenelle näen sen oikeaksi antaa.',
        6: 'Nyt minä annan kaikki nämä maat Nebukadnessarin, Baabelin kuninkaan, palvelijani, käsiin, ja myös kedon eläimet annan hänelle palvelemaan häntä.',
        7: 'Kaikki kansat palvelevat häntä ja hänen poikaansa ja hänen poikansa poikaa, kunnes tulee hänenkin maansa aika ja monet kansat ja suuret kuninkaat tekevät hänet palvelijakseen.',
        8: 'Mutta sitä kansaa ja sitä valtakuntaa, joka ei tahdo palvella häntä, Nebukadnessaria, Baabelin kuningasta, ja joka ei anna niskaansa Baabelin kuninkaan ikeeseen, sitä kansaa minä rankaisen miekalla, nälällä ja rutolla, sanoo Herra, kunnes teen heistä lopun hänen kädellään.',
        9: "Mutta te, älkää kuulko profeettojanne, tietäjiänne, unianne, ennustelijoitanne ja velhojanne, jotka sanovat teille näin: 'Ette joudu palvelemaan Baabelin kuningasta.'",
        10: 'Sillä valhetta he profetoivat teille ja toimittavat teidät kauas pois maastanne. Karkotan teidät, ja te hukutte.',
        11: 'Mutta sen kansan, joka taivuttaa niskansa Baabelin kuninkaan ikeen alle ja palvelee häntä, annan jäädä omaan maahansa, sanoo Herra. Se viljelee sitä ja asuu siinä."',
        12: 'Sidkialle, Juudan kuninkaalle, puhuin kaikki nämä sanat sanoen: Taivuttakaa niskanne Baabelin kuninkaan ikeen alle ja palvelkaa häntä ja hänen kansaansa, niin pysytte elossa.',
        13: 'Miksi teidän pitäisi kuolla, sinun ja sinun kansasi, miekkaan, nälkään ja ruttoon, niin kuin Herra on puhunut sille kansalle, joka ei tahdo palvella Baabelin kuningasta?',
        14: 'Älkää kuulko niiden profeettojen sanoja, jotka sanovat teille näin: "Te ette joudu palvelemaan Baabelin kuningasta"; sillä valhetta he profetoivat teille.',
        15: 'Sillä en ole lähettänyt heitä, sanoo Herra, vaan he profetoivat minun nimessäni valhetta ja saattavat minut karkottamaan teidät, ja te hukutte, te ja nuo profeetat, jotka teille profetoivat.',
        16: 'Papeille ja koko tälle kansalle puhuin sanoen: Näin sanoo Herra: Älkää kuulko profeettojenne sanoja, niiden, jotka profetoivat teille sanoen: "Katso, Herran temppelin astiat tuodaan nyt kohta takaisin Baabelista"; sillä valhetta he profetoivat teille.',
        17: 'Älkää kuulko heitä. Palvelkaa Baabelin kuningasta, niin pysytte elossa. Miksi pitäisi tämän kaupungin tulla raunioiksi?',
        18: 'Mutta jos he ovat profeettoja ja jos heillä on Herran sana, rukoilkoot Herraa Sebaotia, etteivät ne astiat, jotka vielä ovat jäljellä Herran temppelissä ja Juudan kuninkaan linnassa ja Jerusalemissa, joutuisi nekin Baabeliin.',
        19: 'Sillä näin sanoo Herra Sebaot pylväistä, vaskimerestä, altaiden telineistä ja muista esineistä, jotka vielä ovat jäljellä tässä kaupungissa',
        20: 'ja joita Nebukadnessar, Baabelin kuningas, ei ottanut mukaansa, kun hän vei Jekonjan, Joojakimin pojan, Juudan kuninkaan, sekä kaikki Juudan ja Jerusalemin ylimykset Jerusalemista karkotukseen Baabeliin.',
        21: 'Sillä näin sanoo Herra Sebaot, Israelin Jumala, astioista, jotka vielä ovat jäljellä Herran temppelissä, Juudan kuninkaan linnassa ja Jerusalemissa:',
        22: '"Baabeliin ne viedään, ja sinne ne jäävät siihen päivään asti, jolloin katson niiden puoleen, sanoo Herra, ja annan tuoda ja palauttaa ne tähän paikkaan."',
    },
    28: {
        1: 'Sinä vuonna, Sidkian, Juudan kuninkaan, hallituksen alussa, hänen neljäntenä hallitusvuotenaan, viidennessä kuussa, sanoi profeetta Hananja, Assurin poika, joka oli kotoisin Gibeonista, minulle Herran huoneessa pappien ja kaiken kansan silmien edessä näin:',
        2: '"Näin sanoo Herra Sebaot, Israelin Jumala: Särjen Baabelin kuninkaan ikeen.',
        3: 'Vielä kaksi vuotta, ja minä palautan tähän paikkaan kaikki Herran temppelin astiat, jotka Nebukadnessar, Baabelin kuningas, otti tästä paikasta ja vei Baabeliin.',
        4: 'Myös Jekonjan, Joojakimin pojan, Juudan kuninkaan, ja kaikki Juudan karkotetut, jotka menivät Baabeliin, minä palautan tähän paikkaan, sanoo Herra; sillä särjen Baabelin kuninkaan ikeen."',
        5: 'Mutta profeetta Jeremia puhui profeetta Hananjalle pappien ja kaiken Herran huoneessa seisovan kansan silmien edessä.',
        6: 'Näin profeetta Jeremia sanoi: "Aamen. Niin Herra tehköön. Täyttäköön Herra sanasi, jotka olet profetoinut, ja palauttakoon Herran temppelin astiat ja kaikki karkotetut Baabelista tähän paikkaan.',
        7: 'Kuule kuitenkin tämä sana, jonka minä puhun kuultesi ja kaiken kansan kuullen.',
        8: 'Ne profeetat, jotka ovat olleet ennen minua ja ennen sinua muinaisuudesta asti, ovat profetoineet sotaa, onnettomuutta ja ruttoa monia maita ja suuria valtakuntia vastaan.',
        9: 'Mutta se profeetta, joka profetoi rauhaa, tunnetaan siitä, että hänen sanansa toteutuu, profeetaksi, jonka Herra totisesti on lähettänyt."',
        10: 'Silloin profeetta Hananja otti ikeen profeetta Jeremian niskalta ja särki sen.',
        11: 'Mutta Hananja sanoi kaiken kansan silmien edessä: "Näin sanoo Herra: Näin minä särjen Nebukadnessarin, Baabelin kuninkaan, ikeen kaikkien kansojen niskasta, ennen kuin kaksi vuotta on kulunut." Mutta profeetta Jeremia lähti matkaansa.',
        12: 'Sitten tämä Herran sana tuli Jeremialle, sen jälkeen kun profeetta Hananja oli särkenyt ikeen profeetta Jeremian niskasta:',
        13: '"Mene ja sano Hananjalle: Näin sanoo Herra: Sinä olet särkenyt puisen ikeen, mutta tehnyt sen sijaan rautaisen ikeen.',
        14: 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: rautaisen ikeen olen pannut kaikkien näiden kansojen niskaan, että ne palvelisivat Nebukadnessaria, Baabelin kuningasta; ja niiden on palveltava häntä. Kedon eläimetkin olen antanut hänelle."',
        15: 'Profeetta Jeremia sanoi profeetta Hananjalle: "Kuule, Hananja! Herra ei ole sinua lähettänyt, vaan sinä olet saattanut tämän kansan turvaamaan valheeseen.',
        16: 'Sen tähden, näin sanoo Herra: Katso, toimitan sinut pois maan päältä: tänä vuonna sinä kuolet, sillä sinä olet julistanut luopumusta Herrasta."',
        17: 'Niin profeetta Hananja kuoli sinä vuonna, seitsemännessä kuussa.',
    },
    29: {
        1: 'Nämä ovat sen kirjeen sanat, jonka profeetta Jeremia lähetti Jerusalemista karkotettujen vanhimmille, mitä heitä vielä oli jäljellä, papeille ja profeetoille sekä kaikelle kansalle, jotka Nebukadnessar oli siirtänyt Jerusalemista pois Baabeliin,',
        2: 'sen jälkeen kun kuningas Jekonja ja kuninkaan äiti, hoviherrat, Juudan ja Jerusalemin ruhtinaat sekä sepät ja lukkosepät olivat lähteneet Jerusalemista.',
        3: 'Hän lähetti kirjeen Elasan, Saafanin pojan, ja Gemarjan, Hilkian pojan, mukana, jotka Sidkia, Juudan kuningas, lähetti Nebukadnessarin, Baabelin kuninkaan, luo Baabeliin. Se kuului näin:',
        4: '"Näin sanoo Herra Sebaot, Israelin Jumala, kaikille karkotetuille, jotka olen siirtänyt Jerusalemista pois Baabeliin:',
        5: 'Rakentakaa taloja ja asukaa niissä, istuttakaa puutarhoja ja syökää niiden hedelmiä.',
        6: 'Ottakaa itsellenne vaimoja ja siittäkää poikia ja tyttäriä. Ottakaa pojillenne vaimoja ja naittakaa tyttärenne, että he synnyttäisivät poikia ja tyttäriä. Lisääntykää siellä älkääkä vähentykö.',
        7: 'Etsikää sen kaupungin menestystä, johon olen teidät siirtänyt, ja rukoilkaa sen puolesta Herraa, sillä sen menestys on teidän menestyksenne.',
        8: 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Älkää antako profeettojenne, joita on keskuudessanne, ja tietäjienne pettää itseänne, älkääkä totelko unianne, joita näette.',
        9: 'Sillä valhetta he ennustavat teille minun nimessäni. En ole lähettänyt heitä, sanoo Herra.',
        10: 'Sillä näin sanoo Herra: Vasta kun ne seitsemänkymmentä Baabelin vuotta ovat täyttyneet, katson puoleenne ja panen täytäntöön teitä kohtaan hyvän lupaukseni ja palautan teidät tähän paikkaan.',
        11: 'Sillä minä tunnen ajatukseni, jotka minulla on teitä kohtaan, sanoo Herra: rauhan eikä turmion ajatukset antaakseni teille tulevaisuuden ja toivon.',
        12: 'Te huudatte minua avuksenne, tulette ja rukoilette minua, ja kuulen teitä.',
        13: 'Te etsitte minua ja löydätte minut, sillä te etsitte minua kaikesta sydämestänne.',
        14: 'Annan teidän löytää itseni, sanoo Herra, ja käännän teidän kohtalonne ja kokoan teidät kaikista kansoista ja kaikista paikoista, joihin olen teidät karkottanut, sanoo Herra, ja palautan teidät tähän paikkaan, josta siirsin teidät pois.',
        15: "Sillä te sanotte: ' Herra on herättänyt meille profeettoja Baabelissa.'",
        16: 'Mutta Herra sanoo näin kuninkaasta, joka istuu Daavidin valtaistuimella, ja kaikesta kansasta, joka asuu tässä kaupungissa, veljistänne, jotka eivät lähteneet kanssanne karkotukseen:',
        17: 'Näin sanoo Herra Sebaot: Katso, lähetän heidän sekaansa miekan, nälän ja ruton ja teen heidät inhottaviksi kuin viikunat, jotka ovat niin huonoja, ettei niitä syödä.',
        18: 'Silloin ajan heitä takaa miekalla, nälällä ja rutolla ja teen heidät kauhuksi kaikille valtakunnille maan päällä, kiroukseksi ja kauhistukseksi, ivaksi ja häväistykseksi kaikkien kansojen keskuudessa, mihin heidät karkotan,',
        19: 'sen tähden etteivät he kuulleet sanojani, sanoo Herra, kun lähetin heidän luokseen palvelijoitani, profeettoja, varhaisesta aamusta alkaen. Te ette ole kuulleet, sanoo Herra.',
        20: 'Mutta, te, kuulkaa Herran sana, kaikki karkotetut, jotka olen lähettänyt Jerusalemista Baabeliin.',
        21: 'Näin sanoo Herra Sebaot, Israelin Jumala, Ahabista, Koolajan pojasta, ja Sidkiasta, Maasejan pojasta, jotka ennustavat teille nimessäni valhetta: Katso, annan heidät Nebukadressarin, Baabelin kuninkaan, käsiin, ja hän lyö heidät kuoliaiksi silmienne edessä.',
        22: "Heistä tulee kirosana kaikille Juudan karkotetuille, jotka ovat Baabelissa. Sanotaan: ' Herra tehköön sinulle niin kuin Sidkialle ja Ahabille, jotka Baabelin kuningas poltti tulessa.'",
        23: 'Koska he ovat tehneet häpeällisen teon Israelissa, ovat tehneet huorin lähimmäistensä vaimojen kanssa ja puhuneet nimessäni valhetta, jota en ole käskenyt heidän puhua. Minä olen se, joka sen tiedän ja olen sen todistaja, sanoo Herra."',
        24: 'Nehelamilaiselle Semajalle puhu sanoen:',
        25: '"Näin sanoo Herra Sebaot, Israelin Jumala: Sen tähden että sinä olet lähettänyt omassa nimessäsi kirjeet kaikelle kansalle, joka on Jerusalemissa, ja pappi Sefanjalle, Maasejan pojalle, ja kaikille papeille:',
        26: 'Herra on asettanut sinut papiksi pappi Joojadan sijaan, että olisi järjestyksenvalvojia Herran huoneessa kaikille hulluille ja ennustajille, ja jotta voit panna sellaisen jalkapuuhun ja kaularautaan.',
        27: 'Miksi et siis ole nuhdellut anatotilaista Jeremiaa, joka profetoi teille?',
        28: 'Hän on lähettänyt meille Baabeliin tämän sanan: \'Se kestää vielä kauan. Rakentakaa taloja ja asukaa niissä, istuttakaa puutarhoja ja syökää niiden hedelmiä.\'"',
        29: 'Pappi Sefanja luki tämän kirjeen profeetta Jeremian kuullen.',
        30: 'Jeremialle tuli tämä Herran sana:',
        31: '"Lähetä kaikille karkotetuille tämä sana: Näin sanoo Herra nehelamilaisesta Semajasta: Koska Semaja on profetoinut teille, vaikka minä en ole lähettänyt häntä, ja saattanut teidät turvaamaan valheeseen,',
        32: 'sen tähden, näin sanoo Herra: Katso, kostan nehelamilaiselle Semajalle ja hänen jälkeläisilleen. Hänellä ei ole oleva ketään, joka asuu tämän kansan keskuudessa, eikä hän ole näkevä sitä hyvää, jonka minä teen kansalleni, sanoo Herra; sillä hän on julistanut luopumusta Herrasta."',
    },
    30: {
        1: 'Sana, joka tuli Herralta Jeremialle ja kuului näin:',
        2: '"Näin sanoo Herra, Israelin Jumala: Kirjoita kirjaan kaikki sanat, jotka olen sinulle puhunut.',
        3: 'Sillä katso, aika tulee, sanoo Herra, jolloin käännän kansani Israelin ja Juudan kohtalon, sanoo Herra, ja palautan heidät maahan, jonka olen antanut heidän isilleen, ja he saavat periä sen."',
        4: 'Nämä ovat ne sanat, jotka Herra on puhunut Israelista ja Juudasta.',
        5: 'Näin sanoo Herra: "Pelon huutoa kuulemme: on kauhu, ei rauha!',
        6: 'Kysykää ja nähkää: synnyttääkö mies? Miksi näen kaikkien miesten pitelevän käsin lanteitaan synnyttävien tavalla, ja miksi kaikki kasvot ovat tulleet kalpeiksi?',
        7: 'Voi! Suuri on se päivä, sen kaltaista ei ole. Se on Jaakobille ahdistuksen aika, mutta hän on pelastuva siitä.',
        8: 'Sinä päivänä, sanoo Herra Sebaot, minä särjen ikeen niskaltasi, katkaisen siteesi eivätkä he enää palvele vieraita,',
        9: 'vaan he palvelevat Herraa, Jumalaansa, ja Daavidia, kuningastaan, jonka heille herätän.',
        10: 'Mutta sinä, palvelijani Jaakob, älä pelkää, sanoo Herra, älä säiky, Israel. Sillä, katso, pelastan sinut kaukaisesta maasta ja jälkeläisesi heidän vankeutensa maasta. Jaakob on palaava, elävä rauhassa ja turvassa kenenkään pelottelematta.',
        11: 'Sillä minä olen kanssasi, sanoo Herra, ja pelastan sinut. Sillä teen lopun kaikista kansoista, joiden sekaan olen sinut hajottanut. Ainoastaan sinusta en tee loppua: kuritan sinua kohtuudella, mutta rankaisematta en sinua jätä.',
        12: 'Sillä näin sanoo Herra: Parantumaton on vammasi, haavasi on vaikea.',
        13: 'Ei kukaan aja asiaasi. Haavaasi ei paranneta, eikä se kasva umpeen.',
        14: 'Kaikki rakastajasi ovat sinut unohtaneet. He eivät sinua kysele. Sillä niin kuin vihollista lyödään, olen lyönyt sinua kovalla kurituksella, koska rikoksesi on suuri ja syntisi monilukuiset.',
        15: 'Miksi valitat vammaasi ja kipusi kovuutta? Koska rikoksesi on suuri ja syntisi ovat monilukuiset, olen tämän sinulle tehnyt.',
        16: 'Niin myös kaikki syöjäsi syödään, ja kaikki ahdistajasi, aivan kaikki, vaeltavat vankeuteen. Ryöstäjäsi tulevat ryöstetyiksi, ja kaikki saalistajasi annan saaliiksi.',
        17: "Sillä kasvatan umpeen haavasi ja parannan sinut saamistasi iskuista, sanoo Herra, sinut, Siion, jolla on nimenä 'hylätty', 'se, jota ei kukaan etsi'.",
        18: 'Näin sanoo Herra: Katso, käännän Jaakobin telttamajojen kohtalon, armahdan hänen asuntojaan. Kaupunki rakennetaan kukkulalleen, ja linna on oleva oikealla paikallaan.',
        19: 'Niistä on kaikuva ylistyslaulu ja iloitsevien ääni. Lisään heitä, eivätkä he vähene. Saatan heidät kunniaan, eivätkä he jää halvoiksi.',
        20: 'Silloin hänen poikansa ovat kuin ennen, hänen seurakuntansa pysyy vahvana edessäni ja rankaisen kaikkia hänen sortajiaan.',
        21: 'Hänen valtiaansa lähtee hänestä itsestään, hänen hallitsijansa hänen keskeltään, ja tuon hänet luokseni, ja hän tulee luokseni. Sillä kuka panee henkensä alttiiksi lähestyäkseen minua? sanoo Herra.',
        22: 'Te olette minun kansani, ja minä olen teidän Jumalanne."',
        23: 'Katso, Herran myrsky, kiivaus, puhkeaa, pyörremyrsky pyörii kohti jumalattomien päätä.',
        24: 'Eikä Herran vihan hehku asetu, ennen kuin hän on toteuttanut ja täyttänyt sydämensä ajatukset. Päivien lopulla te tulette ymmärtämään sen.',
    },
    31: {
        1: '"Siihen aikaan, sanoo Herra, olen kaikkien Israelin sukukuntien Jumala, ja he ovat kansani."',
        2: 'Näin sanoo Herra: "Kansa, miekalta säästynyt, löysi erämaassa armon. Menen saattamaan Israelin rauhaan."',
        3: 'Kaukaa ilmestyy minulle Herra: "Iankaikkisella rakkaudella olen sinua rakastanut, sen tähden olen vetänyt sinua puoleeni armosta.',
        4: 'Rakennan sinut jälleen, ja sinä, neitsyt Israel, tulet rakennetuksi. Kaunistat itsesi jälleen käsirummuillasi ja lähdet iloitsevien karkeloon.',
        5: 'Istutat jälleen viinitarhoja Samarian vuorille. Istuttajat istuttavat ne ja nauttivat niistä.',
        6: "Sillä päivä tulee, jolloin vartijat huutavat Efraimin vuorella: 'Nouskaa, lähtekäämme Siioniin Herran, Jumalamme, luo.'",
        7: "Sillä näin sanoo Herra: Riemuitkaa iloiten Jaakobista, kohottakaa riemuhuuto hänelle, joka on kansojen pää. Kuuluttakaa, kiittäkää ja sanokaa: 'Auta, Herra, kansaasi, Israelin jäännöstä.'",
        8: 'Katso, tuon heidät pohjoisesta maasta ja kokoan heidät maan ääristä. Heissä on sokeita, rampoja sekä raskaana olevia ja synnyttäviä yhdessä. He palaavat tänne suurena joukkona.',
        9: 'Itkien he tulevat, ja johdatan heitä, kun he kulkevat rukoillen. Vien heidät vesipuroille, tasaista tietä, jolla he eivät kompastu. Sillä olen Israelin Isä, ja Efraim on esikoiseni.',
        10: 'Kuulkaa Herran sana, te kansat, ilmoittakaa kaukaisissa merensaarissa ja sanokaa: Hän, joka Israelin hajotti, on sen kokoava ja varjeleva sitä kuin paimen laumaansa.',
        11: 'Sillä Herra on lunastanut Jaakobin ja vapahtanut hänet häntä väkevämmän kädestä.',
        12: 'Silloin he tulevat ja riemuitsevat Siionin kukkulalla. He tulevat virtanaan Herran hyvyyden luo, vehnän, viinin ja öljyn ääreen, karitsojen ja vasikoiden ääreen. Heidän sielunsa on oleva kuin kostea puutarha, eivätkä he enää näänny.',
        13: 'Silloin neitsyt iloitsee karkelossa ja nuorukaiset ja vanhukset yhdessä. Muutan heidän surunsa riemuksi, annan heille lohdutuksen ja ilon päästäen heidät heidän murheestaan.',
        14: 'Virvoitan pappien sielut yltäkylläisyydellä, ja kansani ravitaan hyvyydelläni, sanoo Herra.',
        15: 'Näin sanoo Herra: Kuule, ääni on kuuluva Raamasta, itku ja kova valitus: Raakel itkee lapsiaan eikä lohdutuksesta huoli surressaan lastensa tähden, sillä heitä ei enää ole.',
        16: 'Näin sanoo Herra: Pidätä äänesi itkusta, silmäsi kyynelistä, sillä työstäsi on tuleva palkka, sanoo Herra, ja he palaavat vihollisen maasta.',
        17: 'Sinulla on tulevaisuuden toivo, sanoo Herra: lapsesi palaavat omalle maalleen.',
        18: "Olen kuulemalla kuullut Efraimin valittavan: 'Olet kurittanut minua, olen saanut kuritusta kuin vikuroiva vasikka. Palauta minut, niin palaan, sillä sinä olet Herra, Jumalani.",
        19: "Sillä käännyttyäni kadun, ja päästyäni ymmärrykseen lyön lanteeseeni. Olen nöyryytetty ja tunnen häpeää, sillä kannan nuoruuteni pilkkaa.'",
        20: 'Eikö Efraim ole kallis poikani, lempilapseni? Sillä niin usein kuin puhunkin häntä vastaan, aina häntä muistan. Siksi sisimpäni väräjää hänen tähtensä: minun täytyy armahtaa häntä, sanoo Herra.',
        21: 'Pystytä itsellesi merkkejä, aseta itsellesi tienviittoja, paina mieleesi tie, polku, jota olet kulkenut. Palaa, neitsyt Israel, palaa näihin kaupunkeihisi.',
        22: 'Kuinka kauan sinä kuljet mutkitellen sinne tänne, sinä luopiotytär? Sillä Herra luo maahan uutta: nainen miestä piirittää.',
        23: "Näin sanoo Herra Sebaot, Israelin Jumala: Vielä sanotaan Juudan maassa ja sen kaupungeissa, kun käännän heidän kohtalonsa, tämä sana: ' Herra siunatkoon sinua, sinä vanhurskauden asuinsija, sinä pyhä vuori.'",
        24: 'Juuda kaikkine kaupunkeineen asuu siellä yhdessä sekä peltomiehet ja ne, jotka vaeltavat laumoineen.',
        25: 'Sillä virvoitan voipuneen sielun, ja jokaisen nääntyvän sielun ravitsen."',
        26: 'Siihen heräsin ja katselin, ja uneni oli minusta suloinen.',
        27: '"Katso, päivät tulevat, sanoo Herra, jolloin kylvän Israelin huoneeseen ja Juudan huoneeseen ihmisen siementä ja karjan siementä.',
        28: 'Niin kuin olen valvonut repiäkseni ja kukistaakseni heitä, hajottaakseni ja hävittääkseni, tuottaakseni onnettomuutta, niin olen valvova rakentaakseni ja istuttaakseni heitä, sanoo Herra.',
        29: "Niinä päivinä ei enää sanota: 'Isät söivät raakoja rypäleitä, ja lasten hampaat heltyivät',",
        30: 'vaan jokaisen on kuoltava oman syntivelkansa tähden. Jokaiselta ihmiseltä, joka syö raakoja rypäleitä, heltyvät hänen omat hampaansa.',
        31: 'Katso, päivät tulevat, sanoo Herra, jolloin teen Israelin heimon ja Juudan heimon kanssa uuden liiton,',
        32: 'en sellaista liittoa kuin se, jonka tein heidän isiensä kanssa silloin, kun tartuin heidän käteensä ja vein heidät pois Egyptin maasta. Sen liittoni he ovat rikkoneet, vaikka olin kihlannut heidät, sanoo Herra.',
        33: 'Vaan tämä on se liitto, jonka teen Israelin heimon kanssa niiden päivien tultua, sanoo Herra: Panen lakini heidän sisimpäänsä ja kirjoitan sen heidän sydämiinsä; ja niin olen heidän Jumalansa, ja he ovat kansani.',
        34: "Silloin ei enää toinen opeta toistaan eikä veli veljeään sanoen: 'Tuntekaa Herra.' Sillä he kaikki pienimmästä suurimpaan tuntevat minut, sanoo Herra, sillä annan anteeksi heidän rikoksensa enkä enää muista heidän syntejään.",
        35: 'Näin sanoo Herra, joka on pannut auringon valaisemaan päivää, säätänyt kuun ja tähdet valaisemaan lakiensa mukaan yötä, hän, joka liikuttaa meren, niin että sen aallot pauhaavat – Herra Sebaot on hänen nimensä:',
        36: 'Jos nämä lait väistyvät kasvojeni edestä, silloin myös Israelin jälkeläiset lakkaavat olemasta kansa kasvojeni edessä ainiaan.',
        37: 'Näin sanoo Herra: Jos voidaan mitata taivaat ylhäällä ja tutkia maan perustukset alhaalla, silloin vasta hylkään Israelin jälkeläiset kaikki, kaiken sen tähden, mitä he ovat tehneet, sanoo Herra.',
        38: 'Katso, päivät tulevat, sanoo Herra, jolloin Herran kaupunki rakennetaan jälleen Hananelin tornista Kulmaporttiin asti.',
        39: 'Silloin mittanuora kulkee edelleen suoraan Gaarebin kukkulalle ja kääntyy sitten Gooaan.',
        40: 'Myös koko laakso, ruumiineen ja tuhkineen, ja koko pelto Kidronin purolle asti, Hevosportin kulmaan saakka itään päin, on oleva Herralle pyhitetty. Sitä ei enää ikinä hävitetä eikä kukisteta."',
    },
    32: {
        1: 'Sana, joka tuli Jeremialle Herralta Sidkian, Juudan kuninkaan, kymmenentenä vuotena, se on Nebukadressarin kahdeksantenatoista vuotena.',
        2: 'Silloin Baabelin kuninkaan sotajoukko piiritti Jerusalemia, ja profeetta Jeremia oli suljettuna vankilan pihaan, joka on Juudan kuninkaan linnassa.',
        3: 'Sinne oli Sidkia, Juudan kuningas, hänet sulkenut sanoen: "Miksi sinä profetoit näin: Näin sanoo Herra: Katso, annan tämän kaupungin Baabelin kuninkaan käsiin, ja hän valloittaa sen?',
        4: 'Mutta Sidkia, Juudan kuningas, ei pääse pakoon kaldealaisten käsistä, vaan hänet tosiaan annetaan Baabelin kuninkaan käsiin, ja hänen täytyy puhua hänen kanssaan suusta suuhun ja nähdä hänet silmästä silmään.',
        5: 'Hän kuljettaa Sidkian Baabeliin, ja sinne hän jää, kunnes katson hänen puoleensa, sanoo Herra. Kun taistelette kaldealaisia vastaan, teillä ei ole menestystä."',
        6: 'Sitten Jeremia sanoi: "Minulle tuli tämä Herran sana, ja se kuului:',
        7: 'Katso, Hanamel, setäsi Sallumin poika, tulee luoksesi ja sanoo: \'Osta peltoni, joka on Anatotissa, sillä sinulla on lunastusoikeus, niin että saat ostaa sen.\'"',
        8: 'Niin Hanamel, setäni poika, tuli Herran sanan mukaan luokseni vankilan pihaan ja sanoi minulle: "Osta peltoni, joka on Anatotissa, Benjaminin maassa, sillä sinulla on perintöoikeus ja sinulla on lunastusoikeus: osta se itsellesi." Ymmärsin, että se oli Herran sana.',
        9: 'Ostin Hanamelilta, setäni pojalta, pellon, joka on Anatotissa, ja punnitsin hänelle rahat, seitsemäntoista sekeliä hopeaa,',
        10: "kirjoitin kauppakirjan ja sinetöin sen, otin todistajat ja punnitsin rahat vaa'alla.",
        11: 'Sitten otin kauppakirjan, joka oli sinetöity lain ja määräysten mukaan, sekä avoimen kirjan,',
        12: 'ja annoin kauppakirjan Baarukille, Neerian, Mahsejan pojan, pojalle, serkkuni Hanamelin nähden ja todistajien nähden, jotka olivat allekirjoittaneet kauppakirjan, ja kaikkien juutalaisten nähden, jotka istuivat vankilan pihassa,',
        13: 'ja käskin Baarukia heidän nähtensä sanoen:',
        14: '"Näin sanoo Herra Sebaot, Israelin Jumala: Ota nämä kirjat, tämä kauppakirja, sekä sinetöity että tämä avoin kirja, ja pane ne saviastiaan, että ne säilyisivät kauan aikaa.',
        15: 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Vielä kerran ostetaan tässä maassa taloja ja peltoja ja viinitarhoja."',
        16: 'Rukoilin Herraa, kun olin antanut kauppakirjan Baarukille, Neerian pojalle, ja sanoin:',
        17: '"Oi Herra, Herra! Katso, sinä olet tehnyt taivaan ja maan suurella voimallasi ja ojennetulla käsivarrellasi: ei mikään ole sinulle mahdotonta,',
        18: 'sinä, joka teet laupeuden tuhansille, mutta kostat isien pahat teot heidän jälkeensä heidän lapsilleen, sinä suuri, väkevä Jumala, jonka nimi on Herra Sebaot,',
        19: 'suuri neuvossa ja voimakas teoissa, sinä, jonka silmät ovat avoimet seuraamaan kaikkia ihmislasten teitä antaaksesi jokaiselle hänen vaelluksensa ja hänen tekojensa hedelmän mukaan;',
        20: 'sinä, joka teit tunnustekoja ja ihmeitä Egyptin maassa ja olet tehnyt niitä aina tähän päivään asti sekä Israelissa että muiden ihmisten joukossa, ja joka olet tehnyt itsellesi nimen, sellaisen kuin se tänäkin päivänä on.',
        21: 'Sinä veit kansasi Israelin pois Egyptin maasta tunnusteoilla ja ihmeillä, väkevällä kädellä ja ojennetulla käsivarrella, suurella pelolla,',
        22: 'ja annoit heille tämän maan, jonka olit luvannut antaa heille heidän isilleen vannotulla valalla, maan, joka vuotaa maitoa ja hunajaa.',
        23: 'Mutta kun he olivat tulleet ja ottaneet sen omakseen, he eivät kuulleet ääntäsi eivätkä vaeltaneet lakisi mukaan. He eivät tehneet mitään siitä, mitä olit käskenyt heidän tehdä, ja annoit kaiken tämän onnettomuuden kohdata heitä.',
        24: 'Katso, piiritysvallit ovat edenneet aivan kaupunkiin asti, niin että se valloitetaan, ja kaupunki joutuu miekan, nälän ja ruton tähden kaldealaisten valtaan, jotka sotivat sitä vastaan. Mitä olet puhunut, on tapahtunut, ja katso, sinä näet sen.',
        25: 'Mutta kuitenkin sinä, Herra, Herra, sanoit minulle: \'Osta rahalla itsellesi pelto ja ota todistajat\', vaikka kaupunki joutuu kaldealaisten käsiin."',
        26: 'Silloin Jeremialle tuli tämä Herran sana, ja se kuului:',
        27: '"Katso, minä olen Herra, kaiken lihan Jumala; onko minulle mikään mahdotonta?',
        28: 'Sen tähden, näin sanoo Herra: Katso, annan tämän kaupungin kaldealaisten käsiin ja Nebukadressarin, Baabelin kuninkaan, käsiin, ja hän valloittaa sen.',
        29: 'Niin kaldealaiset, jotka sotivat tätä kaupunkia vastaan, tulevat ja sytyttävät tämän kaupungin tuleen ja polttavat sen niine taloineen, joiden katoilla on poltettu uhreja Baalille ja vuodatettu juomauhreja vieraille jumalille, saadakseen vihani syttymään.',
        30: 'Sillä Israelin ja Juudan miehet ovat nuoruudestaan asti tehneet vain sitä, mikä on pahaa silmissäni, sillä kättensä teoilla israelilaiset ovat kiihottaneet minua vain vihaan, sanoo Herra.',
        31: 'Sillä tämä kaupunki on ollut minulle vihaksi ja kiivastukseksi siitä päivästä lähtien, jona he sen rakensivat, aina tähän päivään asti. Heitän sen pois kasvojeni edestä',
        32: 'kaiken sen pahan tähden, minkä israelilaiset ja Juudan miehet ovat tehneet minulle herättääkseen vihani – he, heidän kuninkaansa, ruhtinaansa, pappinsa ja profeettansa sekä Juudan miehet ja Jerusalemin asukkaat.',
        33: 'He ovat kääntäneet minulle selkänsä eivätkä kasvojaan, ja vaikka olen opettanut heitä aamuvarhaisesta alkaen, he eivät ole kuulleet eivätkä ottaneet varteen opetusta.',
        34: 'He ovat asettaneet iljetyksensä temppeliin, joka on otettu nimiini, ja saastuttaneet sen.',
        35: 'He ovat myös rakentaneet Baalille uhrikukkulat, jotka ovat Ben-Hinnomin laaksossa, polttaakseen poikiaan ja tyttäriään uhrina Molokille, mitä en ole käskenyt ja mikä ei ole mieleeni tullut. Tällaisia kauhistuksia he tekivät ja saivat Juudan tekemään syntiä.',
        36: 'Mutta nyt sanoo Herra, Israelin Jumala, näin tästä kaupungista, jonka te sanotte annettavan Baabelin kuninkaan käsiin miekan, nälän ja ruton tähden:',
        37: 'Katso, kokoan heidät jälleen kaikista maista, joihin heidät vihassani, kiivastuksessani ja suuressa suuttumuksessani karkotan, ja palautan heidät tähän paikkaan ja saatan heidät asumaan turvassa.',
        38: 'Silloin he ovat kansani, ja minä olen heidän Jumalansa,',
        39: 'ja annan heille yhden sydämen ja yhden tien, niin että he pelkäävät minua kaiken elinaikansa heille ja heidän lapsilleen parhaaksi heidän jälkeensä.',
        40: 'Teen heidän kanssaan iankaikkisen liiton, niin etten käänny heistä pois, vaan teen heille hyvää, ja annan pelkoni heidän sydämiinsä, niin etteivät he luovu minusta.',
        41: 'Iloitsen heistä, siitä, että teen heille hyvää, ja istutan heidät tähän maahan totuudessa kaikesta sydämestäni ja kaikesta sielustani.',
        42: 'Sillä näin sanoo Herra: Samoin kuin olen tuottanut tälle kansalle kaiken tämän suuren onnettomuuden, niin minä myös tuotan heille kaiken sen hyvän, minkä minä heille sanon.',
        43: "Vielä ostetaan peltoja tässä maassa, josta te sanotte: 'Se on oleva autio, vailla ihmisiä ja eläimiä ja kaldealaisten käsiin annettu.'",
        44: 'Peltoja ostetaan rahalla, kauppakirjoja kirjoitetaan ja sinetöidään ja todistajia otetaan Benjaminin maassa, Jerusalemin ympäristössä ja Juudan kaupungeissa, Vuoriston, Alankomaan ja Negevin kaupungeissa, sillä käännän heidän kohtalonsa, sanoo Herra."',
    },
    33: {
        1: 'Herran sana tuli Jeremialle toistamiseen, kun hän oli vielä suljettuna vankilan pihalle. Se kuului näin:',
        2: '"Näin sanoo Herra, joka sen myös tekee, Herra, joka valmistaa sen ja vahvistaa sen – Herra on hänen nimensä:',
        3: 'Huuda minua avuksesi, niin vastaan sinulle ja ilmoitan sinulle suuria ja salattuja asioita, joita et tiedä.',
        4: 'Sillä näin sanoo Herra, Israelin Jumala, tämän kaupungin taloista ja Juudan kuningasten linnoista, jotka sortuvat piiritysvallien ja miekan edessä,',
        5: 'ja niistä, jotka ovat tulleet taistelemaan kaldealaisia vastaan, ja täyttämään talot ihmisten ruumiilla, jotka vihassani ja kiivastuksessani surmaan ja joiden kaiken pahuuden tähden olen kätkenyt kasvoni tältä kaupungilta:',
        6: 'Katso, kasvatan umpeen ja lääkitsen sen haavat, ja parannan heidät ja avaan heille rauhan ja totuuden yltäkylläisyyden.',
        7: 'Käännän Juudan kohtalon ja Israelin kohtalon ja rakennan heidät entiselleen.',
        8: 'Puhdistan heidät kaikista heidän pahoista teoistaan, joilla he ovat tehneet syntiä minua vastaan, ja annan anteeksi kaikki heidän pahat tekonsa, joilla he ovat rikkoneet minua vastaan ja nousseet kapinaan minua vastaan.',
        9: 'Tämä kaupunki on oleva minulle kunniaksi ja iloksi, ylistykseksi ja kirkkaudeksi kaikkien maan kansojen edessä, jotka kuulevat kaiken sen hyvän, minkä minä sille teen. He pelästyvät ja vapisevat kaiken sen hyvän ja kaiken sen rauhan tähden, jonka minä sille annan.',
        10: "Näin sanoo Herra: Vielä kerran kuullaan tässä paikassa, josta te sanotte: 'Se on oleva rauniona, vailla ihmisiä ja eläimiä.' Juudan kaupungeissa ja Jerusalemin autioilla kaduilla, joilla ei nyt ole ihmistä, ei asukasta eikä eläintä,",
        11: "riemun ja ilon huuto, huuto yljälle ja huuto morsiamelle, niiden huuto, jotka sanovat: 'Kiittäkää Herraa Sebaotia, sillä Herra on hyvä, sillä hänen armonsa pysyy iankaikkisesti', ja niiden, jotka tuovat Herran huoneeseen kiitosuhreja. Sillä käännän maan kohtalon entiselleen, sanoo Herra.",
        12: 'Näin sanoo Herra Sebaot: Vielä kerran on tässä paikassa, joka on rauniona, vailla ihmisiä ja eläimiä, ja kaikilla sen kaupungeilla oleva laitumia, joilla paimenet antavat lampaittensa levätä.',
        13: 'Vuoriston kaupungeissa, Alankomaan kaupungeissa ja Negevin kaupungeissa, Benjaminin maassa, Jerusalemin ympäristössä ja Juudan kaupungeissa on vielä kerran lampaita kulkeva laskijan käsien ohi, sanoo Herra.',
        14: 'Katso, päivät tulevat, sanoo Herra, jolloin toteutan sen hyvän lupauksen, jonka olen lausunut Israelin heimosta ja Juudan heimosta.',
        15: 'Niinä päivinä ja siihen aikaan kasvatan Daavidille vanhurskauden Vesan, ja hän on tekevä oikeuden ja vanhurskauden maassa.',
        16: "Niinä päivinä pelastetaan Juuda, ja Jerusalem asuu turvassa, ja tämä on se nimi, joksi sitä sanotaan: ' Herra, vanhurskautemme.'",
        17: 'Sillä näin sanoo Herra: Aina on mies Daavidin suvusta istuva Israelin heimon valtaistuimella.',
        18: 'Aina on myös mies leeviläisten pappien suvusta oleva edessäni uhraamassa polttouhria ja sytyttämässä ruokauhria ja toimittamassa teurasuhria joka päivä."',
        19: 'Jeremialle tuli tämä Herran sana, ja se kuului:',
        20: '"Näin sanoo Herra: Jos saatte rikotuksi liittoni päivän kanssa ja liittoni yön kanssa, niin että päivä ja yö eivät enää tule ajallaan,',
        21: 'niin rikkoutuu myös liittoni palvelijani Daavidin kanssa, niin ettei hänellä enää ole poikaa, joka istuu kuninkaana hänen valtaistuimellaan, ja liittoni leeviläisten pappien, palvelijoitteni, kanssa.',
        22: 'Samoin kuin taivaan joukkoa ei voi lukea eikä meren hiekkaa mitata, niin monilukuisiksi teen palvelijani Daavidin jälkeläiset ja leeviläiset, jotka minua palvelevat."',
        23: 'Sitten Jeremialle tuli tämä Herran sana, ja se kuului:',
        24: '"Etkö ole huomannut, mitä tämä kansa puhuu sanoen: \'Ne kaksi sukukuntaa, jotka Herra valitsi, hän on hylännyt\'? He halveksivat kansaani, niin kuin se ei enää olisikaan kansa heidän silmissään.',
        25: 'Näin sanoo Herra: Jos liittoni päivän ja yön kanssa on olematon, jos en ole säätänyt taivaan ja maan lakeja,',
        26: 'niin myös hylkään Jaakobin ja palvelijani Daavidin jälkeläiset, niin etten ota hänen jälkeläisistään hallitsijoita Aabrahamin, Iisakin ja Jaakobin jälkeläisille. Sillä käännän heidän kohtalonsa ja armahdan heitä."',
    },
    34: {
        1: 'Sana, joka tuli Jeremialle Herralta, kun Nebukadnessar, Baabelin kuningas, ja koko hänen sotajoukkonsa ja kaikki hänen valtaansa kuuluvan maan valtakunnat ja kaikki kansat sotivat Jerusalemia ja kaikkia siihen kuluvia kaupunkeja vastaan. Se kuului näin:',
        2: '"Näin sanoo Herra, Israelin Jumala: Mene ja sano Sidkialle, Juudan kuninkaalle, sano hänelle: Näin sanoo Herra: Katso, annan tämän kaupungin Baabelin kuninkaan käsiin, ja hän polttaa sen tulella.',
        3: 'Mutta sinä et pääse pakoon hänen käsistään, vaan sinut otetaan kiinni ja annetaan hänen käsiinsä, ja sinun täytyy nähdä Baabelin kuningas silmästä silmään, ja hän puhuu kanssasi suusta suuhun, ja joudut Baabeliin.',
        4: 'Mutta kuule Herran sana, Sidkia, Juudan kuningas: Näin sanoo Herra sinusta: Et kuole miekkaan.',
        5: 'Kuolet rauhassa; ja niin kuin isillesi, aikaisemmille kuninkaille, jotka olivat ennen sinua, niin poltetaan kunniaksesi kuolinsuitsutus ja sinulle pidetään valittajaiset ja huudetaan: \'Voi herraamme!\' Sillä minä olen sen sanonut, sanoo Herra."',
        6: 'Profeetta Jeremia puhui Sidkialle, Juudan kuninkaalle, kaikki nämä sanat Jerusalemissa,',
        7: 'kun Baabelin kuninkaan sotajoukko taisteli Jerusalemia vastaan ja kaikkia vielä jäljellä olevia Juudan kaupunkeja vastaan, Laakista ja Asekaa vastaan, sillä nämä olivat jääneet jäljelle Juudan kaupungeista, nimittäin sen linnoitetuista kaupungeista.',
        8: 'Sana, joka tuli Jeremialle Herralta, sen jälkeen kun kuningas Sidkia oli tehnyt liiton kaiken kansan kanssa, joka oli Jerusalemissa, ja julistanut heille vapautuksen,',
        9: 'että jokaisen tuli päästää vapaaksi orjansa ja orjattarensa, heprealainen mies ja heprealainen nainen, niin etteivät he pitäisi heitä orjinaan, kukaan ei juutalaista veljeään.',
        10: 'Sen kuulivat kaikki ruhtinaat ja kaikki kansa, jotka olivat menneet tähän liittoon, että jokaisen tuli päästää vapaaksi orjansa ja orjattarensa eikä enää pitää heitä orjinaan, ja he tottelivat ja päästivät heidät.',
        11: 'Mutta jälkeenpäin he peräytyivät liitosta ja ottivat takaisin ne orjat ja orjattaret, jotka he olivat päästäneet vapaiksi, ja alistivat heidät orjikseen ja orjattarikseen.',
        12: 'Silloin tuli Jeremialle Herralta tämä Herran sana:',
        13: '"Näin sanoo Herra, Israelin Jumala: Minä tein isienne kanssa liiton sinä päivänä, kun vein heidät pois Egyptin maasta, orjuuden huoneesta sanoen:',
        14: 'Seitsemän vuoden kuluttua päästäkää veljenne, heprealainen: joka on myynyt itsensä sinulle ja palvellut sinua kuusi vuotta, päästä hänet luotasi vapaaksi. Mutta isänne eivät kuulleet minua eivätkä kallistaneet korvaansa puheelleni.',
        15: 'Vaan nyt te olette kääntyneet ja tehneet teon, joka on oikea silmissäni julistaessanne vapautuksen kukin lähimmäiselleen, ja olette tehneet liiton kasvojeni edessä huoneessa, joka on otettu nimiini.',
        16: 'Mutta sitten te olette jälleen kääntyneet pois ja häväisseet nimeni: olette ottaneet takaisin kukin orjanne ja orjattarenne, jotka olitte päästäneet vapaiksi ja itsenäisiksi, ja olette alistaneet heidät olemaan orjinanne ja orjattarinanne.',
        17: 'Sen tähden näin sanoo Herra: Te ette kuulleet minua ettekä julistaneetkaan vapautusta kukin veljelleen ja lähimmäiselleen. Katso, julistan teille vapautuksen, sanoo Herra: menon miekkaan, ruttoon ja nälkään, ja teen teidät kauhuksi kaikille valtakunnille maan päällä.',
        18: 'Annan ne miehet, jotka ovat rikkoneet liittoni, jotka eivät ole pitäneet sen liiton sanoja, jonka he tekivät edessäni halkaisten kahtia uhrivasikan ja käyden sen puolikkaiden välitse, nämä miehet –',
        19: 'Juudan ruhtinaat ja Jerusalemin ruhtinaat, hoviherrat ja papit sekä kaiken maan kansan, jotka kävivät vasikan puolikkaiden välitse –',
        20: 'annan heidät heidän vihollistensa käsiin, niiden käsiin, jotka etsivät heidän henkeään; ja heidän ruumiinsa joutuvat taivaan lintujen ja maan eläinten ruuaksi.',
        21: 'Sidkian, Juudan kuninkaan, ja hänen ruhtinaansa annan heidän vihollistensa käsiin, niiden käsiin, jotka etsivät heidän henkeään, Baabelin kuninkaan sotajoukon käsiin, joka on lähtenyt pois kimpustanne.',
        22: 'Katso, käsken heitä, sanoo Herra, ja palautan heidät tämän kaupungin kimppuun, ja he sotivat sitä vastaan, valloittavat sen ja polttavat sen tulella; ja Juudan kaupungit teen autioiksi, eikä niissä ole asukkaita."',
    },
    35: {
        1: 'Sana, joka tuli Jeremialle Herralta Juudan kuninkaan Joojakimin, Joosian pojan, päivinä, ja kuului:',
        2: '"Mene reekabilaisten luo ja puhuttele heitä ja vie heidät Herran temppeliin, yhteen sen kammioista, ja anna heille viiniä juoda."',
        3: 'Niin otin Jaasanjan, joka oli Jeremian, Habassinjan pojan, poika, sekä hänen veljensä ja kaikki hänen poikansa ja koko reekabilaisten heimon,',
        4: 'ja vein heidät Herran huoneeseen, Jumalan miehen Haananin, Jigdaljan pojan, poikien kammioon, joka on ruhtinaiden kammion vieressä, ovenvartija Maasejan, Sallumin pojan, kammion yläpuolella.',
        5: 'Asetin reekabilaisten eteen täysiä viiniruukkuja sekä maljoja ja sanoin heille: "Juokaa viiniä."',
        6: 'Mutta he vastasivat: "Me emme juo viiniä; sillä meidän isämme Joonadab, Reekabin poika, on antanut meille tämän käskyn: Älkää te ja teidän lapsenne ikinä juoko viiniä.',
        7: 'Älkää rakentako taloja älkääkä kylväkö siementä. Älkää istuttako viinitarhoja, älköönkä niitä teillä olko, vaan asukaa teltoissa kaikkina elämänne päivinä, että eläisitte kauan siinä maassa, jossa te olette muukalaisina.',
        8: 'Me kuulemme isämme Joonadabin, Reekabin pojan ääntä, kaikessa, mitä hän on käskenyt meidän tehdä, niin että emme koskaan juo viiniä elämämme päivinä, emme me eivätkä vaimomme, eivät poikamme eivätkä tyttäremme,',
        9: 'emmekä rakenna taloja asuaksemme, eikä meillä ole viinitarhoja, ei peltoa eikä siementä.',
        10: 'Vaan me asumme teltoissa ja olemme kuuliaiset ja teemme kaiken, mitä isämme Joonadab on käskenyt meidän tehdä.',
        11: 'Mutta kun Nebukadressar, Baabelin kuningas, hyökkäsi maahan, niin sanoimme: \'Tulkaa, menkäämme Jerusalemiin kaldealaisten sotajoukkoa ja aramilaisten sotajoukkoa pakoon\', ja asetuimme Jerusalemiin."',
        12: 'Silloin Jeremialle tuli tämä Herran sana, ja se kuului:',
        13: '"Näin sanoo Herra Sebaot, Israelin Jumala: Mene ja sano Juudan miehille ja Jerusalemin asukkaille: Ettekö ota ojennusta varteen ja kuule minun sanojani? sanoo Herra.',
        14: 'Joonadabin, Reekabin pojan, sanat, joilla hän kielsi poikiansa juomasta viiniä, pidetään voimassa, ja niin he eivät ole juoneet tähän päivään asti, sillä he ovat kuuliaisia isänsä käskylle. Mutta minä olen puhunut teille aamuvarhaisesta alkaen, ja te ette ole kuulleet minua.',
        15: 'Olen lähettänyt teidän luoksenne kaikki palvelijani, profeetat, aamuvarhaisesta alkaen, sanoen: Kääntykää kukin pahalta tieltänne ja parantakaa tekonne, älkää seuratko muita jumalia älkääkä niitä palvelko, niin tulette asumaan siinä maassa, jonka olen antanut teille ja teidän isillenne. Mutta te ette ole kallistaneet korvaanne, ette ole kuulleet minua.',
        16: 'Joonadabin, Reekabin pojan, jälkeläiset ovat siis pitäneet voimassa isänsä käskyn, jonka hän heille antoi, mutta tämä kansa ei ole kuullut minua.',
        17: 'Sen tähden, näin sanoo Herra, Jumala Sebaot, Israelin Jumala: Katso, annan tulla Juudalle ja kaikille Jerusalemin asukkaille kaiken sen onnettomuuden, jolla olen heitä uhannut, koska he eivät kuulleet, kun puhuin heille, eivätkä vastanneet, kun heitä kutsuin."',
        18: 'Mutta reekabilaisille Jeremia sanoi: "Näin sanoo Herra Sebaot, Israelin Jumala: Koska olette olleet kuuliaisia isänne Joonadabin käskylle ja noudattaneet kaikkia hänen käskyjään ja tehneet kaiken, mitä hän käski teidän tehdä,',
        19: 'sen tähden, näin sanoo Herra Sebaot, Israelin Jumala: Joonadabin, Reekabin pojan, suvussa on aina oleva mies, joka seisoo kasvojeni edessä."',
    },
    36: {
        1: 'Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena tuli tämä sana Jeremialle Herralta ja se kuului:',
        2: '"Ota kirjakäärö ja kirjoita siihen kaikki sanat, jotka olen puhunut sinulle Israelista ja Juudasta ja kaikista pakanakansoista siitä päivästä asti, jolloin aloin sinulle puhua, Joosian päivistä, aina tähän päivään saakka.',
        3: 'Ehkäpä Juudan heimo, kuultuaan kaiken sen onnettomuuden, jonka minä aion heille tuottaa, kääntyy, kukin pahalta tieltään, ja annan anteeksi heidän pahat tekonsa ja syntinsä."',
        4: 'Silloin Jeremia kutsui Baarukin, Neerian pojan, ja Baaruk kirjoitti kirjakääröön Jeremian suusta kaikki ne sanat, jotka Herra oli hänelle puhunut.',
        5: 'Sitten Jeremia käski Baarukia sanoen: "Minä olen estetty, en voi mennä Herran huoneeseen.',
        6: 'Mene sinä ja lue kirjakääröstä, jonka olet kirjoittanut suustani, Herran sanat kansan kuullen Herran huoneessa paastopäivänä ja myös koko Juudan kuullen, niiden, jotka tulevat kaupungeistaan, on sinun ne julistettava.',
        7: 'Ehkäpä he rukouksessa lankeavat Herran eteen ja kääntyvät kukin pahalta tieltään. Sillä suuri on viha ja kiivaus, jonka Herra on julistanut tälle kansalle."',
        8: 'Niin Baaruk, Neerian poika, teki kaikki, kuten profeetta Jeremia oli käskenyt hänen tehdä, ja luki kirjasta Herran sanat Herran huoneessa.',
        9: 'Mutta Juudan kuninkaan Joojakimin, Joosian pojan, viidentenä hallitusvuotena, yhdeksännessä kuussa, oli kaikki Jerusalemin kansa ja kaikki se kansa, joka oli tullut Juudan kaupungeista Jerusalemiin, kutsuttu pitämään paastoa Herran edessä.',
        10: 'Silloin Baaruk luki kirjasta Jeremian sanat Herran huoneessa, kirjuri Gemarjan, Saafanin pojan, kammiossa ylemmässä esipihassa Herran huoneen uuden portin ovella kaiken kansan kuullen.',
        11: 'Kun Miika, Gemarjan, Saafanin pojan, poika, oli kuullut kaikki Herran sanat kirjasta,',
        12: 'hän meni alas kuninkaan linnaan, kirjurin kammioon, ja katso, siellä istuivat kaikki ruhtinaat: kirjuri Elisama ja Delaja, Semajan poika, ja Elnatan, Akborin poika, ja Gemarja, Saafanin poika, ja Sidkia, Hananjan poika, ja kaikki muut ruhtinaat.',
        13: 'Heille Miika ilmoitti kaikki sanat, jotka hän oli kuullut Baarukin lukevan kirjasta kansan kuullen.',
        14: 'Kaikki ruhtinaat lähettivät Baarukin luo Jehudin, joka oli Netanjan poika, joka Selemjan poika, joka Kuusin poika, ja käskivät sanoa: "Ota käteesi kirjakäärö, josta luit kansan kuullen, ja tule tänne." Niin Baaruk, Neerian poika, otti kirjakäärön käteensä ja meni heidän luokseen.',
        15: 'Silloin he sanoivat hänelle: "Istu ja lue meidän kuultemme", ja Baaruk luki heidän kuultensa.',
        16: 'Mutta kun he olivat kuulleet kaikki sanat, katsoivat he toisiinsa pelästyneinä ja sanoivat Baarukille: "Meidän täytyy ilmoittaa kuninkaalle kaikki nämä sanat."',
        17: 'Niin he kysyivät Baarukilta sanoen: "Ilmoita meille, kuinka sinä kirjoitit kaikki nämä sanat hänen suustaan."',
        18: 'Baaruk vastasi heille: "Hän saneli minulle suustaan kaikki nämä sanat, ja minä kirjoitin ne musteella kirjaan."',
        19: 'Ruhtinaat sanoivat Baarukille: "Mene ja piiloudu, sinä ja Jeremia, älköönkä kukaan saako tietää, missä olette."',
        20: 'Niin he menivät kuninkaan luo esipihaan, mutta kirjakäärön he jättivät talteen kirjuri Elisaman kammioon, ja he puhuivat kaikki nämä sanat kuninkaan kuullen.',
        21: 'Kuningas lähetti Jehudin hakemaan kirjakäärön, ja hän haki sen kirjuri Elisaman kammiosta. Jehudi luki sen kuninkaan kuullen ja kaikkien ruhtinaiden kuullen, jotka seisoivat kuninkaan edessä.',
        22: 'Mutta kuningas istui talvihuoneessa – oli yhdeksäs kuukausi – ja hänen edessään oli palamassa hiilipannu.',
        23: 'Aina kun Jehudi oli lukenut kolme tai neljä palstaa, leikkasi kuningas ne pois kirjurinveitsellä ja heitti tuleen, joka oli hiilipannussa, kunnes koko kirjakäärö oli palanut loppuun tulessa, joka oli hiilipannussa.',
        24: 'Mutta ei kuningas eikä kukaan hänen palvelijoistaan, jotka kuulivat kaikki nämä sanat, pelästynyt eikä reväissyt vaatteitaan.',
        25: 'Vaikka Elnatan, Delaja ja Gemarja olivat pyytäneet hartaasti kuningasta, ettei hän polttaisi kirjakääröä, hän ei heitä kuullut.',
        26: 'Kuningas käski Jerahmeelin, kuninkaan pojan, ja Serajan, Asrielin pojan, ja Selemjan, Abdeelin pojan, ottaa kiinni kirjuri Baarukin ja profeetta Jeremian, mutta Herra kätki heidät.',
        27: 'Mutta sen jälkeen kun kuningas oli polttanut kirjakäärön sekä sanat, jotka Baaruk oli kirjoittanut Jeremian suusta, Jeremialle tuli tämä Herran sana ja se kuului:',
        28: '"Ota vielä itsellesi toinen kirjakäärö ja kirjoita siihen kaikki entiset sanat, jotka olivat edellisessäkin kirjakäärössä, jonka Juudan kuningas Joojakim poltti.',
        29: "Sano Juudan kuninkaasta Joojakimista: Näin sanoo Herra: Sinä olet polttanut tämän kirjakäärön sanoen: 'Miksi olet kirjoittanut siihen näin: Baabelin kuningas on tuleva ja hävittävä tämän maan ja lopettava siitä ihmiset ja eläimet?'",
        30: 'Sen tähden Herra sanoo Juudan kuninkaasta Joojakimista näin: Hänellä ei ole oleva ketään, joka istuisi Daavidin valtaistuimella, ja hänen ruumiinsa heitetään pois virumaan päivän helteessä ja yön kylmyydessä.',
        31: 'Rankaisen häntä ja hänen jälkeläisiään ja hänen palvelijoitaan heidän pahojen tekojensa tähden. Annan tulla heille ja Jerusalemin asukkaille ja Juudan miehille kaiken sen onnettomuuden, jonka heille julistin, mutta jota he eivät kuulleet."',
        32: 'Sitten Jeremia otti toisen kirjakäärön ja antoi sen kirjuri Baarukille, Neerian pojalle; ja tämä kirjoitti siihen Jeremian suusta kaikki sen kirjan sanat, jonka Juudan kuningas Joojakim oli tulessa polttanut. Sitten niihin lisättiin vielä paljon samanlaisia sanoja.',
    },
    37: {
        1: 'Sidkia, Joosian poika, tuli kuninkaaksi Konjan, Joojakimin pojan, sijaan. Hänet Nebu-kadressar, Baabelin kuningas, asetti kuninkaaksi Juudan maahan.',
        2: 'Mutta ei hän eivätkä hänen palvelijansa eikä maan kansa totelleet Herran sanoja, jotka hän puhui profeetta Jeremian kautta.',
        3: 'Kuningas Sidkia lähetti Juukalin, Selemjan pojan, ja pappi Sefanjan, Maasejan pojan, profeetta Jeremian luo sanoen: "Rukoile puolestamme Herraa, Jumalaamme."',
        4: 'Silloin vielä Jeremia tuli ja meni kansan keskellä, sillä häntä ei ollut pantu vankilaan.',
        5: 'Faraon sotajoukko oli lähtenyt liikkeelle Egyptistä, mutta kun kaldealaiset, jotka piirittivät Jerusalemia, kuulivat siitä sanoman, he lähtivät pois Jerusalemin kimpusta.',
        6: 'Silloin tuli profeetta Jeremialle tämä Herran sana, ja se kuului:',
        7: '"Näin sanoo Herra, Israelin Jumala: Sanokaa näin Juudan kuninkaalle, joka on lähettänyt teidät luokseni kysymään minulta neuvoa: Katso, faraon sotajoukko, joka on lähtenyt avuksenne, palaa takaisin maahansa Egyptiin.',
        8: 'Sitten kaldealaiset tulevat takaisin ja sotivat tätä kaupunkia vastaan, valloittavat sen ja polttavat tulella.',
        9: "Näin sanoo Herra: Älkää pettäkö itseänne sanoen: 'Kaldealaiset varmasti lähtevät pois kimpustamme.' Sillä he eivät lähde.",
        10: 'Vaikka te voittaisitte koko kaldealaisten sotajoukon, joka sotii teitä vastaan, niin ettei heistä jäisi jäljelle kuin muutamia haavoitettuja miehiä, niin he nousisivat pystyyn kukin teltassaan ja polttaisivat tulella tämän kaupungin."',
        11: 'Mutta kun kaldealaisten sotajoukko faraon sotajoukon tähden oli lähtenyt pois Jerusalemia piirittämästä,',
        12: 'Jeremia lähti Jerusalemista mennäkseen Benjaminin maahan ottamaan jaossa osansa sieltä kansan keskuudesta.',
        13: 'Kun hän oli tullut Benjaminin portille, siinä oleva vartiopäällikkö, jonka nimi oli Jiiria, Selemjan, Hananjan pojan, poika, tarttui profeetta Jeremiaan sanoen: "Sinä aiot karata kaldealaisten puolelle."',
        14: 'Jeremia vastasi: "Se on valhe! Minä en karkaa kaldealaisten puolelle." Mutta Jiiria ei kuunnellut häntä, vaan otti Jeremian kiinni ja vei hänet ruhtinaiden luo.',
        15: 'Ruhtinaat vihastuivat Jeremiaan ja löivät häntä ja panivat hänet vankilaan kirjuri Joonatanin taloon, sillä he olivat tehneet siitä vankilan.',
        16: 'Jeremia joutui vankiluolaan ja holveihin, ja Jeremia jäi sinne moniksi päiviksi.',
        17: 'Kuningas Sidkia lähetti hakemaan häntä, ja kuningas kysyi häneltä salaa linnassaan ja sanoi: "Onko sanaa Herralta?" Jeremia vastasi: "On." Niin hän sanoi: "Sinut annetaan Baabelin kuninkaan käsiin."',
        18: 'Jeremia sanoi kuningas Sidkialle: "Mitä minä olen rikkonut sinua ja palvelijoitasi vastaan ja tätä kansaa vastaan, koska te olette panneet minut vankilaan?',
        19: "Missä ovat teidän profeettanne, jotka profetoivat teille sanoen: 'Baabelin kuningas ei tule teidän kimppuunne eikä tämän maan kimppuun'?",
        20: 'Kuule nyt, herrani kuningas, salli minun pyyntöni langeta eteesi äläkä lähetä minua takaisin kirjuri Joonatanin taloon sinne kuolemaan."',
        21: 'Kuningas Sidkia käski säilyttää Jeremiaa vankilan pihassa, ja hänelle annettiin leipäkakku päivässä Leipurienkadulta, kunnes kaikki leipä oli kaupungista loppunut. Jeremia jäi vankilan pihaan.',
    },
    38: {
        1: 'Mutta Sefatja, Mattanin poika, ja Gedalja, Pashurin poika, ja Juukal, Selemjan poika, ja Pashur, Malkian poika, kuulivat ne sanat, jotka Jeremia puhui kaikelle kansalle, ja ne kuuluivat:',
        2: '"Näin sanoo Herra: Se, joka jää tähän kaupunkiin, kuolee miekkaan, nälkään ja ruttoon. Mutta se, joka menee kaldealaisten luo, elää, pitää henkensä saaliinaan ja hän jää eloon.',
        3: 'Näin sanoo Herra: Tämä kaupunki totisesti annetaan Baabelin kuninkaan sotajoukon käsiin, ja hän valloittaa sen."',
        4: 'Ruhtinaat sanoivat kuninkaalle: "Tämä mies kuolkoon, sillä hän herpaisee niiden sotamiesten kädet, jotka ovat jäljellä tässä kaupungissa, ja kaiken kansan kädet, kun hän puhuu heille tällaisia sanoja. Sillä tämä mies ei etsi tämän kansan menestystä, vaan onnettomuutta."',
        5: 'Kuningas Sidkia vastasi: "Katso, hän on teidän käsissänne. Sillä eihän kuningas voi mitään teitä vastaan."',
        6: 'Silloin he ottivat Jeremian ja heittivät hänet Malkian, kuninkaan pojan, kaivoon, joka oli vankilan pihassa, laskivat Jeremian köysillä alas. Mutta kaivossa ei ollut vettä, vaan liejua, ja Jeremia vajosi liejuun.',
        7: 'Mutta kuusilainen Ebed-Melek, hoviherra, joka oli kuninkaan linnassa, kuuli, että he olivat panneet Jeremian kaivoon. Mutta kuningas istui Benjaminin portissa.',
        8: 'Niin Ebed-Melek lähti kuninkaan linnasta ja puhutteli kuningasta sanoen:',
        9: '"Herrani, kuningas! Nuo miehet ovat pahoin tehneet kaikessa, mitä ovat tehneet profeetta Jeremialle: he ovat heittäneet hänet kaivoon, kuolemaan nälkään siihen paikkaansa." Sillä kaupungissa ei ollut enää leipää.',
        10: 'Silloin kuningas käski kuusilaista Ebed-Melekiä sanoen: "Ota mukaasi täältä kolmekymmentä miestä ja nosta profeetta Jeremia kaivosta, ennen kuin hän kuolee."',
        11: 'Niin Ebed-Melek otti miehet mukaansa ja meni kuninkaan linnaan, aarrekammion alla olevaan paikkaan, ja otti sieltä rikkinäisiä ja kuluneita riepuja ja laski ne köysillä Jeremialle kaivoon.',
        12: 'Kuusilainen Ebed-Melek sanoi Jeremialle: "Pane nämä rikkinäiset ja kuluneet rievut kainaloihisi köysien alle", ja Jeremia teki niin.',
        13: 'He vetivät Jeremian ylös ja nostivat hänet kaivosta, ja Jeremia jäi vankilan pihaan.',
        14: 'Mutta kuningas Sidkia lähetti hakemaan profeetta Jeremian luokseen Herran temppelin kolmanteen sisäänkäytävään. Kuningas sanoi Jeremialle: "Minä kysyn sinulta jotakin. Älä salaa minulta mitään."',
        15: 'Jeremia vastasi Sidkialle: "Jos sinulle jotakin ilmoitan, sinä totisesti surmautat minut. Mutta jos sinua neuvon, et minua kuule."',
        16: 'Kuningas Sidkia vannoi salaa Jeremialle sanoen: "Niin totta kuin Herra elää, joka on luonut tämän meidän elämämme: minä en sinua surmauta enkä jätä sinua näiden miesten käsiin, jotka etsivät henkeäsi."',
        17: 'Silloin Jeremia sanoi Sidkialle: "Näin sanoo Herra, Jumala Sebaot, Israelin Jumala: Jos sinä tosiaan lähdet Baabelin kuninkaan ruhtinaiden luo, henkesi säilyy, eikä tätä kaupunkia polteta tulella, ja sinä ja huoneesi jäätte eloon.',
        18: 'Mutta jos et mene Baabelin kuninkaan ruhtinaiden luo, niin tämä kaupunki annetaan kaldealaisten käsiin, ja he polttavat sen tulella, etkä sinäkään pelastu heidän käsistään."',
        19: 'Silloin kuningas Sidkia sanoi Jeremialle: "Minä pelkään niitä juutalaisia, jotka ovat menneet kaldealaisten puolelle, pelkään, että minut jätetään heidän käsiinsä ja he pitävät minua pilkkanaan."',
        20: 'Mutta Jeremia sanoi: "Ei jätetä. Kuule vain Herran ääntä, kuule, mitä minä sinulle puhun, niin sinun käy hyvin, ja pysyt hengissä.',
        21: 'Mutta jos sinä et mene, niin tämä on se sana, jonka Herra on minulle näyttänyt:',
        22: "Katso, kaikki naiset, jotka ovat jäljellä Juudan kuninkaan linnassa, viedään Baabelin kuninkaan ruhtinaiden luokse, ja katso, he sanovat: 'Miesystäväsi ovat sinut viekoitelleet ja saaneet sinut valtaansa; sinun jalkasi vajosivat liejuun – he vetäytyivät pois.'",
        23: 'Niin kaikki sinun vaimosi ja lapsesi viedään kaldealaisille, etkä sinä pelastu näiden käsistä, vaan Baabelin kuninkaan käsi tarttuu sinuun, ja sinä saatat tämän kaupungin tulella poltettavaksi."',
        24: 'Silloin Sidkia sanoi Jeremialle: "Älköön kukaan saako tietää näistä sanoista, muuten sinä kuolet.',
        25: "Mutta jos ruhtinaat kuulevat, että minä olen puhunut kanssasi, ja tulevat luoksesi ja sanovat sinulle: 'Ilmoita meille, mitä olet puhunut kuninkaalle ja mitä kuningas on puhunut sinulle – älä salaa sitä meiltä, muuten me surmaamme sinut' –",
        26: 'niin sano heille: \'Minä annoin rukoukseni langeta kuninkaan eteen, ettei hän lähettäisi minua takaisin Joonatanin taloon, kuolemaan sinne.\'"',
        27: 'Kaikki ruhtinaat tulivat Jeremian luo ja kysyivät häneltä, ja hän ilmoitti heille kaiken, mitä kuningas oli käskenyt hänen ilmoittaa. He jättivät hänet rauhaan, sillä asiasta ei ollut mitään kuultu.',
        28: 'Jeremia jäi olemaan vankilan pihaan siihen päivään asti, jona Jerusalem valloitettiin.',
    },
    39: {
        1: 'Juudan kuninkaan Sidkian yhdeksäntenä hallitusvuotena, kymmenennessä kuussa, oli Nebukadressar, Baabelin kuningas, kaikkine sotajoukkoineen hyökännyt Jerusalemin kimppuun ja saartanut sen,',
        2: 'ja Sidkian yhdentenätoista hallitusvuotena, neljännessä kuussa, kuukauden yhdeksäntenä päivänä, kaupunki oli vallattu.',
        3: '– Niin kaikki Baabelin kuninkaan ruhtinaat tulivat ja asettuivat Keskiporttiin: Neergal-Sareser, Samgar-Nebo, Sarsekim, ylimmäinen hoviherra, Neergal-Sareser, ylimmäinen tietäjä, ja kaikki muut Baabelin kuninkaan ruhtinaat.',
        4: 'Kun Sidkia, Juudan kuningas, ja kaikki sotilaat näkivät heidät, he pakenivat ja lähtivät yöllä kaupungista kuninkaan puutarhaa kohti molempien muurien välisestä portista, ja hän lähti Aromaahan päin.',
        5: 'Mutta kaldealaisten sotajoukko ajoi heitä takaa, ja he saavuttivat Sidkian Jerikon aroilla. Niin he ottivat hänet kiinni ja veivät hänet Nebukadressarin, Baabelin kuninkaan, eteen Riblaan, joka on Hamatin maassa, ja tämä julisti hänelle tuomiot.',
        6: 'Baabelin kuningas surmautti Sidkian pojat Riblassa hänen silmiensä edessä. Myös kaikki Juudan ylimykset Baabelin kuningas surmautti.',
        7: 'Hän sokaisi Sidkian silmät ja sitoi hänet vaskikahleilla viedäkseen hänet Baabeliin.',
        8: 'Kuninkaan linnan ja kansan talot kaldealaiset polttivat tulella, ja Jerusalemin muurit he repivät maahan.',
        9: 'Loput kansasta, jotka olivat jäljellä kaupungissa, sekä ne, jotka olivat menneet hänen puolelleen – loput kansasta, jotka olivat jäljellä – vei Nebusaradan, henkivartijoiden päällikkö, karkotukseen Baabeliin.',
        10: 'Mutta köyhimmät kansasta, joilla ei ollut mitään, Nebusaradan, henkivartijoiden päällikkö, jätti Juudan maahan ja antoi heille sinä päivänä viinitarhoja ja peltoja.',
        11: 'Nebukadressar, Baabelin kuningas, oli antanut Nebusaradanille, henkivartijoiden päällikölle, Jeremiasta tämän käskyn:',
        12: '"Ota hänet ja pidä hänestä huoli. Älä tee hänelle mitään pahaa, vaan tee hänelle niin, kuin hän itse sinulle sanoo."',
        13: 'Silloin lähettivät Nebusaradan, henkivartijoiden päällikkö, Nebusasban, ylimmäinen hoviherra, Neergar-Sareser, ylimmäinen tietäjä, ja kaikki muut Baabelin kuninkaan päälliköt',
        14: '– nämä lähettivät noutamaan Jeremian vankilan pihasta ja antoivat hänet Gedaljalle, Saafanin pojan Ahikamin pojalle, että tämä veisi hänet kotiin, ja niin hän jäi kansan keskuuteen.',
        15: 'Jeremialle oli tullut tämä Herran sana hänen ollessaan suljettuna vankilan pihaan ja se kuului:',
        16: '"Mene ja sano kuusilaiselle Ebed-Melekille näin: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä toteutan sanani tälle kaupungille onnettomuudeksi enkä onneksi. Tämä tapahtuu sinun edessäsi sinä päivänä.',
        17: 'Mutta sinut pelastan sinä päivänä, sanoo Herra, etkä sinä joudu niiden miesten käsiin, joita pelkäät.',
        18: 'Sillä pelastan sinut, niin ettet kaadu miekkaan, vaan saat pitää henkesi saaliinasi, sillä sinä turvasit minuun, sanoo Herra."',
    },
    40: {
        1: 'Sana, joka tuli Jeremialle Herralta, sen jälkeen kun Nebusaradan, henkivartijoiden päällikkö, oli päästänyt hänet menemään Raamasta, jonne hän oli haettanut hänet, kun hän oli kahleilla sidottuna kaikkien Baabeliin siirrettävien Jerusalemin ja Juudan karkotettujen joukossa.',
        2: 'Henkivartijoiden päällikkö haetti Jeremian ja sanoi hänelle: " Herra, sinun Jumalasi, on julistanut tämän onnettomuuden tälle paikalle,',
        3: 'ja Herra on antanut sen tapahtua ja on tehnyt, kuten on puhunut. Sillä te olette tehneet syntiä Herraa vastaan ettekä ole kuulleet hänen ääntään, ja niin tämä sana kävi teille toteen.',
        4: 'Katso, nyt tänä päivänä päästän sinut kahleista, jotka ovat käsissäsi. Jos näet hyväksi lähteä kanssani Baabeliin, lähde, ja minä pidän sinusta huolen. Mutta jos et näe hyväksi lähteä kanssani Baabeliin, älä lähde. Katso, koko maa on edessäsi. Minne näet hyväksi ja oikeaksi mennä, sinne mene."',
        5: 'Mutta kun tämä ei ollut vielä lähtenyt takaisin, hän sanoi: "Palaa Gedaljan luo, joka on Saafanin pojan Ahikamin poika, hänen, jonka Baabelin kuningas on asettanut Juudan kaupunkien käskynhaltijaksi, ja jää hänen luokseen kansan keskuuteen, tai mene, minne vain näet oikeaksi mennä." Niin henkivartijoiden päällikkö antoi hänelle evästä ja lahjoja ja päästi hänet menemään.',
        6: 'Jeremia meni Gedaljan, Ahikamin pojan, luo Mispaan ja asui hänen luonaan maahan jääneen kansan keskuudessa.',
        7: 'Kun kaikki sotaväen päälliköt, jotka olivat maaseudulla, he ja heidän sotamiehensä, kuulivat, että Baabelin kuningas oli asettanut Gedaljan, Ahikamin pojan, käskynhaltijaksi maahan ja jättänyt hänen haltuunsa ne miehet, vaimot ja lapset sekä ne maan köyhät, joita ei ollut siirretty Baabeliin,',
        8: 'he tulivat Gedaljan luo Mispaan: Ismael, Netanjan poika, Joohanan ja Joonatan, Kaareahin pojat, Seraja, Tanhumetin poika, netofalaisen Eefain pojat ja Jesanja, maakatilaisen poika, he ja heidän sotamiehensä.',
        9: 'Gedalja, Saafanin pojan Ahikamin poika, vannoi heille ja heidän miehilleen sanoen: "Älkää pelätkö palvella kaldealaisia. Asukaa maassa ja palvelkaa Baabelin kuningasta, niin teidän käy hyvin.',
        10: 'Katso, minä itse asun Mispassa palvellakseni niitä kaldealaisia, jotka tulevat luoksemme. Mutta te kootkaa viiniä ja hedelmiä ja öljyä ja pankaa astioihinne ja asukaa kaupungeissanne, jotka olette ottaneet haltuunne."',
        11: 'Kaikki nekin juutalaiset, jotka olivat Mooabissa ja ammonilaisten keskuudessa ja Edomissa sekä kaikissa muissa maissa, saivat kuulla, että Baabelin kuningas oli jättänyt Juudaan jäännöksen ja asettanut näille käskynhaltijaksi Gedaljan, joka oli Saafanin pojan Ahikamin poika.',
        12: 'Kaikki juutalaiset palasivat takaisin kaikista paikoista, joihin heitä oli karkotettu, ja tulivat Juudan maahan Mispaan, Gedaljan luo, ja korjasivat viiniä ja hedelmiä hyvin runsaasti.',
        13: 'Mutta Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat maaseudulla, tulivat Gedaljan luo Mispaan',
        14: 'ja sanoivat hänelle: "Tiedätkö tosiaan, että ammonilaisten kuningas Baalis on lähettänyt Ismaelin, Netanjan pojan, lyömään sinut kuoliaaksi?" Mutta Gedalja, Ahikamin poika, ei uskonut heitä.',
        15: 'Silloin Joohanan, Kaareahin poika, sanoi Gedaljalle Mispassa salaa näin: "Minäpä menen ja lyön kuoliaaksi Ismaelin, Netanjan pojan, kenenkään tietämättä! Miksi hän saa lyödä sinut kuoliaaksi, niin että kaikki juutalaiset, jotka ovat kokoontuneet luoksesi, hajaantuvat ja Juudan jäännös hukkuu?"',
        16: 'Mutta Gedalja, Ahikamin poika, vastasi Joohananille, Kaareahin pojalle: "Älä tee mitä sanoit, sillä sinä puhut valhetta Ismaelista."',
    },
    41: {
        1: 'Mutta seitsemännessä kuussa Ismael, Elisaman pojan Netanjan poika, joka oli kuninkaallista sukua ja kuninkaan ylimmäisiä, tuli Gedaljan, Ahikamin pojan, luo Mispaan kymmenen miestä mukanaan. Siellä Mispassa he söivät leipää yhdessä.',
        2: 'Ismael, Netanjan poika, sekä ne kymmenen miestä, jotka olivat hänen kanssaan, nousivat ja he löivät miekalla kuoliaaksi Gedaljan, joka oli Saafanin pojan Ahikamin poika. Ismael surmasi hänet, jonka Baabelin kuningas oli asettanut käskynhaltijaksi maahan.',
        3: 'Myös kaikki juutalaiset, jotka olivat Gedaljan luona Mispassa, sekä kaldealaiset, jotka sieltä tavattiin, ja sotamiehet, Ismael löi kuoliaaksi.',
        4: 'Seuraavana päivänä, sen jälkeen kun hän oli surmannut Gedaljan, kun ei kukaan sitä vielä tietänyt,',
        5: 'Sikemistä, Siilosta ja Samariasta tuli kahdeksankymmentä miestä, parta ajettuna, vaatteet revittyinä ja iho viileskeltynä, ja heillä oli käsissään ruokauhreja ja suitsutusta vietäväksi Herran huoneeseen.',
        6: 'Niin Ismael, Netanjan poika, lähti Mispasta heitä vastaan itkien lakkaamatta kulkiessaan. Kun hän kohtasi heidät, hän sanoi heille: "Tulkaa Gedaljan, Ahikamin pojan, luo."',
        7: 'Mutta kun he olivat tulleet keskelle kaupunkia, Ismael, Netanjan poika, ja ne miehet, jotka olivat hänen kanssaan, surmasivat heidät ja heittivät heidät kaivoon.',
        8: 'Mutta heidän joukossaan oli kymmenen miestä, jotka sanoivat Ismaelille: "Älä surmaa meitä, sillä meillä on kedolla kätkössä vehnää, ohraa, öljyä ja hunajaa." Hän jätti sen tekemättä eikä surmannut heitä heidän veljiensä joukkoon.',
        9: 'Kaivo, johon Ismael heitti kaikkien niiden miesten ruumiit, jotka hän oli lyönyt kuoliaaksi Gedaljan tähden, oli se, jonka kuningas Aasa oli teettänyt Baesan, Israelin kuninkaan, pelosta. Sen Ismael, Netanjan poika, täytti nyt surmatuilla.',
        10: 'Sitten Ismael otti vangeiksi kaikki kansan tähteet, mitä Mispassa oli, kuninkaan tyttäret ja kaiken Mispaan jäljelle jääneen kansan, jonka käskynhaltijaksi Nebusaradan, henkivartijoiden päällikkö, oli asettanut Gedaljan, Ahikamin pojan. Heidät Ismael, Netanjan poika, otti vangeiksi ja lähti kulkemaan siirtyäkseen yli ammonilaisten luo.',
        11: 'Mutta Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, saivat kuulla kaiken sen pahan, minkä Ismael, Netanjan poika, oli tehnyt.',
        12: 'He ottivat kaikki miehensä ja lähtivät taistelemaan Ismaelia, Netanjan poikaa, vastaan, ja he tapasivat hänet suurilta vesiltä, jotka ovat Gibeonissa.',
        13: 'Mutta kun kaikki kansa, joka oli Ismaelin mukana, näki Joohananin, Kaareahin pojan, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, niin he ilahtuivat.',
        14: 'Niin kaikki kansa, jonka Ismael oli ottanut vangiksi Mispasta, kääntyi takaisin ja meni Joohananin, Kaareahin pojan, puolelle.',
        15: 'Mutta Ismael, Netanjan poika, pääsi kahdeksan miehen kanssa Joohanania pakoon ja lähti ammonilaisten luo.',
        16: 'Niin Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, ottivat kaikki kansan tähteet, jotka hän oli palauttanut Ismaelin, Netanjan pojan, luota Mispasta, sen jälkeen kun tämä oli lyönyt Gedaljan, Ahikamin pojan, kuoliaaksi. Heitä oli miehiä, sotilaita, naisia ja lapsia ja hoviherroja, jotka hän oli palauttanut Gibeonista.',
        17: 'Sitten he kulkivat, mutta pysähtyivät Kimhamin majapaikkaan, joka on lähellä Beetlehemiä, lähteäkseen Egyptiin',
        18: 'kaldealaisia pakoon, sillä he pelkäsivät heitä, koska Ismael, Netanjan poika, oli lyönyt kuoliaaksi Gedaljan, Ahikamin pojan, jonka Baabelin kuningas oli asettanut käskynhaltijaksi maahan.',
    },
    42: {
        1: 'Kaikki sotaväen päälliköt ja Joohanan, Kaareahin poika, ja Jesanja, Hoosajan poika, sekä kaikki kansa, pienimmästä suurimpaan, astuivat esiin',
        2: 'ja sanoivat profeetta Jeremialle: "Langetkoon pyyntömme eteesi, ja rukoile puolestamme Herraa, Jumalaasi, kaiken tämän jäännöksen puolesta, sillä suuresta luvusta meitä on jäänyt jäljelle vain vähän, niin kuin omat silmäsi näkevät meitä olevan.',
        3: 'Herra, sinun Jumalasi, ilmoittakoon meille, mitä tietä meidän on kuljettava, ja sanan, jota meidän on noudatettava."',
        4: 'Silloin profeetta Jeremia vastasi heille: "Minä kuulen. Katso, minä rukoilen Herraa, teidän Jumalaanne, niin kuin sanotte, ja kaiken sen, mitä Herra teille vastaa, ilmoitan teille enkä salaa teiltä mitään."',
        5: 'He sanoivat Jeremialle: "Olkoon Herra totuudellinen ja luotettava todistaja meitä vastaan, jos emme tee aivan sen sanan mukaan, jonka Herra, sinun Jumalasi, lähettää sinut meille tuomaan.',
        6: 'Olkoon se hyvä tai paha: Herran, meidän Jumalamme ääntä, jonka luo me sinut lähetämme, tottelemme, että meidän kävisi hyvin, kun tottelemme Herran, meidän Jumalamme, ääntä."',
        7: 'Kymmenen päivän kuluttua Herran sana tuli Jeremialle,',
        8: 'ja hän kutsui Joohananin, Kaareahin pojan, ja kaikki sotaväen päälliköt, jotka olivat tämän kanssa, sekä kaiken kansan, pienimmästä suurimpaan.',
        9: 'Hän sanoi heille: "Näin sanoo Herra, Israelin Jumala, jonka luo te lähetitte minut laskemaan rukouksenne hänen eteensä:',
        10: 'Jos tosiaan jäätte tähän maahan, rakennan teidät enkä hajota maahan, istutan teidät enkä revi pois, sillä kadun sitä onnettomuutta, jonka olen tuottanut teille.',
        11: 'Älkää pelätkö Baabelin kuningasta, jota te nyt pelkäätte. Älkää pelätkö häntä, sanoo Herra, sillä minä olen teidän kanssanne, minä autan teitä ja pelastan teidät hänen käsistään.',
        12: 'Annan teille armon, niin että hän armahtaa teitä ja antaa teidän palata takaisin maahanne.',
        13: "Mutta jos te sanotte: 'Me emme jää tähän maahan', ettekä tottele Herran, Jumalanne, ääntä,",
        14: "vaan sanotte: 'Ei! Menemme Egyptiin, jossa emme näe sotaa, kuule torven ääntä emmekä kärsi leivän nälkää, ja sinne me jäämme asumaan' –",
        15: 'niin kuulkaa siis nyt Herran sana, te Juudan tähteet: Näin sanoo Herra Sebaot, Israelin Jumala: Jos te todella käännätte kasvonne Egyptiä kohti ja menette sinne asumaan muukalaisina,',
        16: 'niin miekka, jota te pelkäätte, saavuttaa teidät siellä Egyptin maassa, ja nälkä, joka teitä huolettaa, seuraa perässänne Egyptiin, ja sinne te kuolette.',
        17: 'Kaikki ne miehet, jotka kääntävät kasvonsa Egyptiä kohti asuakseen siellä muukalaisina, kuolevat miekkaan, nälkään ja ruttoon, eikä kukaan heistä pääse pakoon eikä pelastu siitä onnettomuudesta, jonka minä annan heille tulla.',
        18: 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Niin kuin vihani ja kiivauteni on vuodatettu Jerusalemin asukasten päälle, niin kiivastukseni vuotaa teidänkin päällenne, jos menette Egyptiin, ja tulette kiroukseksi ja kauhistukseksi, kirosanaksi ja häväistykseksi ettekä enää näe tätä paikkaa.',
        19: 'Herra sanoo teille, te Juudan tähteet: Älkää menkö Egyptiin. Se tosiaan tietäkää, että olen tänä päivänä teitä varoittanut.',
        20: "Eksytitte itsenne, kun te lähetitte minut Herran, teidän Jumalanne, luo sanoen: 'Rukoile puolestamme Herraa, meidän Jumalaamme; ja kaikki, mitä Herra, meidän Jumalamme, sanoo, ilmoita meille, niin me teemme sen.'",
        21: 'Olen sen tänä päivänä teille ilmoittanut, mutta te ette kuulleet Herran, teidän Jumalanne, ääntä kaikessa, mitä varten hän lähetti minut teidän luoksenne.',
        22: 'Nyt siis totisesti tietäkää, että te kuolette miekkaan, nälkään ja ruttoon siinä paikassa, johon te haluatte mennä siellä muukalaisina asumaan.',
    },
    43: {
        1: 'Mutta kun Jeremia oli loppuun asti puhunut kaikelle kansalle kaikki Herran, heidän Jumalansa, sanat, jotka Herra, heidän Jumalansa, oli lähettänyt hänet tuomaan heille – kaikki ne sanat –,',
        2: 'niin Asarja, Hoosajan poika, ja Joohanan, Kaareahin poika, ja kaikki julkeat miehet sanoivat Jeremialle: "Sinä puhut valhetta. Herra, meidän Jumalamme, ei ole lähettänyt sinua sanomaan: \'Älkää menkö Egyptiin asumaan siellä muukalaisina\',',
        3: 'vaan Baaruk, Neerian poika, kiihottaa sinua meitä vastaan antaakseen meidät kaldealaisten käsiin tapettaviksi tai vietäviksi karkotukseen Baabeliin."',
        4: 'Joohanan, Kaareahin poika, kaikki sotaväen päälliköt ja kaikki kansa olivat tottelemattomia Herran äänelle eivätkä jääneet Juudan maahan.',
        5: 'Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt ottivat kaikki Juudan tähteet, jotka olivat kaikista kansakunnista, jonne heidät oli karkotettu, ja jotka olivat palanneet asumaan Juudan maahan:',
        6: 'miehet, naiset ja lapset, kuninkaan tyttäret ja kaiken sen väen, jonka Nebusaradan, henkivartijoiden päällikkö, oli jättänyt Gedaljan huostaan, joka oli Saafanin pojan Ahikamin poika, sekä profeetta Jeremian ja Baarukin, Neerian pojan.',
        7: 'He menivät Egyptin maahan, sillä he eivät kuulleet Herran ääntä, ja tulivat Tahpanheeseen.',
        8: 'Tämä Herran sana tuli Jeremialle Tahpanheessa, ja se kuului:',
        9: '"Ota käsiisi suuria kiviä ja kätke ne muurilaastiin, tiilikivipenkereeseen, joka on faraon linnan oven edustalla Tahpanheessa, juutalaisten miesten nähden.',
        10: 'Sano sitten heille: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä lähetän hakemaan palvelijani Nebukadressarin, Baabelin kuninkaan, ja asetan hänen valtaistuimensa näiden kivien päälle, jotka olen kätkenyt, ja hän panee niiden päälle kuninkaallisen paviljonkinsa.',
        11: 'Hän tulee ja lyö Egyptin maata: sitä, joka on oleva kuoleman oma, kuolemalla, sitä, joka on oleva vankeuden oma, vankeudella, ja miekalla sitä, joka on oleva miekan oma!',
        12: 'Sytytän Egyptin jumalien huoneet tuleen, ja Baabelin kuningas polttaa ne ja vie jumalat pois. Hän pukee päälleen Egyptin maan, niin kuin paimen pukeutuu vaatteeseensa, ja lähtee sieltä rauhassa.',
        13: 'Hän murskaa patsaat Egyptin maan Beet-Semeksestä, ja Egyptin jumalien huoneet hän polttaa tulella."',
    },
    44: {
        1: 'Sana, joka tuli Jeremialle kaikista niistä juutalaisista, jotka asuivat Egyptin maassa, nimittäin Migdolissa, Tahpanheessa, Noofissa ja Patroksen maakunnassa. Se kuului:',
        2: '"Näin sanoo Herra Sebaot, Israelin Jumala: Te olette nähneet kaiken sen onnettomuuden, jonka olen tuottanut Jerusalemille ja kaikille Juudan kaupungeille. Katso, ne ovat nyt raunioina, eikä niissä asu ketään,',
        3: 'heidän pahuutensa tähden, jota he tekivät, vihoittaen minut, kun menivät ja polttivat uhreja muille jumalille, palvelivat niitä, joita he eivät tunteneet, eivät he ettekä te eivätkä teidän isänne.',
        4: "Aamuvarhaisesta alkaen minä lähetin teidän luoksenne kaikki palvelijani, profeetat, sanomaan: 'Älkää tehkö näitä kauhistuksia, joita minä vihaan.'",
        5: 'Mutta he eivät kuulleet eivätkä sille korvaansa kallistaneet, niin että olisivat kääntyneet pois pahuudestaan ja lakanneet polttamasta uhreja muille jumalille.',
        6: 'Kiivauteni ja vihani vuoti alas ja paloi Juudan kaupungeissa ja Jerusalemin kaduilla, ja ne tulivat raunioiksi ja autioiksi, niin kuin ne tänä päivänä ovat.',
        7: 'Nyt sanoo Herra, Jumala Sebaot, Israelin Jumala, näin: Miksi te tuotatte itsellenne suuren onnettomuuden, hävitätte miehet ja vaimot, lapset ja imeväiset Juudasta ettekä jätä itsestänne jäännöstäkään?',
        8: 'Vihoitatte minut kättenne teoilla, kun poltatte uhreja muille jumalille Egyptin maassa, johon olette tulleet asumaan täällä muukalaisina. Niin tuotatte itsellenne häviön ja tulette kirosanaksi ja häväistykseksi kaikissa maan kansoissa.',
        9: 'Oletteko unohtaneet isienne pahat teot, Juudan kuningasten pahat teot ja heidän vaimojensa pahat teot, omat pahat tekonne ja vaimojenne pahat teot, joita he tekivät Juudan maassa ja Jerusalemin kaduilla?',
        10: 'He eivät ole murtuneet tähän päivään asti, eivät pelkää eivätkä vaella minun lakini ja minun käskyjeni mukaan, jotka olen antanut teille ja teidän isillenne.',
        11: 'Sen tähden, näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä käännän kasvoni teitä vastaan onnettomuudeksi hävittääkseni koko Juudan.',
        12: 'Tempaan pois Juudan jäännöksen, ne jotka käänsivät kasvonsa Egyptin maata kohti mennäkseen siellä asumaan muukalaisina, ja heistä kaikista tulee loppu Egyptin maassa. He kaatuvat miekkaan ja menehtyvät nälkään. Pienimmästä suurimpaan asti he kuolevat miekkaan ja nälkään ja tulevat kiroukseksi, kauhistukseksi, kirosanaksi ja häväistykseksi.',
        13: 'Rankaisen niitä, jotka asuvat Egyptin maassa, niin kuin rankaisin Jerusalemia, miekalla, nälällä ja rutolla.',
        14: 'Ei jää pakoon päässeitä, ei pelastuneita Juudan jäännöksestä, niistä, jotka ovat tulleet asumaan muukalaisina täällä Egyptin maassa, eivätkä he palaa Juudan maahan, jonne heidän sielunsa jälleen kaipaa heidän siellä asuakseen. Sinne on näet palaava vain muutamia pakolaisia."',
        15: 'Mutta kaikki miehet, jotka tiesivät vaimojensa polttavan uhreja muille jumalille, ja kaikki naiset, jotka seisoivat siellä suurena joukkona, ja kaikki kansa, joka asui Egyptin maassa, Patroksessa, vastasivat Jeremialle sanoen:',
        16: '"Sanaa, jonka puhuit meille Herran nimessä, emme siinä sinua tottele,',
        17: 'vaan me totisesti täytämme jokaisen lupauksen, mikä suustamme on lähtenyt, poltamme uhreja taivaan kuningattarelle ja vuodatamme hänelle juomauhreja, niin kuin teimme me ja meidän isämme, meidän kuninkaamme ja ruhtinaamme Juudan kaupungeissa ja Jerusalemin kaduilla. Silloin meillä oli leipää yltäkyllin, meidän oli hyvä olla emmekä nähneet onnettomuutta.',
        18: 'Mutta siitä asti, kun lakkasimme polttamasta uhreja taivaan kuningattarelle ja vuodattamasta hänelle juomauhreja, osanam-me on ollut kaiken puute ja kuoleminen miekkaan ja nälkään.',
        19: 'Kun poltamme uhreja taivaan kuningattarelle ja vuodatamme hänelle juomauhreja, teemmekö ilman miestemme lupaa hänelle uhrikakkuja, hänen kuvansa muotoisia, ja vuodatamme hänelle juomauhreja?"',
        20: 'Silloin Jeremia sanoi kaikelle kansalle, miehille ja naisille, kaikelle kansalle, joka oli hänelle näin vastannut:',
        21: '"Eikö sitä uhrisavua, jota olette suitsuttaneet Juudan kaupungeissa ja Jerusalemin kaduilla, te ja teidän isänne, teidän kuninkaanne ja ruhtinaanne ja maan kansa, Herra muista ja pidä mielessään?',
        22: 'Eikä Herra voinut sitä enää kärsiä teidän tekojenne pahuuden tähden, kauhistusten tähden, joita teitte, ja niin teidän maanne tuli raunioiksi ja autioksi ja kirosanaksi, tuli asumattomaksi, niin kuin se tänä päivänä on.',
        23: 'Sen tähden että te poltitte uhreja ja teitte syntiä Herraa vastaan, ette totelleet Herran ääntä ettekä vaeltaneet hänen lakinsa, käskyjensä ja todistustensa mukaan, sen tähden tämä onnettomuus on kohdannut teitä, niin kuin nyt on tapahtunut."',
        24: 'Jeremia sanoi vielä kaikelle kansalle ja kaikille naisille: "Kuulkaa Herran sana, kaikki Juuda, joka olet Egyptin maassa.',
        25: "Näin sanoo Herra Sebaot, Israelin Jumala: Mitä te ja teidän vaimonne olette suullanne puhuneet, sen te panette käsillänne täytäntöön, sanoen: 'Täytämme lupauksemme, joilla olemme luvanneet polttaa uhreja taivaan kuningattarelle ja vuodattaa hänelle juomauhreja.' Niinpä pitäkää lupauksenne, pankaa lupauksenne täytäntöön!",
        26: "Sen tähden kuulkaa Herran sana, kaikki Juuda, te jotka asutte Egyptin maassa: Katso, minä vannon suuren nimeni kautta, sanoo Herra: Totisesti yksikään Juudan mies ei ole enää mainitseva suullaan nimeäni, niin että sanoisi: 'Niin totta kuin Herra, Herra elää' – ei koko Egyptin maassa.",
        27: 'Katso, valvon, mutta heille onnettomuudeksi, en onneksi. Jokainen Juudan mies, joka on Egyptin maassa, hukkuu miekkaan ja nälkään, kunnes heistä on tullut loppu.',
        28: 'Vain vähäinen joukko miekasta pelastuneita palaa Egyptin maasta Juudan maahan. Silloin Juudan koko jäännös, ne jotka tulivat Egyptin maahan, asumaan siellä muukalaisina, tulevat tietämään, kumman sana toteutuu, minun vai heidän.',
        29: 'Tämä on oleva sen merkkinä, sanoo Herra, että minä rankaisen teitä tässä paikassa, tietääksenne, että minun sanani teitä vastaan tosiaan toteutuvat teille onnettomuudeksi:',
        30: 'Näin sanoo Herra: Katso, annan farao Hofran, Egyptin kuninkaan, hänen vihollistensa käsiin, niiden käsiin, jotka etsivät hänen henkeään, kuten annoin Sidkian, Juudan kuninkaan, Nebukadressarin, Baabelin kuninkaan, käsiin, joka oli hänen vihollisensa ja etsi hänen henkeään."',
    },
    45: {
        1: 'Sana, jonka profeetta Jeremia puhui Baarukille, Neerian pojalle, kun tämä kirjoitti nämä sanat kirjaan Jeremian suusta Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena. Se kuului:',
        2: '"Näin sanoo Herra, Israelin Jumala, sinusta, Baaruk:',
        3: "Sinä sanot: 'Voi minua! Sillä Herra on antanut minulle murhetta kipuni lisäksi; olen uupunut huokaamisestani enkä löydä lepoa.'",
        4: 'Sano hänelle näin: Näin sanoo Herra: Katso, minkä olen rakentanut, sen minä hajotan, ja minkä olen istuttanut, sen minä revin irti, ja se tapahtuu koko maalle.',
        5: 'Sinä pyydät itsellesi suuria! Älä pyydä, sillä katso, tuotan onnettomuuden kaikelle lihalle, sanoo Herra. Mutta sinulle annan henkesi saaliiksi joka paikassa minne menetkin."',
    },
    46: {
        1: 'Herran sana, joka tuli profeetta Jeremialle pakanakansoja koskien.',
        2: 'Egyptiä koskien: Farao Nekon, Egyptin kuninkaan, sotajoukkoa koskien, joka oli Eufrat-virran rannalla Karkemiissa ja jonka Nebukadressar, Baabelin kuningas, voitti Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena.',
        3: '"Pankaa kuntoon pienet ja suuret kilvet ja käykää taisteluun.',
        4: 'Valjastakaa hevoset, nouskaa ratsaille, käykää esiin kypärät päässä. Kiillottakaa keihäät ja pukekaa päällenne haarniskat.',
        5: 'Miksi näen heidän pelästyvän ja peräytyvän? Heidän sankarinsa sortuvat. He syöksyvät pakoon eivätkä käänny. Kauhu on kaikkialla, sanoo Herra.',
        6: 'Ei pääse nopea pakoon eikä sankari pelastu. Pohjoisessa Eufrat-virran luona he kompastuvat ja kaatuvat.',
        7: 'Mikä on tuo, joka nousee kuin Niili, jonka vedet vyöryvät kuin virrat?',
        8: "Egypti nousee kuin Niili, sen vedet vyöryvät kuin virrat; se sanoo: 'Minä nousen ja peitän maan, hävitän kaupungin ja sen asukkaat.'",
        9: 'Hyökätkää, hevoset, ajakaa hurjasti, vaunut! Lähtekööt liikkeelle sankarit, kuusilaiset ja puutilaiset, kilven käyttäjät, ja luudilaiset, jousen käyttäjät ja jousen jännittäjät!',
        10: 'Tämä päivä on Herran, Herran Sebaotin, päivä, koston päivä, jona hän kostaa vihollisilleen. Miekka syö, tulee kylläiseksi ja juopuu heidän verestään, kun Herralla, Herralla Sebaotilla, on uhriteurastus pohjoisessa maassa Eufrat-virran luona.',
        11: 'Nouse Gileadiin, hae balsamia, sinä neitsyt, tytär Egypti – turhaan sinä hankit paljon lääkkeitä: sinä et parane.',
        12: 'Kansat kuulevat häpeäsi, ja valitushuutosi täyttää maan, sillä sankari kompastuu sankariin ja yhdessä he molemmat kaatuvat."',
        13: 'Tämä on se sana, jonka Herra puhui profeetta Jeremialle ja ilmoitti Nebukadressarin, Baabelin kuninkaan, tulevan lyömään Egyptin maata.',
        14: '"Julistakaa Egyptissä ja kuuluttakaa Migdolissa, kuuluttakaa Noofissa ja Tahpanheessa, ja sanokaa: \'Astu esiin, ole valmis, sillä miekka syö ympärilläsi.\'',
        15: 'Miksi sankarisi ovat syöstyt maahan? He eivät pysyneet pystyssä, sillä Herra ajoi heidät pois.',
        16: "Hän saattoi monet kompastumaan, ja he kaatuivat toinen toisensa päälle ja sanoivat: 'Nouse! Palatkaamme kansamme luo ja synnyinmaahamme hävittäjän miekkaa pakoon.'",
        17: "Siellä huudetaan: 'Farao, Egyptin kuningas, on hämillään! Hän on päästänyt määräaikansa menemään.'",
        18: 'Niin totta kuin minä elän, sanoo kuningas – Herra Sebaot on hänen nimensä: hän tulee, hän joka on kuin Taabor vuorten joukossa ja kuin Karmel meren rannalla.',
        19: 'Tee itsellesi varusteet karkotusta varten, sinä Egyptissä asuva tytär, sillä Noof tulee autioksi ja hävitetään niin, ettei siinä ole asukkaita.',
        20: 'Hyvin kaunis nuori lehmä on Egypti. Paarma tulee pohjoisesta, se tulee!',
        21: 'Palkkasoturitkin, jotka sillä on keskellänsä, nuo syöttövasikoitten kaltaiset, kääntyvät nekin pakoon kaikki yhdessä. He eivät kestä. Heidän onnettomuutensa päivä on näet tullut heille ja on heidän rangaistuksensa aika.',
        22: 'Ne pitävät mennessään ääntä kuin käärme, sillä ne tulevat sotavoimalla ja käyvät sen kimppuun kirveillä kuin puunkaatajat.',
        23: 'He kaatavat siltä metsän, sanoo Herra, tuon määrättömän suuren, sillä heitä on enemmän kuin heinäsirkkoja, ja he ovat lukemattomat.',
        24: 'Häpeään joutuu tytär Egypti, hänet annetaan pohjoisen kansan käsiin.',
        25: 'Herra Sebaot, Israelin Jumala, sanoo: Katso, rankaisen Aamonia, joka on Noossa, niin myös faraota ja Egyptiä, sen jumalia ja sen kuninkaita, sekä faraota että niitä, jotka häneen turvaavat.',
        26: 'Annan heidät niiden käsiin, jotka etsivät heidän henkeään, Nebukadressarin, Baabelin kuninkaan, käsiin ja hänen palvelijoidensa käsiin. Mutta sen jälkeen siellä asutaan kuin entisinä aikoina, sanoo Herra.',
        27: 'Mutta sinä, palvelijani Jaakob, älä pelkää, älä arkaile, Israel. Sillä katso, pelastan sinut kaukaa ja jälkeläisesi heidän vankeutensa maasta. Jaakob palaa, elää rauhassa ja on turvassa eikä sillä ole pelättävää.',
        28: 'Sinä, palvelijani Jaakob, älä pelkää, sanoo Herra, sillä minä olen kanssasi. Teen lopun kaikista kansoista, joiden sekaan sinut karkotin. Mutta sinusta en tee loppua. Kuritan sinua kohtuudella, mutta rankaisematta en sinua jätä."',
    },
    47: {
        1: 'Herran sana filistealaisia vastaan, joka tuli profeetta Jeremialle, ennen kuin farao valloitti Gassan:',
        2: '"Näin sanoo Herra: Katso, vedet nousevat pohjoisesta, ja niistä tulee tulvavirta. Ne tulvivat yli maan ja kaiken, mitä siinä on, yli kaupungin ja sen asukkaiden. Ihmiset huutavat ja kaikki maan asukkaat valittavat.',
        3: 'Kun kuuluu hänen hevostensa kavioiden töminä, hänen vaunujensa jyrinä ja hänen rattaittensa ryske, isät eivät käänny lastensa puoleen, sillä heidän kätensä ovat hervottomat',
        4: 'päivän tähden, joka tulee ja tuhoaa kaikki filistealaiset, hävittää Tyyrolta ja Siidonilta kaikki auttajat, mitä on jäljellä. Herra on näet tuhoava filistealaiset, kaikki, mitä on jäljellä Kaftorin saarelta tulleista.',
        5: 'Kaljuksi on tullut Gassa, hävitetty on Askelon ja se mitä oli jäljellä heidän laaksossaan. Kuinka kauan sinä viileskelet ihoasi?',
        6: 'Voi, Herran miekka! Milloin vihdoinkin lepäät? Mene takaisin tuppeesi, asetu ja ole hiljaa.',
        7: 'Mutta kuinka se saisi levätä, kun Herra on antanut sille käskyn? Askelonia ja meren rantaa vastaan hän on sen asettanut."',
    },
    48: {
        1: 'Mooabista. Näin sanoo Herra Sebaot, Israelin Jumala: "Voi Neboa, sillä se on hävitetty! Häpeään joutunut, vallattu on Kirjataim, häpeään ja kauhun valtaan on joutunut vuorilinna.',
        2: "Enää ei ylistetä Mooabia, Hesbonissa suunnitellaan sille pahaa: 'Tulkaa hävittäkäämme se kansojen luvusta.' Myös sinä, Madmena, kukistut, miekka kulkee perässäsi.",
        3: 'Valittava ääni kuluu Hooronaimista! Tuho ja suuri hävitys!',
        4: 'Hävitetty on Mooab, sen pienokaisten parku kuuluu.',
        5: 'He nousevat itkien Luuhitiin, ja Hooronaimin rinteeltä kuuluu tuskan huuto hävityksen tähden.',
        6: 'Paetkaa, pelastakaa henkenne ja olkaa kuin Aroer erämaassa.',
        7: 'Sillä koska turvaat omiin tekoihisi ja aarteisiisi, sinutkin vallataan, ja Kemos lähtee karkotukseen ja hänen pappinsa ja ruhtinaansa hänen kanssaan.',
        8: 'Hävittäjä tulee jokaiseen kaupunkiin, eikä yksikään kaupunki pelastu. Laakso hävitetään ja tasanko tuhotaan, niin kuin Herra on puhunut.',
        9: 'Antakaa siivet Mooabille, sillä lentämällä on hänen lähdettävä pois. Hänen kaupunkinsa tulevat autioiksi, niin ettei niissä ole yhtään asukasta.',
        10: 'Kirottu olkoon se, joka tekee Herran työn laiskasti, kirottu olkoon se, joka pidättää miekkansa verestä.',
        11: 'Suruttomana on Mooab ollut nuoruudestaan asti ja levännyt rauhassa sakkansa päällä. Sitä ei ole tyhjennetty astiasta astiaan, eikä se ole karkotukseen vaeltanut. Sen tähden siihen on jäänyt sen oma maku, eikä sen haju ole muuttunut.',
        12: 'Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin lähetän sille viininlaskijat, jotka sitä laskevat ja tyhjentävät sen astiat ja rikkovat sen leilit.',
        13: 'Silloin Mooab joutuu häpeään Kemoksen tähden, niin kuin Israelin heimo joutui häpeään Beetelin tähden, johon se turvasi.',
        14: "Kuinka te sanotte: 'Me olemme sankareita ja vahvoja miehiä taisteluun'?",
        15: 'Mooab on hävitetty, sen kaupunkeihin on hyökätty, ja sen valionuorukaiset ovat voipuneet teurastettaviksi, sanoo kuningas – Herra Sebaot on hänen nimensä.',
        16: 'Lähellä tulossa on Mooabin hävitys. Sen onnettomuus tulee kovalla kiireellä.',
        17: "Surkutelkaa sitä, kaikki sen naapurit, ja kaikki te, jotka tunnette sen nimen. Sanokaa: 'Voi, kuinka onkaan murrettu voiman valtikka, kunnian sauva!'",
        18: 'Astu alas kunniasta ja istu janoiseen maahan, sinä valtiatar, tytär Diibon, sillä Mooabin hävittäjä hyökkää kimppuusi ja kukistaa linnoituksesi.',
        19: "Seiso tiellä ja tähystele, sinä Aroerin asukas; kysy pakolaisilta ja pelastuneilta, sano: 'Mitä on tapahtunut?'",
        20: 'Häpeään on joutunut Mooab, sillä se on kukistettu. Valittakaa ja huutakaa, julistakaa Arnonilla, että Mooab on hävitetty.',
        21: "Tuomio on tullut tasangon maalle, Hoolonille, Jahaalle ja Meefaa'atille,",
        22: 'Diibonille, Nebolle ja Beet-Diblataimille,',
        23: 'Kirjataimille, Beet-Gaamulille ja Beet-Meonille,',
        24: 'Kerijotille, Bosralle ja kaikille Mooabin maan kaupungeille, kaukaisille ja läheisille.',
        25: 'Katkaistu on Mooabin sarvi ja murskattu hänen käsivartensa, sanoo Herra.',
        26: 'Juovuttakaa hänet, sillä hän on ylpeillyt Herraa vastaan, niin että Mooab suistuu omaan oksennukseensa ja tulee hänkin naurunalaiseksi.',
        27: 'Vai eikö Israel ollut sinulle nauruksi? Onko hänet tavattu varkaiden joukosta, koska sinä, milloin vain hänestä puhuit, pudistit päätäsi?',
        28: 'Jättäkää kaupungit ja asukaa kallioilla, te Mooabin asukkaat, ja olkaa kuin kyyhkynen, joka tekee pesänsä ammottavan kuilun taakse.',
        29: 'Me olemme kuulleet Mooabin ylpeilyn, tuon hyvin ylpeän, hänen korskeutensa, ylpeilynsä ja kopeilunsa ja hänen sydämensä pöyhkeyden.',
        30: 'Minä tunnen, sanoo Herra, hänen ylimielisyytensä ja hänen tyhjät puheensa ja toisenlaiset tekonsa.',
        31: 'Siksi valitan Mooabin tähden, koko Mooabin tähden minä huudan. Kiir-Hereksen miesten tähden huokaillaan.',
        32: 'Itken sinua, Jaeser, itken sinua, Sibman viinipuu. Sinun köynnöksiäsi meni yli meren, Jaeserin merelle asti. Sinun hedelmän- ja viininkorjuuseesi on hävittäjä hyökännyt.',
        33: 'Ilo ja riemu on otettu pois hedelmätarhoista ja Mooabin maasta. Viinin olen lopettanut viinikuurnista. Enää ei poljeta viiniä ilohuudoin eikä ilohuuto ole enää ilohuuto.',
        34: 'Hesbonin parku kuuluu Elaleen, Jahaaseen asti. Heidän valituksensa kuuluu Sooarista Hooronaimiin, Eglat-Selisijjaan asti, jopa kolmivuotisesta lehmästä, sillä Nimrimin vedet ehtyvät erämaaksi.',
        35: 'Lopetan Mooabista, sanoo Herra, kukkuloilla-uhraajat, ne, jotka polttavat uhreja jumalilleen.',
        36: 'Siksi sydämeni valittaa Mooabin tähden kuin huilu, sydämeni valittaa Kiir-Hereksen miesten tähden kuin huilu, sillä hävinnyt on heidän hankkimansa rikkaus.',
        37: 'Sillä kaikki päät ovat paljaiksi ajettuja, kaikki parrat leikattuja, kaikki kädet viileskeltyjä, ja lanteilla on säkit.',
        38: 'Kaikilla Mooabin katoilla ja toreilla on pelkkää valitusta, sillä olen murskannut Mooabin kuin kelpaamattoman astian, sanoo Herra.',
        39: 'Miten murskattu se onkaan! Valittakaa! Kuinka Mooab kääntyikään selin ja häpesi! Mooab on tullut nauruksi ja kauhuksi kaikille naapureilleen.',
        40: 'Sillä näin sanoo Herra: Katso, kotkan kaltainen liitelee siivet levitettyinä Mooabia kohti.',
        41: 'Kerijotin ovat ottaneet haltuunsa ja vuorilinnat on vallattu. Sinä päivänä on Mooabin sankarien sydän kuin synnytystuskissa olevan vaimon sydän.',
        42: 'Silloin Mooab hävitetään kansakuntien joukosta, sillä se on ylpeillyt Herraa vastaan.',
        43: 'Kauhu, kuoppa ja ansa ovat edessäsi, sinä Mooabin asukas, sanoo Herra.',
        44: 'Joka pakenee kauhua, se putoaa kuoppaan, ja joka kuopasta nousee, se tarttuu ansaan. Sillä saatan Mooabille heidän rangaistusvuotensa, sanoo Herra.',
        45: 'Hesbonin varjossa seisovat pakolaiset voimaa vailla. Sillä tuli lähti Hesbonista, liekki Siihonista, ja se kulutti Mooabin ohimon ja kapinoivien miesten päälaen.',
        46: 'Voi sinua, Mooab! Hukkunut on Kemoksen kansa, sillä poikasi on otettu vangeiksi ja tyttäresi on viety vankeuteen.',
        47: 'Mutta käännän Mooabin kohtalon viimeisinä päivinä, sanoo Herra." Tähän asti Mooabin tuomiosta.',
    },
    49: {
        1: 'Ammonilaisista. Näin sanoo Herra: "Eikö Israelilla olekaan lapsia, tai eikö hänellä ole perillistä? Miksi Malkam on perinyt Gaadin ja hänen kansansa on asettunut sen kaupunkeihin?',
        2: 'Sen tähden, katso, päivät tulevat, sanoo Herra, jolloin annan sotahuudon kuulua ammonilaisten Rabbaa vastaan, ja siitä on tuleva autio rauniokumpu, ja sen tytärkaupungit palavat tulessa. Israel on perivä perijänsä, sanoo Herra.',
        3: 'Valita, Hesbon, sillä Ai on hävitetty. Huutakaa, te Rabban tyttäret, kääriytykää säkkeihin, pitäkää valittajaiset ja kuljeskelkaa ympäriinsä tarhoissa, sillä Malkam menee karkotukseen ja hänen pappinsa ja ruhtinaansa hänen kanssaan.',
        4: "Miksi kerskut laaksoistasi? Laaksosi ovat virranneet tyhjiin, sinä luopiotytär, joka luotat aarteisiisi sanoen: 'Kuka käy kimppuuni?'",
        5: 'Katso, tuotan sinulle kauhun joka taholta, sanoo Herra, Herra Sebaot, ja teidät karkotetaan, kuka minnekin, eikä pakenevilla ole kokoajaa.',
        6: 'Mutta sen jälkeen käännän ammonilaisten kohtalon, sanoo Herra."',
        7: 'Edomista. Näin sanoo Herra Sebaot: "Eikö ole enää viisautta Teemanissa? Hävinnyt on ymmärtäväisiltä neuvo, ja loppunut on heidän viisautensa.',
        8: 'Paetkaa, kääntykää, piiloutukaa syvälle, te Dedanin asukkaat, sillä tuotan Eesaulle onnettomuuden, kun hänen rangaistuksensa aika tulee.',
        9: 'Jos viininkorjaajat tulevat luoksesi, he eivät jätä jälkikorjuuta. Jos varkaat tulevat yöllä, he hävittävät, kunnes heillä on kylliksi.',
        10: 'Sillä paljastan Eesaun, tuon ilmi hänen kätkönsä, eikä hän voi piiloutua. Hänen lapsensa, veljensä ja naapurinsa hävitetään, niin ettei häntä enää ole.',
        11: 'Jätä orposi minun elätettävikseni, ja leskesi turvatkoot minuun.',
        12: 'Sillä näin sanoo Herra: Katso, niidenkin, jotka eivät ole tuomitut juomaan siitä maljasta, täytyy siitä juoda, ja sinäkö jäisit rankaisematta? Sinä et jää rankaisematta, vaan sinun täytyy juoda.',
        13: 'Sillä olen vannonut itseni kautta, sanoo Herra, että Bosra on tuleva kauhuksi, häpeäksi, tyrmistykseksi ja kirosanaksi, ja kaikki sen tytärkaupungit tulevat ikuisiksi raunioiksi."',
        14: 'Olen kuullut sanoman Herralta, ja sanansaattaja on lähetetty kansakuntiin: "Kokoontukaa ja käykää sitä vastaan ja nouskaa sotaan." –',
        15: '"Sillä katso, teen sinut vähäiseksi kansojen seassa ja halveksituksi ihmisten keskuudessa.',
        16: 'Sinun pelottavuutesi, sydämesi ylpeys on pettänyt sinut, joka asut kallion rotkoissa ja vallitset kukkuloiden korkeudet. Vaikka tekisit pesäsi korkealle kuin kotka, syöksen sinut sieltä alas, sanoo Herra.',
        17: 'Edom tulee kauhistukseksi; jokainen ohikulkija kauhistuu ja viheltää kaikille sen haavoille.',
        18: 'Kuten Sodoman ja Gomorran ja niiden naapurien tultua hävitetyiksi, sanoo Herra, niin ei täälläkään kukaan ole asuva eikä yksikään ihmislapsi oleskeleva.',
        19: 'Katso, niin kuin leijona syöksyy ylös Jordanin tiheiköstä lakastumattomalle laitumelle, niin äkisti karkotan heidät sieltä pois. Sen, joka on valittu, asetan sinne kaitsijaksi. Sillä kuka on minun vertaiseni, ja kuka vetää minut tilille? Kuka on se paimen, joka voi kestää edessäni?',
        20: 'Sen tähden kuulkaa Herran päätös, jonka hän on päättänyt Edomista, ja hänen ajatuksensa, jotka hän on ajatellut Teemanin asukkaista: Totisesti, lauman vähäisimmät raastetaan pois. Totisesti, hän tekee autioiksi heidän asuinpaikkansa.',
        21: 'Heidän sortumisensa pauhusta järisee maa. Huudetaan, niin että ääni kuuluu Kaislamerelle asti.',
        22: 'Katso, kotkan kaltainen kohoaa ja liitelee siivet levitettyinä Bosraa kohti. Sinä päivänä on Edomin sankarien sydän kuin synnytystuskissa olevan vaimon sydän."',
        23: 'Damaskosta. "Hamat ja Arpad joutuvat häpeään, sillä he kuulevat pahan sanoman ja ovat epätoivoisia – on levottomuus meressä, joka ei voi tyyntyä!',
        24: 'Damasko lannistuu, kääntyy pakoon, kauhu on sen vallannut. Sillä on kova ahdistus ja tuska kuin synnyttäjällä!',
        25: 'Kuinka hyljeksitty onkaan ylistetty kaupunki, minun iloni kaupunki!',
        26: 'Sen tähden sen nuorukaiset kaatuvat sen kaduilla, ja kaikki sotamiehet saavat surmansa sinä päivänä, sanoo Herra Sebaot.',
        27: 'Sytytän Damaskon muurit tuleen, ja se on kuluttava Benhadadin palatsit."',
        28: 'Keedarin ja Haasorin valtakunnasta, jotka Nebukadressar, Baabelin kuningas, kukisti. Näin sanoo Herra: "Nouskaa, käykää Keedarin kimppuun ja hävittäkää se, te Idän miehet.',
        29: "Heidän telttansa ja lampaansa otetaan pois, heidän kankaansa, kaikki heidän tavaransa ja kamelinsa viedään heiltä, ja heistä huudetaan: 'Kauhu kaikkialla!'",
        30: 'Lähtekää pakoon, paetkaa nopeasti, piiloutukaa syvälle, te Haasorin asukkaat, sanoo Herra, sillä Nebukadressar, Baabelin kuningas, on päättänyt teitä vastaan päätöksen, ja on pitänyt neuvoa teitä vastaan.',
        31: 'Nouskaa, käykää kansan kimppuun, joka asuu rauhassa ja turvallisena, sanoo Herra. Sillä ei ole ovia eikä salpoja, he asuvat yksinään.',
        32: 'Heidän kamelinsa joutuvat ryöstettäviksi ja heidän karjansa paljous saaliiksi, ja he tulevat hajotetuiksi kaikkiin tuuliin, nuo, joiden tukka on ohimoilta leikattu, ja joka puolelta tuotan heille turmion, sanoo Herra.',
        33: 'Haasor tulee sakaalien asunnoksi, autioksi iankaikkisesti. Kukaan ei ole siellä asuva, ei yksikään ihmislapsi siellä oleskeleva."',
        34: 'Herran sana, joka tuli profeetta Jeremialle Eelamista Juudan kuninkaan Sidkian hallituksen alussa ja joka kuului:',
        35: '"Näin sanoo Herra Sebaot: Katso, murran Eelamin jousen, heidän parhaimman voimansa.',
        36: 'Tuon Eelamia vastaan neljä tuulta taivaan neljältä ääreltä ja hajotan heidät kaikkiin näihin tuuliin. Ei ole oleva kansaa, johon ei tulisi Eelamin karkotettuja.',
        37: 'Saatan Eelamin kauhistumaan vihollistensa edessä, niiden edessä, jotka etsivät heidän henkeään, ja annan onnettomuuden kohdata heitä, vihani hehkun, sanoo Herra, ja lähetän heidän jälkeensä miekan, kunnes heidät lopetan.',
        38: 'Asetan valtaistuimeni Eelamiin ja hävitän sieltä kuninkaan ja ruhtinaat, sanoo Herra.',
        39: 'Mutta aikojen lopulla käännän Eelamin kohtalon, sanoo Herra."',
    },
    50: {
        1: 'Sana, jonka Herra puhui Baabelista, se on, kaldealaisten maasta, profeetta Jeremian kautta:',
        2: '"Julistakaa kansojen keskuudessa ja kuuluttakaa, nostakaa lippu; kuuluttakaa, älkää salatko. Sanokaa: Baabel on vallattu, Beel on joutunut häpeään, kukistettu on Merodak. Sen jumalankuvat ovat joutuneet häpeään ja sen epäjumalat ovat maahan murskatut.',
        3: 'Sillä sen kimppuun käy kansa pohjoisesta ja tekee sen maan autioksi, niin ettei siellä ole asukasta, ja ihmiset ja eläimet pakenevat ja menevät pois.',
        4: 'Niinä päivinä ja siihen aikaan, sanoo Herra, tulevat israelilaiset yhdessä Juudan miesten kanssa. He kulkevat itkien ja etsivät Herraa, Jumalaansa.',
        5: 'Siionia he kysyvät, sitä kohden he kääntävät kasvonsa. Tulkaa! He liittyvät Herran kanssa iankaikkiseen liittoon, jota ei unohdeta.',
        6: 'Kadonnut lammaslauma oli kansani. Heidän paimenensa olivat vieneet heidät harhaan ja ajoivat heidät eksyksiin vuorilla. He kulkivat vuorelta kukkulalle ja unohtivat lepopaikkansa.',
        7: "Kaikki, jotka heitä tapasivat, söivät heitä, ja heidän vihollisensa sanoivat: 'Emme ole syyllisiä, sillä he ovat tehneet syntiä Herraa vastaan, vanhurskauden asumusta, Herraa, heidän isiensä toivoa, vastaan.'",
        8: 'Paetkaa Baabelin keskeltä ja lähtekää kaldealaisten maasta, ja käykää kuin vuohipukit lauman edellä.',
        9: 'Sillä katso, minä herätän ja nostan Baabelia vastaan suurten kansojen joukon pohjoisesta maasta, ja ne asettuvat sitä vastaan. Sieltä käsin se vallataan. Heidän nuolensa ovat kuin menestyvän sankarin, joka ei palaa tyhjin toimin.',
        10: 'Mutta Kaldea joutuu ryöstettäväksi, kaikki sen ryöstäjät saavat kyllikseen, sanoo Herra.',
        11: 'Iloitkaa vain, riemuitkaa vain, te perintöosani riistäjät, hypelkää kuin puiva hieho, ja hirnukaa kuin oriit:',
        12: 'kuitenkin äitinne joutuu suureen häpeään, synnyttäjänne saa hävetä. Katso, pakanakansoista viimeinen! Erämaa, kuiva maa ja aromaa!',
        13: 'Herran vihan tähden se on oleva asumaton, aivan autio. Jokainen, joka kulkee Baabelin ohi, kauhistuu ja viheltää kaikille sen haavoille.',
        14: 'Asettukaa rintamaan Baabelia vastaan, joka puolelta, kaikki jousimiehet. Ampukaa sitä, älkää nuolia säästäkö, sillä se on tehnyt syntiä Herraa vastaan.',
        15: 'Nostakaa sotahuuto sitä vastaan joka taholta. Se on ojentanut kätensä, sen pylväät ovat kaatuneet, sen muurit sortuneet. Sillä tämä on Herran kosto. Kostakaa sille, tehkää sille, niin kuin sekin on tehnyt.',
        16: 'Tuhotkaa kylväjät Baabelista ja ne, jotka elonkorjuun aikana sirppiin tarttuvat. Hävittäjän miekkaa pakoon he kääntyvät kukin oman kansansa luo ja pakenevat kukin omaan maahansa.',
        17: 'Israel on hajotettu lammaslauma, leijonat ovat sen ajaneet hajalle. Ensiksi Assurin kuningas söi sen, ja nyt viimeksi Nebukadressar, Baabelin kuningas, murskasi sen luut.',
        18: 'Sen tähden, näin sanoo Herra Sebaot, Israelin Jumala: Katso, rankaisen Baabelin kuningasta ja hänen maatansa, niin kuin rankaisin Assurin kuningasta.',
        19: 'Tuon Israelin takaisin sen omille laidunmaille, ja se on käyvä laitumella Karmelilla ja Baasanissa ja hänen sielunsa tulee ravituksi Efraimin vuorilla ja Gileadissa.',
        20: 'Niinä päivinä ja siihen aikaan, sanoo Herra, etsitään Israelin rikosta, eikä sitä enää ole, ja Juudan syntiä, eikä sitä löydetä, sillä annan anteeksi niille, jotka jätän jäännökseksi.',
        21: 'Käy niskurimaan kimppuun ja niiden asukkaiden kimppuun, joita kohtaa kosto. Hyökkää, hävitä heidän jälkeläisensä, sanoo Herra, ja tee kaikki, mitä olen käskenyt sinun tehdä.',
        22: 'Sotahuuto kuuluu maassa, ja on suuri hävitys!',
        23: 'Kuinka rikottu ja särjetty onkaan se vasara, joka löi kaikkea maata! Kuinka onkaan Baabel tullut kauhistavaksi kansojen seassa!',
        24: 'Viritin sinulle pyydyksen, ja niin sinut, Baabel, vangittiin tietämättäsi. Sinut tavoitettiin ja otettiin kiinni, sillä sinä nousit vastustamaan Herraa.',
        25: 'Herra on avannut varastonsa ja tuonut esiin vihansa aseet. Sillä Herra, Herra Sebaot, on tekevä työnsä kaldealaisten maassa.',
        26: 'Käykää sen kimppuun äärimmäisiltä rajoilta, avatkaa sen aitat, heittäkää ulos, mitä siinä on, pankaa ne läjiin kuin lyhteet. Vihkikää se tuhon omaksi, älköön siitä tähteitä jääkö.',
        27: 'Hävittäkää kaikki sen härät, astukoot ne teurastettaviksi. Voi heitä! Sillä heidän päivänsä on tullut, heidän rangaistuksensa aika.',
        28: 'Kuule! Pakenevia ja pakolaisia tulee Baabelin maasta Siioniin ilmoittamaan Herran, meidän Jumalamme, kostoa, kostoa hänen temppelinsä tähden.',
        29: 'Kutsukaa ampujat, kaikki jousimiehet, kokoon Baabelia vastaan: leiriytykää sen ympärille, älköön yksikään pääskö pakoon. Maksakaa sille sen tekojen mukaan. Kaiken sen mukaan, mitä se on tehnyt, tehkää sillekin. Sillä se on pöyhkeillyt Herraa, Israelin Pyhää vastaan.',
        30: 'Sen tähden sen nuorukaiset kaatuvat sen kaduilla, ja kaikki sotamiehet saavat surmansa sinä päivänä, sanoo Herra.',
        31: 'Katso, käyn kimppuusi, sinä ylpeä, sanoo Herra, Herra Sebaot, sillä päiväsi, rangaistuksesi aika, on tullut.',
        32: 'Ylpeä kompastuu ja kaatuu, eikä ole hänen nostajaansa. Sytytän hänen kaupunkinsa tuleen, ja se kuluttaa ne ja kaiken hänen ympäriltään.',
        33: 'Näin sanoo Herra Sebaot: Sorrettuja ovat israelilaiset ja myös Juudan miehet yhdessä heidän kanssaan, ja kaikki heidän vangitsijansa pitävät heistä kiinni, he eivät suostu päästämään heitä irti.',
        34: 'Mutta heidän lunastajansa on voimakas, Herra Sebaot on hänen nimensä. Hän toden totta ajaa heidän asiansa ja tuo rauhan maahan, mutta vapinan Baabelin asukkaille.',
        35: 'Miekka kaldealaisten kimppuun, sanoo Herra, ja Baabelin asukkaiden kimppuun, sen ruhtinaiden ja tietäjien kimppuun!',
        36: 'Miekka tyhjänpuhujien kimppuun, ja he käyvät typeriksi! Miekka sen sankarien kimppuun, ja he kauhistuvat!',
        37: 'Miekka sen hevosten ja vaunujen kimppuun ja kaiken sekakansan kimppuun, joka on sen keskellä, ja he tulevat naisiksi! Miekka sen aarteiden kimppuun, ja ne ryöstetään!',
        38: 'Helle sen vetten kimppuun, ja ne kuivuvat! Sillä se on jumalankuvien maa, ja he pöyhkeilevät kauheista epäjumalistaan.',
        39: 'Sen tähden sen asukkaiksi tulevat erämaan eläimet ja sakaalit, ja strutsit siellä asuvat. Siellä ei ikinä enää asuta, autioksi se jää polvesta polveen.',
        40: 'Niin kuin oli silloin, kun Jumala hävitti Sodoman ja Gomorran ja niiden naapurit, sanoo Herra, niin ei sielläkään ole kukaan asuva, ei yksikään ihmislapsi oleskeleva.',
        41: 'Katso, kansa tulee pohjoisesta: suuri kansa ja monet kuninkaat nousevat maan ääristä.',
        42: 'He tarttuvat jouseen ja keihääseen, ovat julmia ja armahtamattomia. Heidän äänensä on kuin pauhaava meri, ja he ratsastavat hevosilla, varustettuina kuin soturi taisteluun sinua vastaan, tytär Baabel.',
        43: 'Kun Baabelin kuningas kuulee sanoman heistä, niin hänen kätensä vaipuvat. Ahdistus valtaa hänet kuin tuska synnyttäjän.',
        44: 'Katso, niin kuin leijona syöksyy Jordanin tiheiköstä lakastumattomalle laitumelle, niin karkotan äkkiä heidät sieltä pois. Sen, joka on siihen valittu, asetan sinne kaitsijaksi. Sillä kuka on minun vertaiseni, ja kuka vetää minut tilille? Kuka on se paimen, joka kestää edessäni?',
        45: 'Sen tähden kuulkaa Herran päätös, jonka hän on päättänyt Baabelia vastaan, ja hänen ajatuksensa, jotka hänellä on kaldealaisten maata vastaan: Totisesti, ne raastetaan pois, nuo lauman vähäiset. Hän totisesti tekee autioksi heidän asuinsijansa.',
        46: 'Baabelin valtauksen äänestä maa vapisee ja valitus kuuluu kansoissa."',
    },
    51: {
        1: 'Näin sanoo Herra: "Katso, minä herätän hävittäjän hengen Baabelia vastaan, ja niitä asukkaita vastaan, jotka ovat nousseet minua vastustamaan.',
        2: 'Lähetän Baabeliin muukalaisia, jotka hajottavat sen ja tyhjentävät maan, sillä joka taholta he tulevat sitä vastaan onnettomuuden päivänä.',
        3: 'Jousimies jännittäköön jousensa sitä vastaan, joka jousen jännittää, ja sitä vastaan, joka ylpeilee haarniskassaan. Älkää säälikö sen nuorukaisia, vihkikää tuhon omaksi koko sen sotajoukko.',
        4: 'Haavoitettuja kaatuu kaldealaisten maassa ja lävistettyjä sen kaduilla.',
        5: 'Sillä ei Israel eikä Juuda ole Jumalansa, Herran Sebaotin, hylkäämä, vaikka noiden maa on täynnä syntivelkaa Israelin Pyhän edessä.',
        6: 'Paetkaa Baabelin keskeltä ja pelastakoon kukin henkensä, ettei hukkuisi sen syntiin. Sillä tämä on Herran koston aika, hän maksaa sille, mitä se on ansainnut.',
        7: 'Baabel oli Herran kädessä kultamalja, joka juovutti kaiken maan. Sen viinistä joivat kansat. Sen tähden kansat käyttäytyivät kuin mielettömät.',
        8: 'Äkkiä Baabel on kaatunut ja murskaantunut. Valittakaa hänen tähtensä! Pankaa balsamia hänen kipuunsa, ehkä hän paranee.',
        9: "'Olemme parantaneet Baabelia, mutta se ei ole parantunut. Jättäkää se, ja menkäämme pois kukin omalle maalleen, sillä sen tuomio ulottuu taivaaseen asti ja kohoaa pilviin saakka.",
        10: "Herra on tuonut ilmi vanhurskautemme. Tulkaa, julistakaamme Siionissa Herran, meidän Jumalamme, tekoja.'",
        11: 'Terottakaa nuolet, täyttäkää viinikotelot! Herra on herättänyt Meedian kuningasten hengen, sillä hänen ajatuksensa käy Baabelia vastaan sen hävittämiseksi. Tämä on Herran kosto, kosto hänen temppelinsä puolesta.',
        12: 'Kohottakaa lippu Baabelin muureja vastaan, vahvistakaa vartiosto, asettakaa vartijat, valmistakaa väijytykset; sillä mitä Herra on ajatellut, sen hän tekeekin, sen, minkä hän on puhunut Baabelin asukkaista.',
        13: 'Sinä, joka asut suurten vetten varrella, joka olet aarteista rikas, loppusi on tullut, ahneutesi mitta on täysi.',
        14: 'Herra Sebaot on vannonut itsensä kautta. Totisesti, täytän sinut ihmisillä niin kuin heinäsirkoilla, ja he virittävät sinusta voittolaulun.',
        15: 'Hän on tehnyt maan voimallaan, vahvistanut maanpiirin viisaudellaan ja levittänyt taivaat taidollaan.',
        16: 'Kun hän antaa äänensä kuulua, käy vetten pauhina taivaalla, ja hän nostaa pilvet maan ääristä, tekee salamat ja sateen ja tuo tuulen sen säilytyspaikoista.',
        17: 'Typerä on jokainen ihminen ja tietoa vailla, häpeän saa jokainen kultaseppä veistetystä kuvasta, petosta on hänen valamansa kuva, eikä niissä ole henkeä.',
        18: 'Turhuutta ne ovat, naurettavia tekeleitä. Kun niiden rangaistus tulee, ne hukkuvat.',
        19: 'Näiden kaltainen ei ole Jaakobin osa, sillä hän on kaiken luoja, ja Jaakob on hänen perintösukunsa: Herra Sebaot on hänen nimensä.',
        20: 'Sinä olit minun vasarani, minun sota-aseeni, sinulla musersin kansoja, sinulla hävitin valtakuntia.',
        21: 'Sinulla muserran hevosen ja ratsastajan, sinulla muserran vaunut ja ajajan.',
        22: 'Muserran sinulla miehen ja aviovaimon, muserran sinulla vanhan ja nuoren, sinulla muserran nuorukaisen ja neitsyen.',
        23: 'Muserran sinulla paimenen ja hänen laumansa, muserran sinulla peltomiehen ja hänen juhtaparinsa, muserran sinulla käskynhaltijat ja päälliköt.',
        24: 'Kostan Baabelille ja kaikille Kaldean asukkaille kaiken sen pahan, minkä he ovat tehneet Siionille teidän silmienne edessä, sanoo Herra.',
        25: 'Katso, käyn kimppuusi, sinä hävityksen vuori, joka hävitit koko maan, sanoo Herra. Ojennan käteni sinua vastaan ja vieritän sinut alas kalliolta ja teen sinusta poltetun vuoren.',
        26: 'Eikä sinusta oteta enää kulmakiveä eikä kiveä perustusta varten, vaan sinä jäät ikuisesti autioksi, sanoo Herra.',
        27: 'Nostakaa lippu maassa, puhaltakaa torveen kansoissa, vihkikää kansat häntä vastaan, kutsukaa häntä vastaan Araratin, Minnin ja Askenaan valtakunnat, asettakaa päällikkö häntä vastaan, antakaa tulla hevosia kuin pörröisiä heinäsirkkoja.',
        28: 'Vihkikää kansoja häntä vastaan, Meedian kuninkaat, sen käskynhaltijat ja kaikki päälliköt ja koko sen valtaan kuuluva maa.',
        29: 'Maa järisee ja vääntelehtii, sillä Herran ajatukset toteutuvat Baabelia vastaan: hän tekee Baabelin maan autioksi, jossa ei ole asukkaita.',
        30: 'Baabelin sankarit lakkaavat taistelemasta, he istuvat linnoituksissaan, heidän voimansa on voipunut, he ovat muuttuneet naisiksi. Sen asunnot on poltettu ja sen salvat rikottu.',
        31: 'Juoksija juoksee juoksijaa vastaan, sanantuoja sanantuojaa vastaan ilmoittamaan Baabelin kuninkaalle, että hänen kaupunkinsa on vallattu reunasta toiseen,',
        32: 'ylikulkupaikat ovat vallatut, linnoitukset ovat tulella poltetut ja sotamiehet ovat kauhun vallassa.',
        33: 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Tytär Baabel on kuin puimatanner puintiaikaan. Vielä vähän aikaa niin sen elonkorjuuaika tulee.',
        34: 'Nebukadressar, Baabelin kuningas, on minua syönyt ja sortanut minua, pannut syrjään kuin tyhjän astian. Hän on niellyt minut kuin lohikäärme, täyttänyt vatsansa herkuillani ja huuhtonut minut pois.',
        35: "'Kärsimäni väkivalta ja lihani tulkoon Baabelin päälle', sanoo Siionin asukas. 'Vereni tulkoon Kaldean asukasten päälle', sanoo Jerusalem.",
        36: 'Sen tähden näin sanoo Herra: Katso, ajan asiasi ja kostan kostosi. Kuivaan hänen virtansa ja ehdytän hänen lähteensä.',
        37: 'Baabelista tulee kivikasa, sakaalien asuinpaikka, kauhistus, jolle vihellellään ja jossa ei ole asukkaita.',
        38: 'He karjahtelevat yhdessä kuin nuoret leijonat, murisevat kuin naarasleijonien pennut.',
        39: 'Heidän kiihkoonsa teen heille juomingit ja juovutan heidät, että he riemastuvat ja nukahtavat hyvin pitkään uneen eivätkä enää herää, sanoo Herra.',
        40: 'Vien heidät teurastettaviksi, kuin karitsat, kuin pässit pukkien kanssa.',
        41: 'Kuinka onkaan vallattu Seesak, vallattu tuo, jota koko maailma ylisti! Kuinka onkaan Baabelista tullut kauhistus kansojen joukossa!',
        42: 'Meri nousi Baabelin yli, sen aaltojen pauhuun se peittyi.',
        43: 'Sen kaupungit ovat tulleet autioiksi, kuivaksi maaksi ja aromaaksi, maaksi, jossa ei asu ketään, josta ihmislapsi ei kulje.',
        44: 'Kostan Beelille Baabelissa ja vedän ulos hänen suustaan sen, mitä hän on niellyt, eivätkä kansat enää virtaa hänen luokseen. Baabelin muurikin on kaatunut.',
        45: 'Lähde pois sen keskuudesta, kansani, ja pelastakoon kukin henkensä Herran vihan hehkusta.',
        46: 'Älköön sydämenne voipuko, älkää pelätkö sanomaa, joka kuuluu maassa, kun tänä vuonna tulee sanoma ja sitten toisenakin vuonna sanoma, kun maassa on väkivaltaa ja hallitsija on hallitsijaa vastaan.',
        47: 'Sen tähden katso, päivät tulevat, jolloin kostan Baabelin jumalankuville, ja koko sen maa joutuu häpeään ja kaikki sen surmatut kaatuvat sen keskellä.',
        48: 'Baabelin kohtalosta riemuitsevat taivas ja maa ja kaikki, mitä niissä on, kun sen surmatut saapuvat pohjoisesta, sanoo Herra.',
        49: 'Baabelinkin on kaatuminen, te Israelin surmatut, kuten Baabelin tähden kaatui surmattuja kautta koko maan.',
        50: 'Te miekasta pelastuneet, menkää, älkää seisahtuko, muistakaa Herraa kaukana ja pitäkää mielessänne Jerusalem.',
        51: "'Häpeämme, sillä kuulemme pilkkaa. Häpeä peittää kasvomme, sillä muukalaiset ovat käyneet käsiksi Herran huoneen pyhyyksiin.'",
        52: 'Sen tähden katso, päivät tulevat, sanoo Herra, jolloin kostan sen jumalankuville ja sen maa on täynnä kuolettavasti haavoittuneiden valitusta.',
        53: 'Vaikka Baabel astuisi ylös taivaaseen, vaikka se vahvistaisi korkeuteen linnansa, sittenkin tulevat sille minulta hävittäjät, sanoo Herra.',
        54: 'Valitushuuto Baabelista, suuri hävitys kuuluu kaldealaisten maasta!',
        55: 'Sillä Herra hävittää Baabelin ja lopettaa sieltä suuren melun. Heidän aaltonsa pauhaavat kuin suuret vedet, niiden äänestä nousee kohina.',
        56: 'Sillä hävittäjä käy Baabelin kimppuun, ja sen sankarit vangitaan, heidän jousensa murretaan, sillä Herra on koston Jumala. Hän vaatii täyden koston.',
        57: 'Minä juovutan sen ruhtinaat ja tietäjät, sen käskynhaltijat, päämiehet ja sankarit; ja he nukkuvat hyvin pitkään uneen eivätkä herää, sanoo Kuningas; Herra Sebaot on hänen nimensä.',
        58: 'Näin sanoo Herra Sebaot: Baabelin leveä muuri hajotetaan maahan, ja sen korkeat portit poltetaan tulella. Niin ovat tehneet kansat työtä tyhjän tähden, kansakunnat tulen hyväksi, ja väsyttäneet itsensä tulen hyväksi."',
        59: 'Asia, jonka profeetta Jeremia käski Serajaa, Neerian poikaa, joka oli Mahsejan poika, toimittamaan, kun tämä lähti Sidkian, Juudan kuninkaan, kanssa Baabeliin hänen neljäntenä hallitusvuotenaan. Seraja oli majoituspäällikkö.',
        60: 'Jeremia kirjoitti kaiken sen onnettomuuden, joka oli tuleva Baabelille, yhteen kirjaan, kaikki nämä sanat, jotka ovat kirjoitetut Baabelista.',
        61: 'Jeremia sanoi Serajalle: "Kun tulet Baabeliin, niin katso, että luet kaikki nämä sanat.',
        62: 'Sano: Herra, sinä olet puhunut tätä paikkaa vastaan. Sinä olet hävittävä sen, niin ettei siinä ole asukasta, ei ihmistä eikä eläintä, vaan se jää ikuiseksi erämaaksi.',
        63: 'Kun olet lukenut tämän kirjan loppuun, sido siihen kivi ja viskaa se keskelle Eufratia,',
        64: 'ja sano: Näin uppoaa Baabel eikä nouse enää siitä onnettomuudesta, jonka minä sille tuotan, vaan he voipuvat." Näin pitkälle Jeremian sanat.',
    },
    52: {
        1: 'Sidkia oli kahdenkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.',
        2: 'Hän teki sitä, mikä on pahaa Herran silmissä, samoin kuin Joojakim oli tehnyt.',
        3: 'Sillä Herran vihan tähden kävi näin Jerusalemille ja Juudalle, kunnes hän heitti heidät pois kasvojensa edestä.',
        4: 'Sidkia kapinoi Baabelin kuningasta vastaan. Hänen yhdeksäntenä hallitusvuotenaan, sen kymmenennessä kuussa, kuukauden kymmenentenä päivänä, tuli Nebukadressar, Baabelin kuningas, koko sotajoukollaan Jerusalemia vastaan, ja he asettuivat leiriin sitä vastaan ja rakensivat saartovarusteet sitä vastaan sen ympärille.',
        5: 'Näin kaupunkia piiritettiin kuningas Sidkian yhdenteentoista hallitusvuoteen asti.',
        6: 'Mutta neljännessä kuussa, kuukauden yhdeksäntenä päivänä, kun nälänhätä ahdisti kaupunkia eikä maan kansalla ollut leipää,',
        7: 'kaldealaiset mursivat kaupungin muuriin aukon, ja kaikki sotilaat pakenivat ja lähtivät ulos kaupungista yöllä molempien muurien välitse vievää porttitietä, joka on kuninkaan puutarhan puolella, kaldealaisten ollessa kaupungin ympärillä, ja he kulkivat Aromaan tietä.',
        8: 'Mutta kaldealaisten sotajoukko ajoi kuningasta takaa, ja he saavuttivat Sidkian Jerikon aroilla, mutta koko hänen sotajoukkonsa oli jättänyt hänet ja hajaantunut hänen luotaan.',
        9: 'He ottivat kuninkaan kiinni ja veivät hänet Baabelin kuninkaan eteen Riblaan, joka on Hamatin maassa, ja tämä julisti hänelle tuomiot.',
        10: 'Baabelin kuningas surmasi Sidkian pojat hänen silmiensä edessä, ja myös kaikki Juudan ruhtinaat hän surmasi Riblassa.',
        11: 'Mutta Sidkialta Baabelin kuningas sokaistutti silmät, kytki hänet vaskikahleisiin ja vei hänet Baabeliin, ja hän pani hänet vankihuoneeseen, jossa hän oli kuolinpäiväänsä asti.',
        12: 'Viidennessä kuussa, kuukauden kymmenentenä päivänä, Baabelin kuninkaan Nebukadressarin yhdeksäntenätoista hallitusvuotena, tuli Nebusaradan, henkivartijoiden päällikkö, joka oli Baabelin kuninkaan palveluksessa, Jerusalemiin.',
        13: 'Hän poltti Herran huoneen ja kuninkaan talon ja kaikki Jerusalemin talot. Kaikki ylhäisten ruhtinaitten talot hän poltti tulella.',
        14: 'Koko kaldealaisten sotajoukko, joka henkivartijoiden päälliköllä oli mukanaan, repi maahan kaikki Jerusalemin muurit joka puolelta ympäriinsä.',
        15: 'Niin Nebusaradan, henkivartijoiden päällikkö, siirsi maasta pois osan kansan köyhiä ja kansan tähteitä, mitä oli jäljellä kaupungissa, sekä ne, jotka olivat menneet Baabelin kuninkaan puolelle, ja loput käsityöläisistä.',
        16: 'Mutta osan maan köyhiä Nebusaradan, henkivartijoiden päällikkö, jätti jäljelle viinitarhureiksi ja peltomiehiksi.',
        17: 'Vaskipylväät, jotka olivat Herran huoneessa, altaiden telineet ja vaskimeren, jotka olivat Herran huoneessa, kaldealaiset särkivät ja veivät kaiken niissä olevan vasken Baabeliin.',
        18: 'Kattilat, lapiot, veitset, maljat, kupit ja kaikki vaskiesineet, joita siinä käytettiin, he veivät pois.',
        19: 'Henkivartijoiden päällikkö vei puolestaan vadit, hiilipannut, maljat, kattilat, lampunjalat, kupit ja kulhot, jotka olivat kokonaan kultaa tai hopeaa.',
        20: 'Hän vei myös molemmat pylväät, meren ja niiden kaksitoista vaskista härkää, jotka olivat telineiden alla – kaikki ne esineet, jotka Salomo oli teettänyt Herran temppeliin ja joiden vaski ei ollut punnittavissa.',
        21: 'Pylväistä oli toisen pylvään korkeus kahdeksantoista kyynärää, ja kahdentoista kyynärän pituinen nauha ulottui sen ympäri. Sen vahvuus oli neljä sormenleveyttä. Se oli ontto.',
        22: 'Sen päässä oli pylväänpää vaskesta. Toisen pylväänpään korkeus oli viisi kyynärää, ja pylväänpään päällä oli ristikko ja granaattiomenia ympäriinsä, kaikki vaskea. Samanlaiset oli toisessa pylväässä sekä granaattiomenat.',
        23: 'Granaattiomenia oli yhdeksänkymmentä kuusi ulospäin. Kaikkiaan oli granaattiomenia sata ristikon päällä ympäriinsä.',
        24: 'Henkivartijoiden päällikkö otti ylimmäisen papin Serajan ja kakkospapin Sefanjan sekä kolme ovenvartijaa,',
        25: 'ja kaupungista hän otti yhden hoviherran, joka oli sotaväen tarkastaja, ja seitsemän miestä, jotka palvelivat kuningasta hänen edessään ja jotka tavattiin kaupungista, sekä sotapäällikön kirjurin, jonka tehtävänä oli ottaa maan kansaa sotapalvelukseen, ja kuusikymmentä miestä maan kansasta, jotka tavattiin kaupungista.',
        26: 'Nämä Nebusaradan, henkivartijoiden päällikkö otti ja vei heidät Baabelin kuninkaan eteen Riblaan.',
        27: 'Baabelin kuningas löi heidät kuoliaaksi Riblassa Hamatin maassa. Juuda siirrettiin pois maastaan.',
        28: 'Tämä on se kansa, jonka Nebukadressar vei karkotukseen: seitsemäntenä vuotena kolmetuhatta kaksikymmentä kolme juutalaista,',
        29: 'Nebukadressarin kahdeksantenatoista hallitusvuotena kahdeksansataa kolmekymmentä kaksi henkeä Jerusalemista.',
        30: 'Nebukadressarin kahdentenakymmenentenä kolmantena hallitusvuotena vei Nebusaradan, henkivartijoiden päällikkö, seitsemänsataa neljäkymmentä viisi juutalaista karkotukseen – yhteensä neljätuhatta kuusisataa henkeä.',
        31: 'Mutta kolmantenakymmenentenä seitsemäntenä vuotena siitä, kun Joojakin, Juudan kuningas, oli viety karkotukseen, kahdennessatoista kuussa, kuukauden kahdentenakymmenentenä viidentenä päivänä, korotti Evil-Merodak, Baabelin kuningas, samana vuonna, jona hän tuli kuninkaaksi, Juudan kuninkaan Joojakinin pään ja päästi hänet vankilasta.',
        32: 'Hän puhutteli häntä ystävällisesti ja asetti hänen istuimensa ylemmäksi muiden kuninkaiden istuimia, jotka olivat hänen luonaan Baabelissa.',
        33: 'Hän vaihtoi pois vanginpuvun ja aterioi aina hänen luonaan, niin kauan kuin eli.',
        34: 'Hän sai Baabelin kuninkaalta elatuksensa, vakinaisen elatuksen, mitä kunakin päivänä tarvitsi, kuolinpäiväänsä asti, niin kauan kuin eli.',
    },
}
